QW.lxloaded(17,{"ظلم":{"mf":"الظُّلْمَةُ: عدمُ النّور، وجمعها: ظُلُمَاتٌ. قال تعالى: أَوْ كَظُلُماتٍ فِي بَحْرٍ لُجِّيٍ<br>[النور/ ٤٠]، ظُلُماتٌ بَعْضُها فَوْقَ بَعْضٍ<br>[النور/ ٤٠]، وقال تعالى: أَمَّنْ يَهْدِيكُمْ فِي ظُلُماتِ الْبَرِّ وَالْبَحْرِ [النمل/ ٦٣]، وَجَعَلَ الظُّلُماتِ وَالنُّورَ<br>[الأنعام/ ١]، ويعبّر بها عن الجهل والشّرك والفسق، كما يعبّر بالنّور عن أضدادها.<br>قال الله تعالى: يُخْرِجُهُمْ مِنَ الظُّلُماتِ إِلَى النُّورِ<br>[البقرة/ ٢٥٧]، أَنْ أَخْرِجْ قَوْمَكَ مِنَ الظُّلُماتِ إِلَى النُّورِ [إبراهيم/ ٥]، فَنادى فِي الظُّلُماتِ [الأنبياء/ ٨٧]، كَمَنْ مَثَلُهُ فِي الظُّلُماتِ [الأنعام/ ١٢٢]، هو كقوله:<br>كَمَنْ هُوَ أَعْمى [الرعد/ ١٩]، وقوله في سورة الأنعام: وَالَّذِينَ كَذَّبُوا بِآياتِنا صُمٌّ وَبُكْمٌ فِي الظُّلُماتِ [الأنعام/ ٣٩]، فقوله: فِي الظُّلُماتِ<br>هاهنا موضوع موضع العمى في قوله: صُمٌّ بُكْمٌ عُمْيٌ [البقرة/ ١٨]، وقوله: فِي ظُلُماتٍ ثَلاثٍ<br><strong>[الزمر/ ٦]، أي:</strong><br>البطن والرّحم والمشيمة، وَأَظْلَمَ فلانُ: حصل في ظُلْمَةٍ. قال تعالى: فَإِذا هُمْ مُظْلِمُونَ<br>[يس/ ٣٧]، وَالظُّلْمُ عند أهل اللّغة وكثير من العلماء: وضع الشيء في غير موضعه المختصّ به، إمّا بنقصان أو بزيادة، وإمّا بعدول عن وقته أو مكانه، ومن هذا يقال: ظَلَمْتُ السِّقَاءَ: إذا تناولته في غير وقته، ويسمّى ذلك اللّبن الظَّلِيمَ.<br>وظَلَمْتُ الأرضَ: حفرتها ولم تكن موضعا للحفر، وتلك الأرض يقال لها: المَظْلُومَةُ، والتّراب الّذي يخرج منها: ظَلِيمٌ. والظُّلْمُ يقال في مجاوزة الحقّ الذي يجري مجرى نقطة الدّائرة، ويقال فيما يكثر وفيما يقلّ من التّجاوز، ولهذا يستعمل في الذّنب الكبير، وفي الذّنب الصّغير، ولذلك قيل لآدم في تعدّيه ظالم <strong>«٣»</strong>، وفي إبليس ظالم، وإن كان بين الظُّلْمَيْنِ بون بعيد. قال بعض الحكماء: الظُّلْمُ ثلاثةٌ:<br>الأوّل: ظُلْمٌ بين الإنسان وبين الله تعالى، وأعظمه: الكفر والشّرك والنّفاق، ولذلك قال:<br>إِنَّ الشِّرْكَ لَظُلْمٌ عَظِيمٌ<br>[لقمان/ ١٣]، وإيّاه<br><br>قصد بقوله: أَلا لَعْنَةُ اللَّهِ عَلَى الظَّالِمِينَ<br>[هود/ ١٨]، وَالظَّالِمِينَ أَعَدَّ لَهُمْ عَذاباً أَلِيماً [الإنسان/ ٣١]، في آي كثيرة، وقال: فَمَنْ أَظْلَمُ مِمَّنْ كَذَبَ عَلَى اللَّهِ<br>[الزمر/ ٣٢]، وَمَنْ أَظْلَمُ مِمَّنِ افْتَرى عَلَى اللَّهِ كَذِباً [الأنعام/ ٩٣].<br>والثاني: ظُلْمٌ بينه وبين الناس، وإيّاه قصد بقوله: وَجَزاءُ سَيِّئَةٍ سَيِّئَةٌ إلى قوله: إِنَّهُ لا يُحِبُّ الظَّالِمِينَ <strong>«١»</strong>، وبقوله: إِنَّمَا السَّبِيلُ عَلَى الَّذِينَ يَظْلِمُونَ النَّاسَ<br><strong>[الشورى/ ٤٢]، وبقوله:</strong><br>وَمَنْ قُتِلَ مَظْلُوماً<br>[الإسراء/ ٣٣].<br>والثالث: ظُلْمٌ بينه وبين نفسه، وإيّاه قصد بقوله: فَمِنْهُمْ ظالِمٌ لِنَفْسِهِ<br>[فاطر/ ٣٢]، وقوله: ظَلَمْتُ نَفْسِي<br>[النمل/ ٤٤]، إِذْ ظَلَمُوا أَنْفُسَهُمْ<br>[النساء/ ٦٤]، فَتَكُونا مِنَ الظَّالِمِينَ<br>[البقرة/ ٣٥]، أي: من الظَّالِمِينَ أنفسهم، وَمَنْ يَفْعَلْ ذلِكَ فَقَدْ ظَلَمَ نَفْسَهُ<br>[البقرة/ ٢٣١].<br>وكلّ هذه الثّلاثة في الحقيقة ظُلْمٌ للنّفس، فإنّ الإنسان في أوّل ما يهمّ بالظُّلْمِ فقد ظَلَمَ نفسه، فإذا الظَّالِمُ أبدا مبتدئ في الظُّلْمِ، ولهذا قال تعالى في غير موضع: ما ظَلَمَهُمُ اللَّهُ وَلكِنْ كانُوا أَنْفُسَهُمْ يَظْلِمُونَ<br>[النحل/ ٣٣]، وَما ظَلَمُونا وَلكِنْ كانُوا أَنْفُسَهُمْ يَظْلِمُونَ<br>[البقرة/ ٥٧]، وقوله: وَلَمْ يَلْبِسُوا إِيمانَهُمْ بِظُلْمٍ<br>[الأنعام/ ٨٢]، فقد قيل: هو الشّرك، بدلالة أنه لمّا نزلت هذه الآية شقّ ذلك على أصحاب النبيّ عليه السلام، وقال لهم: <strong>«ألم تروا إلى قوله: إِنَّ الشِّرْكَ لَظُلْمٌ عَظِيمٌ<br>»</strong> <strong>«٢»</strong>، وقوله: وَلَمْ تَظْلِمْ مِنْهُ شَيْئاً<br>[الكهف/ ٣٣]، أي: لم تنقص، وقوله: وَلَوْ أَنَّ لِلَّذِينَ ظَلَمُوا ما فِي الْأَرْضِ جَمِيعاً<br>[الزمر/ ٤٧]، فإنه يتناول الأنواع الثّلاثة من الظُّلْمِ، فما أحد كان منه ظُلْمٌ مّا في الدّنيا إلّا ولو حصل له ما في الأرض ومثله معه لكان يفتدي به، وقوله: هُمْ أَظْلَمَ وَأَطْغى<br>[النجم/ ٥٢]، تنبيها أنّ الظُّلْمَ لا يغني ولا يجدي ولا يخلّص بل يردي بدلالة قوم نوح. وقوله: وَمَا اللَّهُ يُرِيدُ ظُلْماً لِلْعِبادِ<br>[غافر/ ٣١]، وفي موضع: وَما أَنَا بِظَلَّامٍ لِلْعَبِيدِ<br>[ق/ ٢٩]، وتخصيص أحدهما بالإرادة مع لفظ العباد، والآخر بلفظ الظَّلَّامِ للعبيد<br><br>يختصّ بما بعد هذا الكتاب <strong>«١»</strong>. والظَّلِيمُ: ذَكَرُ النعامِ، وقيل: إنّما سمّي بذلك لاعتقادهم أنه مَظْلُومٌ، للمعنى الذي أشار إليه الشاعر:<br><span class=\"num\">٣٠٧-</span><table class=\"poem\"><tr><td>فصرت كالهيق عدا يبتغي </td><td> قرنا فلم يرجع بأذنين</td></tr></table><strong>«٢»</strong> والظَّلْمُ: ماء الأسنان. قال الخليل <strong>«٣»</strong> : لقيته أوّل ذي ظَلَمٍ، أو ذي ظَلَمَةٍ، أي: أوّل شيء سدّ بصرك، قال: ولا يشتقّ منه فعل، ولقيته أدنى ظَلَمٍ كذلك.","mq":[["خلاف الضياء والنور","وضع الشي غير موضعه تعديا"],"الظاء واللام والميم أصلانِ صحيحان، أحدهما خلافُ الضِّياء والنور، والآخر وَضْع الشَّئ غيرَ موضعه تعدِّياً.<br>فالأوّل الظُّلمة، والجمع ظلمات. والظَّلام: اسم الظلمة؛ وقد أظلَمَ المكان إظلاماً.<br>ومن هذا الباب ما حكاه الخليل من قولهم: لقيته أوَّلَ ذِى ظُلْمة * (١)<br>. قال:<br>وهو أوّلُ شئٍ سَدَّ (٢) بصرَك فى الر"],"ln":"<p><b>1.</b> <b class=\"ar\">ظَلَمَ</b> , aor. <b class=\"ar\">ظَلِمَ</b> , has for its inf. n. <span class=\"ar\">ظَلْمٌ</span>, (M, Msb, K, and so in some copies of the S,) or <span class=\"ar\"> <span class=\"ar\">ظُلْمٌ</span></span>, (so in other copies of the S,) or both, (T,) or the latter is a simple subst., (T, M, Msb, TA,) which is put in the place of the inf. n., (TA, [and the same is indicated in the T and K by the saying that the proper inf. n. is with fet-h,]) and <span class=\"ar\"> <span class=\"ar\">مَظْلِمَةٌ</span></span>, (S, TA,) or this is likewise a simple subst., (Msb,) and <span class=\"ar\"> <span class=\"ar\">مَظْلَمَةٌ</span></span>, [or this also is a simple subst.,] and <span class=\"ar\"> <span class=\"ar\">ظِلَامٌ</span></span> also is said to be an inf. n. like <span class=\"ar\">ظُلْمٌ</span>, these two being like <span class=\"ar\">لِبَاسٌ</span> and <span class=\"ar\">لُبْسٌ</span>, [or it is a simple subst. like as <span class=\"ar\">ظُلْمٌ</span> is said to be, or it is an inf. n. of 3, as such occurring in the middle of this paragraph,] or, accord. to Kr, it is pl. of <span class=\"ar\">ظُلْمٌ</span> [like as <span class=\"ar\">رِمَاحٌ</span> is pl. of <span class=\"ar\">رُمْحٌ</span>]: (TA:) [<span class=\"ar\">ظَلَمَ</span> when intrans. generally means <i>He did wrong;</i> or <i>acted wrongfully, unjustly, injuriously,</i> or <i>tyrannically:</i> and when trans., <i>he wronged;</i> or <i>treated,</i> or <i>used, wrongfully, unjustly, injuriously,</i> or <i>tyrannically;</i> or <i>he misused:</i>] accord. to most of the lexicologists, (Er-Rághib, TA,) primarily, (As, T, S, Msb,) <span class=\"ar\"> <span class=\"ar\">الظُّلْمُ</span></span> signifies <i>the putting a thing in a place not its own; putting it in a wrong place; misplacing it:</i> (As, T, S, M, Er-Rághib, Msb, K:) and it is <i>by exceeding</i> or <i>by falling short,</i> or <i>by deviating from the proper time and place:</i> (Er-Rághib, TA:) or <i>the acting in whatsoever way one pleases in the disposal of the property of another:</i> and <i>the transgressing the proper limit:</i> (El-Munáwee, TA:) [i. e.] <i>the transgressing the proper limit much</i> or <i>little:</i> (Er-Rághib, TA:) or, accord. to some, it primarily signifies <span class=\"ar\">النَّقْص</span> [as meaning <i>the making to suffer loss,</i> or <i>detriment</i>]: (MF, TA:) and it is said to be of three kinds, <i>between man and God,</i> and <i>between man and man,</i> and <i>between a man and himself;</i> every one of which three is really <span class=\"ar\">لِلنَّفْسِ</span> [i. e. <i>a wrongdoing to oneself</i>]: (Er-Rághib, TA:) [when it is used as a simple subst.,] the pl. of <span class=\"ar\">ظُلْمٌ</span>, accord. to Kr. is <span class=\"ar\">ظِلَامٌ</span>, as mentioned above, and <span class=\"ar\"> <span class=\"ar\">ظُلَامٌ</span></span>, with damm, is said to be syn. with <span class=\"ar\">ظُلْمٌ</span>, or a pl. thereof, [of an extr. form, commonly regarded as that of a quasi-pl. n.,] like <span class=\"ar\">رُخَالٌ</span>. (TA.) One says, <span class=\"ar\">مَنِ ٱسْتَرْعَى الذِّئْبَ فَقَدْ ظَلَمَ</span> [<i>He who asks,</i> or <i>desires, the wolf to keep guard surely does wrong,</i> or <i>puts a thing in a wrong place</i>]: a prov. (S, Msb.) And <span class=\"ar\">مَنْ أَشْبَهَ أَبَاهُ فَمَا ظَلَمَ</span>, (As, T, S,) a prov., meaning [<i>Whoso resembles his father</i> in a quality, or an attribute,] <i>he has not put the likeness in a wrong place.</i> (As, T. [See art. <span class=\"ar\">شبه</span>.]) <span class=\"ar\">وَلَمْ</span> <span class=\"ar\">تَظْلِمْ مِنْهُ شَيْئًا</span>, in the Kur [xviii. 31], means <span class=\"ar\">وَلَمْ تَنْقُصْ</span> [i. e. <i>And made not aught thereof to suffer loss,</i> or <i>detriment</i>]: (M, K:) and in like manner Fr explains the saying in the Kur [ii. 54 and vii. 160], <span class=\"ar\">وَمَا ظَلَمُونَا وَلٰكِنْ كَانُوا أَنْفُسَهُمْ</span> <span class=\"ar\">يَظْلِمُونَ</span> <i>And they made not us to suffer loss,</i> or <i>detriment,</i> by that which they did, <i>but themselves they made to suffer loss,</i> or <i>detriment:</i> (T, TA:) in which sense it seems to be indicated in the A that the verb is tropical. (TA.) -b2- It is also trans. by means of <span class=\"ar\">بِ</span>; as in the phrase in the Kur [vii. 101 and xvii. 61] <span class=\"ar\">فَظَلَمُوا بِهَا</span>, because the meaning is <span class=\"ar\">كَفَرُوا</span> [i. e. <i>And they disbelieved in them</i>], referring to the <span class=\"ar\">آيَات</span> [or <i>signs</i>]; (M, TA; *) the verb having this meaning tropically or by implication; or being thus made trans. because implying the meaning of <span class=\"ar\">التَّكْذِيب</span>: or [the meaning is, and <i>they wronged</i> themselves, or the people, <i>because of them;</i> for], as some say, the <span class=\"ar\">ب</span> is causative, and the objective complement, i. e. <span class=\"ar\">أَنْفُسَهُمْ</span>, or <span class=\"ar\">النَّاسَ</span>, is suppressed. (TA.) -b3- And it is doubly trans. by itself: (TA:) one says, <span class=\"ar\">ظَلَمَهُ حَقَّهُ</span> [<i>He made him to suffer loss,</i> or <i>detriment, of his right,</i> or <i>due;</i> or <i>defrauded,</i> or <i>despoiled,</i> or <i>deprived, him of it</i>]; and <span class=\"ar\"> <span class=\"ar\">تظلّمهُ</span>حَقَّهُ</span>: (M, K:) [and] you say, <span class=\"ar\"> <span class=\"ar\">تَظَلَّمَنِى</span>فُلَانٌ</span>, [as well as <span class=\"ar\">تظلّمنى مَالِى</span>, occurring in a verse cited in the M,] meaning <span class=\"ar\">ظَلَمَنِى مَالِى</span> [i. e. <i>Such a one caused me to suffer loss,</i> &amp;c., <i>of my property</i>]. (S.) It is said in the Kur [iv. 44], <span class=\"ar\">إِنَّ ٱللّٰهَ لَا</span> <span class=\"ar\">يَظْلِمُ مِثْقَالَ ذَرَّةٍ</span>, for <span class=\"ar\">لَا يَظْلِمُهُمْ مِثْقَالَ ذَرَّةِ</span>, and the verb is made doubly trans. because the meaning is <span class=\"ar\">لَا يَسْلُبُهُمْ</span> [i. e. <i>Verily God will not despoil them,</i> or <i>deprive them, of the weight of one of the smallest of ants,</i> or <i>a grub of an ant,</i> &amp;c.]: or <span class=\"ar\">مِثْقَالَ ذَرَّةٍ</span>, may be put in the place of the inf. n., for <span class=\"ar\">ظَلْمًا حَقِيرًا كَمِثْقَالِ ذَرَّةٍ</span> [i. e. <i>with a paltry spoliation</i> or <i>deprivation, such as the weight of one of the smallest of ants,</i> &amp;c.]. (M.) -b4- One says also, <span class=\"ar\">أَرَادَ ظِلَامَهُ</span> and <span class=\"ar\">مُظَالَمَتَهُ</span>, [these two nouns being inf. ns. of <span class=\"ar\"> <span class=\"ar\">ظَالَمَهُ</span></span>, or the former, as mentioned above, is, accord. to some, an inf. n. of <span class=\"ar\">ظَلَمَ</span>,] meaning <span class=\"ar\">ظُلْمَهُ</span> or <span class=\"ar\">ظَلْمَهُ</span> [i. e. <i>He desired the wronging,</i> &amp;c., <i>of him</i>]. (M, K.) -b5- <span class=\"ar\">ظَلَمَهُ</span>, inf. n. <span class=\"ar\">ظُلْمٌ</span> [or <span class=\"ar\">ظَلْمٌ</span>?], also means <i>He imposed upon him a thing that was above his power,</i> or <i>ability.</i> (TA.) And <span class=\"ar\">يُظْلَمُ</span> <i>He is asked for a thing that is above his power,</i> or <i>ability.</i> (S.) -b6- And one says, <span class=\"ar\">ظَلَمَ البَعِيرَ</span> (tropical:) <i>He slaughtered the camel without disease.</i> (S, K, TA.) And <span class=\"ar\">ظُلِمَتِ النَّاقَةُ</span> (assumed tropical:) <i>The she-camel was slaughtered without disease:</i> or <i>was covered without her desiring the stallion.</i> (M.) And <span class=\"ar\">ظَلَمَ الحِمَارُ الأَتَانَ</span> (tropical:) <i>The he-ass leaped the she-ass</i> (K, TA) <i>before her time:</i> (TA:) or <i>when she was pregnant:</i> (K, TA:) so in the A. (TA.) -b7- And <span class=\"ar\">ظَلَمَ الوَطْبَ</span>, (S, K,) inf. n. <span class=\"ar\">ظُلْمٌ</span> [or <span class=\"ar\">ظَلْمٌ</span>?], (S,) (tropical:) <i>He gave to drink of the milk of his skin before its becoming thick</i> (S, K, TA) <i>and its butter's coming forth.</i> (TA. [And the like is said in the T and M.]) And <span class=\"ar\">ظَلَمَ القَوْمَ</span> (assumed tropical:) <i>He gave to drink to the people,</i> or <i>party,</i> (T, M, K,) <i>milk before it had attained to maturity,</i> (T, K,) as related on the authority of A 'Obeyd, (T,) or [<i>milk such as is termed</i>] <span class=\"ar\">ظَلِيمَة</span>: (M:) but this is a mistake: it is related on the authority of Ahmad Ibn-Yahyà [i. e. Th] and AHeyth that one says, <span class=\"ar\">ظَلَمْتُ السِّقَآءَ</span>, and <span class=\"ar\">اللَّبَنَ</span>, meaning <i>I drank,</i> or <i>gave to drink, what was in the skin,</i> and <i>the milk, before its attaining to maturity and the extracting of its butter:</i> accord. to ISk, one says, <span class=\"ar\">ظَلَمْتُ وَطْبِىَ القَوْمَ</span>, [but I think that it is correctly <span class=\"ar\">ظَلَمْتُ وَطْبِى لِلْقَومِ</span>, agreeably with a verse cited in the T and M,] meaning <i>I gave to drink</i> [<i>to the people,</i> or <i>party,</i>] <i>the contents of my milk-skin before the thickening thereof.</i> (T.) And <span class=\"ar\">ظَلَمْتُهُ</span> is said of anything as meaning (assumed tropical:) <i>I did it hastily,</i> or <i>hurriedly, before its proper time,</i> or <i>season.</i> (M, TA.) -b8- <span class=\"ar\">ظَلَمْتُ الحَوْضَ</span> means (assumed tropical:) <i>I made the watering-trough in a place in which watering-troughs should not be made.</i> (ISk, T.) And <span class=\"ar\">ظَلَمَ الأَرْضَ</span> means (tropical:) <i>He dug the ground in what was not the place of digging:</i> (M, K, TA:) or <i>when it had not been dug before.</i> (M.) And, said of a torrent, (assumed tropical:) <i>It furrowed the earth in a place that was not furrowed.</i> (T.) And <span class=\"ar\">ظَلَمَ</span> <span class=\"ar\">البِطَاحَ</span>, said of a torrent, (tropical:) <i>It reached the</i> <span class=\"ar\">بطاح</span> [or <i>wide water-courses containing fine,</i> or <i>broken, pebbles,</i> &amp;c.], <i>not having reached them before.</i> (A, TA.) And <span class=\"ar\">ظَلَمَ الوَادِى</span> (tropical:) <i>The water of the valley reached a place that it had not reached before.</i> (Fr, T, S, K, TA.) -b9- When men have added upon the grave other than its own earth, <span class=\"ar\">لَا تَظْلِمُوا</span> (tropical:) [<i>Transgress not ye the proper limit</i>] is said to them. (TA.) -b10- And one says, <span class=\"ar\">لَا</span> <span class=\"ar\">تَظْلِمْ وَضَحَ الطَّرِيقِ</span> (assumed tropical:) <i>Turn not thou from the main part,</i> or <i>the beaten track, of the road.</i> (M.) And <span class=\"ar\">لَا تَظْلِمْ عَنْهُ شَيْئَا</span> (assumed tropical:) <i>Turn not thou from it at all.</i> (T.) And <span class=\"ar\">لَزِمَ الطَّرِيقَ فَلَمْ يَظْلِمْهُ</span> (assumed tropical:) [<i>He kept to the road, and</i>] <i>did not turn from it to the right and left.</i> (TA.) -b11- And <span class=\"ar\">مَا ظَلَمَكَ</span> <span class=\"ar\">أَنْ تَفْعَلَ</span> (T, K, TA) (tropical:) <i>What has prevented thy doing</i> (K, TA) such a thing? (TA.) A man complained to Abu-l-Jarráh of his suffering indigestion from food that he had eaten, and he said to him, <span class=\"ar\">مَا ظَلَمَكَ أَنْ تَقِىْءَ</span> (assumed tropical:) [<i>What has prevented thy vomiting?</i>]. (Fr, T.) And one says, <span class=\"ar\">مَا ظَلَمَكَ عَنْ كَذَا</span> (assumed tropical:) <i>What has prevented thee from such a thing?</i> (T.) Respecting the saying <span class=\"ar\">قَالَ بَلَى يَا مَىَّ وَاليَوْمُ ظَلَمْ</span> [addressed by a man to a woman who had invited him to visit her], Fr says, they say that the meaning is <span class=\"ar\">حَقًّا</span> [<i>Truly,</i> or <i>in truth;</i> i. e. <i>He said, Yes, O Meiya, truly,</i> or <i>in truth,</i> I will visit thee]; and it is a prov.; (T;) or <span class=\"ar\">اليَوْمُ ظَلَمَ</span>, or <span class=\"ar\">بَلَى وَاليَوْمُ ظَلَمَ</span>, is a prov.; (Meyd;) and thus it was expl. by IAar, as used in the manner of an oath: but Fr says, in my opinion the meaning is, <i>and a day in which is a cause of prevention shall not prevent me:</i> [so that the words of the hemistich above may be rendered, <i>he said, Yes, O Meiya, though the day present an obstacle,</i> for I will overcome every obstacle]: (T:) accord. to Kr, <span class=\"ar\">قَدِمَ فُلَانٌ وَاليَوْمُ ظَلَمَ</span> means <i>Such a one came truly,</i> or <i>in truth:</i> [or it may be rendered <i>such a one came though the day presented an obstacle:</i>] but in the saying <span class=\"ar\">إِنَّ الفِرَاقَ اليَوْمَ وَاليَوْمُ ظَلَمْ</span> the meaning is said by some to be <span class=\"ar\">وَاليَوْمُ ظَلَمَنَا</span> [i. e. <i>Verily separation is to-day, and the day has wronged</i> (us)]: or, as some say, <span class=\"ar\">ظلم</span> here means, <i>has put the thing in a wrong place:</i> (M:) accord. to ISk, the phrase <span class=\"ar\">وَاليَوْمُ ظَلَم</span> means [<i>And,</i> or <i>but,</i> or <i>though,</i>] <i>the day has put the affair in a wrong place.</i> (T.) [See also Freytag's Arab. Prov. ii. 911.] -A2- <span class=\"ar\">ظَلِمَ</span>, said of the night: see 4.</p><p><b>2.</b> <b class=\"ar\">ظلّمهُ</b> , inf. n. <span class=\"ar\">تَظْلِيمٌ</span>, (T, S, &amp;c.,) <i>He told him that he was</i> <span class=\"ar\">ظَالِم</span> [i. e. <i>doing wrong</i> or <i>acting wrongfully</i> &amp;c., or <i>a wrongdoer</i>]: (T:) or <i>he attributed,</i> or <i>imputed, to him</i> <span class=\"ar\">ظُلْم</span> [i. e. <i>wrongdoing,</i> &amp;c.]. (S, M, Msb, K.) -b2- And <i>He</i> (a judge) <i>exacted justice for him from his wronger, and aided him against him.</i> (T.)</p><p><b>3.</b> <b class=\"ar\">ظَاْلَمَ</b> see 1, in the middle of the paragraph.</p><p><b>4.</b> <b class=\"ar\">اظلم</b> , said of the night, (Fr, T, S, M, Msb, K,) and <span class=\"ar\"> <span class=\"ar\">ظَلِمَ</span></span>, (Fr, T, S, K,) the latter with kesr, (S,) like <span class=\"ar\">سَمِعَ</span>, (K,) [erroneously written in the TT as from the M <span class=\"ar\">ظَلَمَ</span>,] <i>It became dark;</i> (S, K;) or <i>it became black;</i> (M;) or <i>it came with its darkness.</i> (Msb.) It is said in the Kur [ii. 19], <span class=\"ar\">وَإِذَا أَظْلَمَ عَلَيْهِمْ قَامُوا</span> [<i>And when it becomes dark to them they stand still</i>]; the verb being intrans.: or, accord. to the Ksh, and Bd follows it, it may be trans. [so that the meaning is, <i>and when He makes</i> their place <i>dark</i> &amp;c.]; as is shown by another reading, which is <span class=\"ar\">أُظْلِمُوا</span>: accord. to AHei, it is known by transmission as only intrans.; but Z makes it to be trans. by itself; Ibn-Es-Saláh affirms it to be trans. and intrans.: and Az [so in the TA, but correctly ISd, in the M,] mentions the saying, <span class=\"ar\">تَكَلَّمَ فَأَظْلَمَ</span> <span class=\"ar\">عَلَيْنَا البَيعتَ</span> (assumed tropical:) [<i>He spoke, and made dark to us the house,</i> or <i>chamber,</i> or <i>tent</i>], meaning he made us to hear what we disliked, or hated, the verb being trans. (TA.) -b2- And <span class=\"ar\">أَظْلَمُوا</span> <i>They entered upon the</i> <span class=\"ar\">ظَلَام</span> [or <i>darkness,</i> or <i>beginning of night</i>]: (S, M, Msb, K:) or, as in the Mufradát [of Er-Rághib], <i>they became in darkness.</i> (TA.) -b3- And they said, <span class=\"ar\">مَا أَظْلَمَهُ</span> and <span class=\"ar\">ما أَضْوَأَهُ</span> [<i>How dark is it!</i> and <i>How light,</i> or <i>bright, is it!</i>]; which is anomalous. (S, TA.) -A2- And <span class=\"ar\">اظلم</span> <span class=\"ar\">الثَّغْرُ</span> <i>The front teeth glistened.</i> (T, K.) Hence the saying [of a poet], <span class=\"ar\">إِذَا مَا ٱجْتَلَى الرَّائِى إِلَيْهَا بِطَرْفِهِ</span> <span class=\"ar\">غُرُوبَ ثَنَايَاهَا أَضَآءَ وَأَظْلَمَا</span> [as though meaning, <i>When the beholder of her with his eye looks at the fineness,</i> or <i>sharpness,</i> (but <span class=\"ar\">غُرُوب</span> is variously explained,) <i>of her central teeth, it shines brightly, and glistens:</i> but Az plainly indicates another meaning; i. e., <i>he sees</i> (lit. <i>lights on,</i> or <i>finds,</i>) <i>brightness and lustre;</i> for he immediately adds, without the intervention of <span class=\"ar\">وَ</span> or <span class=\"ar\">أَوْ</span>, evidently in relation to this verse,] <span class=\"ar\">أَضَآءَ</span> <span class=\"ar\">أَىْ أَصَابَ ضَوْءًا وَأَظْلَمَ أَصَابَ ظَلْمًا</span>: (T:) [and ISd cites the verse above with the substitution of <span class=\"ar\">بِعَينِهِ</span> for <span class=\"ar\">بِطَرْفِهِ</span> and of <span class=\"ar\">أَنَارَ</span> for <span class=\"ar\">أَضَآءَ</span> immediately after saying that] <span class=\"ar\">أَظْلَمَ</span> signifies <i>he looked at the teeth and saw lustre</i> (<span class=\"ar\">الظَّلْمَ</span>). (M.) [In the K, next after the explanation of <span class=\"ar\">اظلم الثَّغْرُ</span> given above, it is added that <span class=\"ar\">اظلم</span> said of a man signifies <span class=\"ar\">أَصَابَ ظَلْمًا</span>: thus, with fet-h, to the <span class=\"ar\">ظ</span>, accord. to the TA: in my MS. copy of the K and in the CK, <span class=\"ar\">ظُلْمًا</span>, which is doubtless a mistranscription.]</p><p><b>5.</b> <b class=\"ar\">تَظَلَّمَ</b> <span class=\"ar\">تظلّم مِنْهُ</span> (T, S, M, K, [but in some copies of the S, <span class=\"ar\">منه</span> is omitted,]) <i>He complained of his</i> <span class=\"ar\">ظُلْم</span> [or <i>wrongdoing,</i> &amp;c.], (S, M, K,) <span class=\"ar\">إِلَى الحَاكِمِ</span> [<i>to the judge</i>]: (T:) in some copies of the S, <span class=\"ar\">تُظُلِّمَ</span>. (TA.) -b2- And <span class=\"ar\">تظلّم</span> signifies also <i>He transferred the responsibility for the</i> <span class=\"ar\">ظُلْم</span> [or <i>wrongdoing,</i> &amp;c.,] <i>upon himself,</i> (M, K,) accord. to IAar, who has cited as an ex., <span class=\"ar\">كَانَتْ إِذَا غَضِبَتْ عَلَىَّ تَظَلَّمَتْ</span> [as though meaning <i>She used, when she was angry with me, to transfer the responsibility for the wrongdoing upon herself;</i> which may mean that she finally confessed the wrongdoing to be hers]; but [ISd says] I know not how that is: the <span class=\"ar\">تَظَلُّم</span> in this case is only the complaining of <span class=\"ar\">الظُّلْم</span>; for when she was angry with him, it was not allowable [to say] that she attributed the <span class=\"ar\">ظُلْم</span> to herself. (M.) -b3- See also 1, former half, in two places.</p><p><b>6.</b> <b class=\"ar\">تظالم القَوْمُ</b> (S, M, Msb) <i>The people,</i> or <i>company of men, treated,</i> or <i>used, one another wrongfully, unjustly, injuriously,</i> or <i>tyrannically</i> (<span class=\"ar\">ظَلَمَ</span> <span class=\"ar\">بَعْضُهُمْ بَعْضًا</span>). (M, Msb.) -b2- And [hence] <span class=\"ar\">تَظَالَمَتِ المِعْزَى</span> (tropical:) <i>The goats smote one another with their horns</i> by reason of their being fat and having abundance of herbage. (IAar, M, TA.) One says, <span class=\"ar\">وَجَدْنَا أَرْضًا تَظَالَمَ مِعْزَاهَا</span> (tropical:) <i>We found a land whereof the goats smote one another with their horns</i> by reason of satiety and liveliness. (T, TA.)</p><p><b>7.</b> <b class=\"ar\">إِنْظَلَمَ</b> see the next paragraph.</p><p><b>8.</b> <b class=\"ar\">اِظَّلَمَ</b> (T, S, M, K) and <span class=\"ar\">اِظْطَلَمَ</span> and <span class=\"ar\">اِطَّلَمَ</span>, (S, M,) which last is [said to be] the most usual, (S,) [but I have mostly found the first to be used,] of the measure <span class=\"ar\">اِفْتَعَلَ</span>, (S, M,) <i>He took upon himself</i> [<i>the bearing of</i>] <span class=\"ar\">ظُلْم</span> [or <i>wrong,</i> &amp;c.,] <i>in spite of difficulty, trouble,</i> or <i>inconvenience:</i> (S, TA:) or <i>he bore</i> <span class=\"ar\">الظُّلْم</span> [or <i>wrong,</i> &amp;c.,] (T, M, K, TA,) <i>willingly, being able to resist;</i> (T, TA;) and <span class=\"ar\"> <span class=\"ar\">اِنْظَلَمَ</span></span> signifies [thus likewise, or] <i>he bore</i> <span class=\"ar\">الظُّلْم</span>. (S, M, K.)</p><p><b class=\"ar\">ظَلْمٌ</b> The <i>lustre,</i> and <i>brightness, of gold.</i> (Z, TA.) -b2- And hence, (Z, TA,) The <i>lustre</i> (lit. <i>running water</i>) <i>upon the teeth;</i> (Lth, T, Z, TA;) the <i>lustre</i> (<span class=\"ar\">مَآء</span>, S, M, K, and <span class=\"ar\">بَرِيق</span>, S, K) <i>of the teeth,</i> (Lth, T, S, M, Z, K, TA,) <i>from the clearness of the colour, not from the saliva,</i> (Lth, * T, * M,) <i>like blackness within the bone thereof, by reason of the intense whiteness,</i> (S, K,) <i>resembling the</i> <span class=\"ar\">فِرِنْد</span> [q. v.] <i>of the sword,</i> (S, K,) or <i>appearing like the</i> <span class=\"ar\">فِرِنْد</span> [<i>of the sword</i>], <i>so that one imagines that there is in it a blackness, by reason of the intense lustre and clearness:</i> (M:) or, accord. to Sh, <i>whiteness of the teeth, as though there were upon it</i> [<i>somewhat of</i>] <i>a blackness:</i> or, as Abu-l-'Abbás ElAhwal says, in the Expos. of the “ Kaabeeyeh, ” <i>lustre</i> (lit. <i>running water</i>) <i>of the teeth, such that one sees upon it, by reason of its intense clearness</i> [app. meaning <i>transparency</i>], <i>what resembles dustcolour and blackness:</i> or, accord. to another explanation, <i>fineness,</i> or <i>thinness, and intense whiteness, of the teeth:</i> (TA:) pl. <span class=\"ar\">ظُلُومٌ</span>. (S, M.) -b3- Also <i>Snow:</i> (M, K:) it is said to have this meaning: and the phrase <span class=\"ar\">مُشْرَبَةِ الثَّنَايَا بِمَآءِ الظَّلْمِ</span>, used by a poet, may mean [<i>Having the central teeth suffused with the lustre termed</i> <span class=\"ar\">ظَلْم</span>, as is indicated in the T and S, or] <i>with the water of snow.</i> (Lth, T.)</p><p><b class=\"ar\">ظُلْمٌ</b> [as a simple subst. generally means <i>Wrong, wrongdoing, injustice, injuriousness,</i> or <i>tyranny</i>]: see 1, first sentence, in two places. -b2- [<span class=\"ar\">ظُلْمُ</span> <span class=\"ar\">الارضِ</span> in the CK is a mistranscription for <span class=\"ar\">ظَلَمَ</span> <span class=\"ar\">الأَرْضَ</span>. -b3- And <span class=\"ar\">الظُلْمُ</span> in one place in the CK, as syn. with <span class=\"ar\">الظَّلْمَآءُ</span>, is a mistake for <span class=\"ar\">الظُّلْمَةُ</span>.]</p><p><b class=\"ar\">لَقِيتُهُ أَدْنَى ظَلَمٍ</b> , (S, M, K,) or <span class=\"ar\">أَدْنَى ذِى ظَلَمٍ</span>, (K, TA, [in the CK <span class=\"ar\">اَوَّلَ ذِى ظَلَمٍ</span>,]) means (tropical:) <i>I met him the first of everything:</i> (S, K, TA:) or <i>the first thing:</i> (M:) or <i>when the darkness was becoming confused:</i> (M, K:) or <span class=\"ar\">أَدْنَى ظَلَمٍ</span> means <i>near;</i> (El-Umawee, S, M, K;) or <i>nearness:</i> (M, K:) and one says, <span class=\"ar\">هُوَ مِنْكَ أَدْنَى ذِى ظَلَمٍ</span> [app. <i>He is near thee</i>], and <span class=\"ar\">رَأَيْتُهُ أَدْنَى ذِى ظَلَمٍ</span> [app. <i>I saw him near</i>]: (M:) and <span class=\"ar\">ظَلَمٌ</span> is also <i>syn. with</i> <span class=\"ar\">شَخْصٌ</span> [as meaning <i>an object seen from a distance,</i> or <i>a person</i>]; (K;) or, as some say, it has this meaning in the phrase <span class=\"ar\">أَدْنَى ظَلَمٍ</span> [so that <span class=\"ar\">لَقِيتُهُ أَدْنَى ظَلَمٍ</span> may mean <i>I met him the nearest object seen from a distance,</i> or <i>the nearest person</i>]: (M:) and accord. to Kh, one says, <span class=\"ar\">لَقِيتُهُ أَدْنَى <span class=\"ar\">ظُلْمَةٍ</span></span>, or <span class=\"ar\">أَوَّلَ ذِى ظُلْمَةٍ</span>, (as in different copies of the S,) meaning <i>I met him the first thing that obstructed my sight.</i> (S.) -b2- <span class=\"ar\">ظَلَمٌ</span> signifies also <i>A mountain:</i> and the pl. is <span class=\"ar\">ظُلُومٌ</span>. (M, K.)</p><p><b class=\"ar\">ظُلَمٌ</b> an appellation of <i>Three nights</i> (T, S, K) <i>of the lunar month</i> (T, S) <i>next after the three called</i> <span class=\"ar\">دُرَعٌ</span>; (T, S, * K; *) so says A'Obeyd: (T:) thus called because of their darkness: (S:) the sing. is <span class=\"ar\"> <span class=\"ar\">ظَلْمَآءُ</span></span>; (T, S;) so that it is anomalous; for by rule it should be <span class=\"ar\">ظُلْمٌ</span>; (S;) and the sing. of <span class=\"ar\">دُرَعٌ</span> is <span class=\"ar\">دَرْعَآءُ</span>: so says A'Obeyd: but accord. to AHeyth and Mbr, the sings. are <span class=\"ar\"> <span class=\"ar\">ظُلْمَةٌ</span></span> and <span class=\"ar\">دُرْعَةٌ</span>, agreeably with rule; and this is the correct assertion. (T. [See more in art. <span class=\"ar\">درع</span>, voce <span class=\"ar\">أَدْرَعُ</span>.])</p><p><b class=\"ar\">ظِلَمٌ</b> : see <span class=\"ar\">ظِلَّامٌ</span>.</p><p><b class=\"ar\">ظُلْمَةٌ</b> (T, S, M, Msb, K) and <span class=\"ar\"> <span class=\"ar\">ظُلُمَةٌ</span></span> (S, M, K) [accord. to the CK <span class=\"ar\">ظُلْمٌ</span> and <span class=\"ar\">ظُلُمٌ</span>, both of which are wrong,] and <span class=\"ar\"> <span class=\"ar\">ظَلْمَآءُ</span></span> (S, M, Msb, K) <i>Darkness; contr. of</i> <span class=\"ar\">نُورٌ</span>: (S, Msb:) or <i>nonexistence of</i> <span class=\"ar\">نُور</span> [or <i>light</i>]: or <i>an accidental state that precludes the coëxistence therewith of</i> <span class=\"ar\">نُور</span>: (Er-Rághib, TA:) or the <i>departure of light;</i> as also <span class=\"ar\"> <span class=\"ar\">ظَلَامٌ</span></span>; (M, K;) which last has no pl.; (T, TA;) or this last signifies the <i>beginning,</i> or <i>first part, of night,</i> (S, M, Msb,) <i>even though it be one in which the moon shines;</i> and is said by Sb to be used only adverbially; one says, <span class=\"ar\">أَتَيْتُهُ ظَلَامًا</span>, meaning <i>I came to him at night,</i> and <span class=\"ar\">مَعَ الظَّلَامِ</span> i. e. <i>at the time of the night:</i> (M, TA:) the pl. of <span class=\"ar\">ظُلْمَةٌ</span> is <span class=\"ar\">ظُلَمٌ</span> and <span class=\"ar\">ظُلُمَاتٌ</span> and <span class=\"ar\">ظُلَمَاتٌ</span> (T, S, Msb) and <span class=\"ar\">ظُلْمَاتٌ</span>, (S, Msb,) or, accord. to IB, the first of these pls. is of <span class=\"ar\">ظُلْمَةٌ</span> and the second is of <span class=\"ar\">ظُلُمَةٌ</span>. (TA.) One says, <span class=\"ar\">هُوَ يَخْبِطُ <span class=\"ar\">الظَّلَامَ</span></span> [or <span class=\"ar\">فِى الظَّلَامِ</span>, expl. in art. <span class=\"ar\">خبط</span>], and <span class=\"ar\">الظُّلْمَةَ</span> [which means the same] and <span class=\"ar\"> <span class=\"ar\">الظَّلْمَآءَ</span></span> [which is also expl. in art. <span class=\"ar\">خبط</span>]. (TA.) -b2- <span class=\"ar\">ظُلْمَةٌ</span> is also [tropically] used as a term for (assumed tropical:) <i>Ignorance:</i> and (assumed tropical:) <i>belief in a plurality of gods:</i> and (assumed tropical:) <i>transgression,</i> or <i>unrighteousness:</i> like as <span class=\"ar\">نُورٌ</span> is used as a term for their contraries: (Er-Rághib, TA:) and it is said in the A that <span class=\"ar\">الظُّلْمُ</span> is <span class=\"ar\">ظُلْمَةٌ</span>, like as <span class=\"ar\">العَدْلُ</span> is <span class=\"ar\">نُورٌ</span>. (TA.) <span class=\"ar\">ظُلُمَاتُ البَحْرِ</span> means (assumed tropical:) <i>The troubles, afflictions, calamities,</i> or <i>hardships, of the sea.</i> (M.) -A2- And one says <span class=\"ar\">لَيْلَةٌ ظُلْمَةٌ</span>, [using the latter word as an epithet, (in the CK, erroneously, <span class=\"ar\">ظَلِمَةٌ</span>,)] and <span class=\"ar\">لَيْلَةٌ <span class=\"ar\">ظَلْمَآءُ</span></span>, both meaning <i>A night intensely dark;</i> (M, K;) or the latter means <span class=\"ar\">مُظْلِمَةٌ</span> [i. e. <i>dark,</i> or <i>black</i>]: (S:) and <span class=\"ar\">لَيْلٌ <span class=\"ar\">ظَلْمَآءُ</span></span> also, (M, K,) which is anomalous, (K,) mentioned by IAar, but [ISd says] this is strange, and in my opinion he has put <span class=\"ar\">لَيْلٌ</span> in the place of <span class=\"ar\">لَيْلَةٌ</span>, as in his mentioning <span class=\"ar\">لَيْلٌ قَمْرَآءُ</span> [q. v.]. (M.) -b2- See also <span class=\"ar\">ظُلَمٌ</span>: -b3- and see the paragraph next preceding it.</p><p><b class=\"ar\">ظِلْمَةٌ</b> sing. of <span class=\"ar\">ظِلَمٌ</span>: see <span class=\"ar\">ظِلَّامٌ</span>.</p><p><b class=\"ar\">ظُلُمَةٌ</b> : see <span class=\"ar\">ظُلْمَةٌ</span>.</p><p><b class=\"ar\">ظَلْمَآءُ</b> : see <span class=\"ar\">ظُلْمَةٌ</span>, in four places: and see also <span class=\"ar\">ظُلَمٌ</span>.</p><p><b class=\"ar\">ظَلَامٌ</b> : see <span class=\"ar\">ظُلْمَةٌ</span>, in two places.</p><p><b class=\"ar\">ظُلَامٌ</b> : see 1, in the first quarter of the paragraph.</p><p><b class=\"ar\">ظِلَامٌ</b> : see 1, near the beginning: -A2- see also <span class=\"ar\">ظِلَّامٌ</span>. -A3- It signifies also <i>Little,</i> or <i>small, in quantity:</i> or <i>mean, contemptible, paltry,</i> or <i>of no weight</i> or <i>worth:</i> -b2- whence the saying, <span class=\"ar\">نَظَرَ إِلَىَّ</span> <span class=\"ar\">ظِلَامًا</span>, meaning <span class=\"ar\">شَزْرًا</span> [i. e. <i>He looked at me from the outer angle of the eye, with anger,</i> or <i>aversion</i>]. (K.)</p><p><b class=\"ar\">ظَلُومٌ</b> : see <span class=\"ar\">ظَلَّامٌ</span>. -b2- [Hence,] one says <span class=\"ar\">اِمْرَأَةٌ</span> <span class=\"ar\">ظَلُومٌ لِلسِّقَآءِ</span> (assumed tropical:) [<i>A woman wont to give to drink the milk of the skin before its attaining to maturity and the extracting of its butter:</i> see <span class=\"ar\">ظَلَمَ الوَطْبَ</span>, and what follows it, in the first paragraph]. (M.)</p><p><b class=\"ar\">ظَلِيمٌ</b> [as syn. with <span class=\"ar\">مَظْلُومٌ</span> in the primary sense of the latter I have not found: but as an epithet in which the quality of a subst. predominates it signifies] (tropical:) <i>Milk that is drunk before its becoming thick and its butter's coming forth</i> or <i>being extracted;</i> (S, * M;) as also <span class=\"ar\"> <span class=\"ar\">ظَلِيمَةٌ</span></span>, (T, S, M,) and <span class=\"ar\"> <span class=\"ar\">مَظْلُومٌ</span></span>. (T, S.) -b2- And (assumed tropical:) <i>A place that is</i> <span class=\"ar\"> <span class=\"ar\">مَظْلُوم</span></span> [i. e. <i>dug where it should not be dug</i>]: (M, TA:) used in this sense by a poet describing a person slain in a desert, for whom a grave was dug in a place not proper for digging [it]. (M.) -b3- And (tropical:) The <i>earth of land that is</i> <span class=\"ar\"> <span class=\"ar\">مَظْلُومَة</span></span> (S, K, TA) i. e. <i>dug,</i> (TA,) or <i>dug for the first time.</i> (S.) And (assumed tropical:) The <i>earth of the</i> <span class=\"ar\">لَحْد</span> [or <i>lateral hollow</i>] <i>of a grave; which is put back, over it, after the burial of the dead therein.</i> (T, TA.) -A2- Also The <i>male ostrich:</i> (T, S, M, K:) said (by IDrd, TA) to be so called because he makes a place for the laying and hatching of the eggs (<span class=\"ar\">يُدَحِّى</span>, inf. n. <span class=\"ar\">تَدْحِيَةٌ</span>,) where the doing so is not proper: (M, TA:) or, accord. to Er-Rághib and others, because he is believed to be deaf: (TA:) pl. <span class=\"ar\">ظِلْمَانٌ</span> (T, M, K) and <span class=\"ar\">ظُلْمَانٌ</span> (M, K) and <span class=\"ar\">أَظْلِمَةٌ</span>, (T, M,) which last is a pl. of pauc. (T.) -b2- And <span class=\"ar\">الظَّلِيمَانِ</span> is an appellation of <i>Two stars;</i> (M, K, * TA;) <i>the two stars of</i> <span class=\"ar\">القَوْس</span> [or <i>Sagittarius</i>] <i>that are on the northern curved end of the bow</i> [i. e. <b class=\"ar\">λ</b> and <b class=\"ar\">μ</b>, <i>above the nine stars called</i> <span class=\"ar\">النَّعَائِم</span>, or “ <i>the ostriches</i> ”]. (Kzw in his descr. of Sagittarius.) And <span class=\"ar\">الظَّلِيمُ</span> is the name of <i>The bright star</i> [ <b class=\"ar\">α</b>] <i>at the end of</i> <span class=\"ar\">النَّهْر</span> [i. e. <i>Eridanus</i>]: and <i>A star upon the mouth of</i> <span class=\"ar\">الحُوت</span> [i. e. <i>Piscis Australis</i>] (Kzw in his descr. of Eridanus.) [It seems to be implied in the K that <span class=\"ar\">الظَّلِيمُ</span> is the name of two stars; or it may be there meant that each of two stars is thus called. Freytag represents the sing. as “ a name of stars, ” and the dual also as “ a name of stars; ” referring, in relation to the former, to Ideler's “ Untersuch, ” pp. 201, 228, and 233; and in relation to the latter, to the same work, pp. 106 and 184.]</p><p><b class=\"ar\">ظُلَامَةٌ</b> : see <span class=\"ar\">مَظْلِمَةٌ</span>.</p><p><b class=\"ar\">ظَلِيمَةٌ</b> : see <span class=\"ar\">مَظْلِمَةٌ</span>: -b2- and see also <span class=\"ar\">ظَلِيمٌ</span>.</p><p><b class=\"ar\">ظَلَّامٌ</b> (TA) and <span class=\"ar\"> <span class=\"ar\">ظِلِّيمٌ</span></span> (S, TA) [and <span class=\"ar\"> <span class=\"ar\">ظَلُومٌ</span></span>, mentioned in the M and K with <span class=\"ar\">ظَالِمٌ</span>, as though syn. therewith, but it is an intensive epithet,] One <i>who acts wrongfully, unjustly, injuriously,</i> or <i>tyrannically, much,</i> or <i>often; i. q.</i> <span class=\"ar\">كَثِيرُ الظُّلْمِ</span>. (S, TA.) -b2- <span class=\"ar\">ظَلَّامُونَ لِلْجُزُرِ</span> occurs in a verse of Ibn-Mukbil [meaning (assumed tropical:) Men <i>often slaughtering camels without disease</i>]. (T, S.) -A2- See also what next follows.</p><p><b class=\"ar\">ظِلَّامٌ</b> (AHn, T, M, K) and <span class=\"ar\"> <span class=\"ar\">ظَلَّامٌ</span></span> (T) and <span class=\"ar\"> <span class=\"ar\">ظِلَامٌ</span></span> (K) and <span class=\"ar\"> <span class=\"ar\">ظَالِمٌ</span></span> and <span class=\"ar\"> <span class=\"ar\">ظِلَمٌ</span></span>, (T, K,) the last mentioned by IAar, and its sing. is <span class=\"ar\"> <span class=\"ar\">ظِلْمَةٌ</span></span>, (T,) accord. to AHn, <i>A certain herb,</i> (M, K, TA,) <i>which is depastured;</i> (M, TA;) accord. to IAar, <i>a strange kind of tree;</i> (T, TA;) accord. to As, <i>a kind of tree</i> (T, TA *) <i>having long</i> [<i>shoots such as are termed</i>] <span class=\"ar\">عَسَالِيج</span> [pl. of <span class=\"ar\">عُسْلُوجٌ</span> q. v.], (T, K, TA,) <i>which extend so that they exceed the limit of the</i> <span class=\"ar\">أَصْل</span> [i. e. either <i>root</i> or <i>stem</i>] <i>thereof;</i> for which reason the tree is called <span class=\"ar\">ظَلَّام</span>. (T, TA.)</p><p><b class=\"ar\">ظِلِّيمٌ</b> : see <span class=\"ar\">ظَلَّامٌ</span>.</p><p><b class=\"ar\">ظَالِمٌ</b> [<i>Acting wrongfully, unjustly, injuriously,</i> or <i>tyrannically:</i> and <i>wronging;</i> or <i>treating,</i> or <i>using, wrongfully,</i> &amp;c.:] part. n. of <span class=\"ar\">ظَلَمَ</span>: (M, K:) and <span class=\"ar\"> <span class=\"ar\">مُتَظَلِّمٌ</span></span> signifies the same; as well as <i>complaining of his wrongdoer:</i> (T:) [the pl. of the former is <span class=\"ar\">ظَالِمُونَ</span> and <span class=\"ar\">ظَلَمَةٌ</span>:] and <span class=\"ar\">ظَلَمَةٌ</span> signifies those <i>who debar men from,</i> or <i>refuse to them, their rights,</i> or <i>dues.</i> (IAar, T, TA.) -A2- See also <span class=\"ar\">ظِلَّامٌ</span>.</p><p><b class=\"ar\">أَظْلَمُ</b> [<i>More,</i> and <i>most, wrongful, unjust, injurious,</i> or <i>tyrannical, in conduct</i>]. El-Muärrij says, I heard an Arab of the desert say to his companion, <span class=\"ar\">أَظْلَمِى وَأَظْلَمُكَ فَفَعَلَ ٱللّٰهُ بِهِ</span>, meaning <i>The more wrongful in conduct of me and of thee</i> [<i>may God do to him</i> what He will do; i. e. may God punish him]. (T.) [And] one says, <span class=\"ar\">لَعَنَ</span> <span class=\"ar\">ٱللّٰهُ أَظْلَمِى وَأَظْلَمَكَ</span> i. e. [<i>May God curse</i>] <i>the more wrongful in conduct of us.</i> (K. [But in the TA, a doubt is intimated as to the correctness of this latter saying.]) One says also, <span class=\"ar\">لَهُوَ أَظْلَمُ</span> <span class=\"ar\">مِنْ حَيَّةٍ</span> [i. e. <i>Verily he is more wrongful in conduct than a serpent</i>]: because it comes to a burrow which it has not excavated, and makes its abode in it: (Fr, T:) for it comes to the burrow of the [lizard called] <span class=\"ar\">ضَبّ</span>, and eats its young one, and takes up its abode in its burrow. (TA voce <span class=\"ar\">حَيَّةٌ</span>.) -b2- And <span class=\"ar\">الأَظْلَمُ</span> is an appellation of <i>The</i> <span class=\"ar\">ضَبّ</span>; because it eats its young ones. (TA.)</p><p><b class=\"ar\">مُظْلِمٌ</b> [<i>Becoming dark,</i> &amp;c.: see its verb, 4]. -b2- [Hence,] <span class=\"ar\">شَعَرٌ مُظْلِمٌ</span> (tropical:) <i>Hair intensely black.</i> (M, K, TA.) And <span class=\"ar\">نَبْتٌ مُظْلِمٌ</span> (tropical:) <i>A plant intensely green, inclining to blackness by reason of its</i> [<i>deep</i>] <i>greenness.</i> (M, K, TA.) And <span class=\"ar\">يَوْمٌ مُظْلِمٌ</span> (tropical:) <i>A day of much evil:</i> (K, TA:) or <i>a very evil day:</i> and <i>a day in which one finds hardship,</i> or <i>difficulty.</i> (M.) And <span class=\"ar\">أَمْرٌ مُظْلِمٌ</span> (tropical:) <i>An affair such that one knows not how to enter upon it;</i> (AZ, M, K;) and so <span class=\"ar\">أَمْرٌ <span class=\"ar\">مِظْلَامٌ</span></span>: (K:) [or,] accord. to Lh, one says <span class=\"ar\">يَوْمٌ <span class=\"ar\">مِظْلَامٌ</span></span>, meaning (assumed tropical:) <i>a day such that one knows not how to enter upon it.</i> (M.)</p><p><b class=\"ar\">مَظْلِمَةٌ</b> and <span class=\"ar\">مَظْلَمَةٌ</span>: see 1, near the beginning. -b2- Also the former, (T, S, M, Mgh, Msb, K,) and the latter likewise, mentioned by Ibn-Málik and ISd and IKtt, and <span class=\"ar\">مَظْلُمَةٌ</span>, which is disallowed by several but mentioned on the authority of Fr, and all three are mentioned in the Towsheeh and in copies of the S, (MF, TA,) and <span class=\"ar\"> <span class=\"ar\">ظُلَامَةٌ</span></span>, (T, S, M, Mgh, Msb, K,) and <span class=\"ar\"> <span class=\"ar\">ظَلِيمَةٌ</span></span>, (S, TA,) <i>A thing of which one has been defrauded;</i> (M, K; [in the CK, <span class=\"ar\">تَظَلَّمَهُ</span> is erroneously put for <span class=\"ar\">تُظُلِّمَهُ</span>;]) <i>a thing of which thou hast been defrauded,</i> (<span class=\"ar\">اَلَّتِى</span> <span class=\"ar\">ظُلِمْتَهَا</span>, T,) or <i>a thing that thou demandest,</i> (<span class=\"ar\">مَا</span> <span class=\"ar\">تَطْلُبُهُ</span>, S, Msb,) <i>in the possession of the wrongdoer;</i> (T, S, Msb;) a term for <i>a thing that has been taken from thee;</i> (S; [thus, as is said in the M, the first is expl. by Sb;]) <i>a right,</i> or <i>due, that has been taken from one wrongfully:</i> (A, Mgh:) the pl. of <span class=\"ar\">مظلمة</span> is <span class=\"ar\">مَظَالِمُ</span>. (Mgh, TA.) In the phrase <span class=\"ar\">يَوْمُ المَظَالِمِ</span>, [meaning <i>The day</i> of the demand <i>of things wrongfully taken,</i> and particularly applied to the great day of judgment,] the prefixed noun [i. e. <span class=\"ar\">طَلَبِ</span>] is suppressed. (Mgh.) [Respecting the office termed <span class=\"ar\">النَّظَرُ</span> <span class=\"ar\">فِى المَظَالِمِ</span> <i>The examination into wrongful exactions,</i> see De Sacy's Chrest. Ar., see. ed., i. 132.]</p><p><b class=\"ar\">مُظَلَّمٌ</b> (assumed tropical:) A house, or chamber, <i>decorated with pictures;</i> (M, TA;) as though the pictures were put therein where they should not be: it is related in a trad. that the Prophet, having been invited to a repast, saw the house, or chamber, to be <span class=\"ar\">مُظَلَّم</span>, and turned away, not entering: (M:) or <i>adorned with gilding and silvering;</i> an explanation disapproved by Az, but pronounced by Z to be correct, from <span class=\"ar\">الظَّلْمُ</span> signifying “ the lustre, and brightness, of gold. ” (TA.) -b2- And (assumed tropical:) Herbage <i>spreading</i> (<span class=\"ar\">مُنْبَثٌّ</span> [in the CK <span class=\"ar\">مُنْبَت</span>]) <i>upon the ground, not rained upon.</i> (K, TA.) -b3- Also, of birds, (assumed tropical:) The <span class=\"ar\">رَخَم</span> [or <i>vultur percnopterus</i>], and <i>crows,</i> or <i>ravens.</i> (IAar, M, K. *)</p><p><b class=\"ar\">مِظْلَامٌ</b> : see <span class=\"ar\">مُظْلِمٌ</span>, in two places.</p><p><b class=\"ar\">مَظْلُومٌ</b> [<i>Wronged; treated,</i> or <i>used, wrongfully, unjustly, injuriously,</i> or <i>tyrannically:</i> -b2- and hence used in other senses]: see <span class=\"ar\">ظَلِيمٌ</span>, in three places. <span class=\"ar\">أَرْضٌ مَظْلُومَةٌ</span> is also expl. as meaning (tropical:) <i>Land that is dug in a place not proper for digging:</i> (TA:) or <i>land in which a watering-trough has been dug, not being a proper place for digging it:</i> (ISk, M:) or <i>land in which a well,</i> or <i>a wateringtrough, has been dug, when there had not been any digging therein:</i> (A, TA:) or <i>hard land, when it is dug.</i> (Ham p. 56.) Also (assumed tropical:) <i>Land upon which rain has not fallen.</i> (T.) And <span class=\"ar\">بَلَدٌ</span> <span class=\"ar\">مَظْلُومٌ</span> (assumed tropical:) <i>A country upon which rain has not fallen, and wherein is no pasturage for the camels upon which people journey.</i> (T.)</p><p><b class=\"ar\">مُتَظَلِّمٌ</b> : see <span class=\"ar\">ظَالِمٌ</span>.</p>"},"ظنن":{"mf":"الظَّنُّ: اسم لما يحصل عن أمارة، ومتى قويت أدّت إلى العلم، ومتى ضعفت جدّا لم يتجاوز حدّ التّوهّم، ومتى قوي أو تصوّر تصوّر القويّ استعمل معه (أنّ) المشدّدة، و (أن) المخفّفة منها. ومتى ضعف استعمل أن المختصّة بالمعدومين من القول والفعل <strong>«٤»</strong>، فقوله: الَّذِينَ يَظُنُّونَ أَنَّهُمْ مُلاقُوا رَبِّهِمْ<br>[البقرة/ ٤٦]، وكذا: يَظُنُّونَ أَنَّهُمْ مُلاقُوا اللَّهِ [البقرة/ ٢٤٩]، فمن اليقين، وَظَنَّ أَنَّهُ الْفِراقُ<br><strong>[القيامة/ ٢٨]، وقوله:</strong><br>أَلا يَظُنُّ أُولئِكَ<br>[المطففين/ ٤]، وهو نهاية في ذمّهم. ومعناه: ألا يكون منهم ظَنٌّ لذلك تنبيها أنّ أمارات البعث ظاهرة. وقوله: وَظَنَّ أَهْلُها أَنَّهُمْ قادِرُونَ عَلَيْها [يونس/ ٢٤]، تنبيها أنهم صاروا في حكم العالمين لفرط طمعهم وأملهم، وقوله: وَظَنَّ داوُدُ أَنَّما فَتَنَّاهُ<br>[ص/ ٢٤]، أي: علم، والفتنة هاهنا. كقوله:<br>وَفَتَنَّاكَ فُتُوناً [طه/ ٤٠]، وقوله: وَذَا النُّونِ إِذْ ذَهَبَ مُغاضِباً فَظَنَّ أَنْ لَنْ نَقْدِرَ عَلَيْهِ<br>[الأنبياء/ ٨٧]، فقد قيل: الأولى أن يكون من الظَّنِّ الذي هو التّوهّم، أي: ظَنَّ أن لن نضيّق عليه <strong>«٥»</strong>. وقوله: وَاسْتَكْبَرَ هُوَ وَجُنُودُهُ فِي الْأَرْضِ بِغَيْرِ الْحَقِّ وَظَنُّوا أَنَّهُمْ إِلَيْنا لا يُرْجَعُونَ<br>[القصص/ ٣٩]، فإنّه استعمل فيه (أنّ) المستعمل مع الظَّنِّ الذي هو للعلم، تنبيها أنهم اعتقدوا ذلك اعتقادهم للشيء المتيقّن وإن لم<br><br>يكن ذلك متيقنا، وقوله: يَظُنُّونَ بِاللَّهِ غَيْرَ الْحَقِّ ظَنَّ الْجاهِلِيَّةِ<br><strong>[آل عمران/ ١٥٤]، أي:</strong><br>يَظُنُّونَ أنّ النبيّ صلّى الله عليه وسلم لم يصدقهم فيما أخبرهم به كما ظَنَّ الجاهليّة، تنبيها أنّ هؤلاء المنافقين هم في حيّز الكفار، وقوله: وَظَنُّوا أَنَّهُمْ مانِعَتُهُمْ حُصُونُهُمْ<br>[الحشر/ ٢]، أي: اعتقدوا اعتقادا كانوا منه في حكم المتيقّنين، وعلى هذا قوله:<br>وَلكِنْ ظَنَنْتُمْ أَنَّ اللَّهَ لا يَعْلَمُ كَثِيراً مِمَّا تَعْمَلُونَ<br>[فصلت/ ٢٢]، وقوله: الظَّانِّينَ بِاللَّهِ ظَنَّ السَّوْءِ<br>[الفتح/ ٦]، هو مفسّر بما بعده، وهو قوله: بَلْ ظَنَنْتُمْ أَنْ لَنْ يَنْقَلِبَ الرَّسُولُ [الفتح/ ١٢]، إِنْ نَظُنُّ إِلَّا ظَنًّا<br>[الجاثية/ ٣٢]، والظَّنُّ في كثير من الأمور مذموم، ولذلك قال تعالى: وَما يَتَّبِعُ أَكْثَرُهُمْ إِلَّا ظَنًّا<br>[يونس/ ٣٦]، وَإِنَّ الظَّنَ<br>[النجم/ ٢٨]، وَأَنَّهُمْ ظَنُّوا كَما ظَنَنْتُمْ<br>[الجن/ ٧]، وقرئ: وما هو على الغيب بِظَنِينٍ <strong>«١»</strong> أي: بمتّهم.","mq":[["معنيين مختلفين: يقين وشك"],"الظاء والنون أُصَيْل صحيحٌ يدلُّ على معنيينِ مختلفين:<br>يقين وشكّ.<br>فأمَّا اليقين فقولُ القائل: ظننت ظنا، أى أيقنت. قال اللّه تعالى: ﴿قالَ اَلَّذِينَ يَظُنُّونَ أَنَّهُمْ مُلاقُوا اَللّهِ﴾ أراد، واللّه أعلم، يوقنون. والعربُ تقول (٣) ذلك وتعرفه. قال شاعرهم (٤)<br>:<br>فقلت لهم ظُنُّوا بألَفْى مُدَجَّجٍ … سرات"],"ln":"<p><b>1.</b> <b class=\"ar\">ظَنَّ</b> , aor. <b class=\"ar\">ظَنُنَ</b> , inf. n. <span class=\"ar\">ظَنٌّ</span>, (Msb,) [<i>He thought, opined, supposed,</i> or <i>conjectured:</i> and <i>he doubted:</i> and <i>he knew,</i> but <i>not by ocular perception:</i> see <span class=\"ar\">ظَنٌّ</span> below:] you say, <span class=\"ar\">ظَنَنْتُ الشَّىْءَ</span>, aor. <span class=\"ar\">أَظُنُّهُ</span>, inf. n. <span class=\"ar\">ظَنٌّ</span>; and <span class=\"ar\"> <span class=\"ar\">اِظَّنَنْتُهُ</span></span> and <span class=\"ar\">اِظْطَنَنْتُهُ</span>; and <span class=\"ar\"> <span class=\"ar\">تَظَنَّنْتُهُ</span></span> and <span class=\"ar\">تَظَنَّيْتُهُ</span>, this last formed by changing the last <span class=\"ar\">ن</span> into <span class=\"ar\">ى</span>: [i. e. <i>I thought the thing,</i> &amp;c:] and Lh mentions, as heard from the Benoo-Suleym, <span class=\"ar\">ظَنْتُ ذَاكَ</span> i. e. <span class=\"ar\">ظَنَنْتُ ذاك</span> [<i>I thought that,</i> &amp;c.] like <span class=\"ar\">ظَلْتُ</span> and other instances of the dial. of Suleym. (M.) [In the first of the senses expl. above, it governs two objective complements, which are originally an inchoative and an enunciative:] you say, <span class=\"ar\">ظَنَنْتُكَ زَيْدًا</span> [<i>I thought thee Zeyd,</i> originally <i>I thought thou wast Zeyd</i>], and <span class=\"ar\">ظَنَنْتُ زَيْدًا إِيَّاكَ</span> [<i>I thought Zeyd thee,</i> originally <i>I thought Zeyd was thou</i>], denoting by a pronoun what is originally an inchoative [in the former phrase] and what is originally an enunciative [in the latter phrase]. (S, TA.) It is also used [in this sense] in the same manner as a verb signifying an oath, the Arabs giving it the same kind of complement, saying, <span class=\"ar\">ظَنَنْتُ لَعَبْدُ</span> <span class=\"ar\">ٱللّٰهِ خَيْرٌ مِنْكَ</span> [<i>I thought surely 'Abd-Allah was better than thou</i>]. (S in art. <span class=\"ar\">درد</span>.) [<span class=\"ar\">ظَنَّ بِهِ كَذَا</span> means <i>I thought of him,</i> or <i>it, such a thing:</i> and <i>I thought such a thing to be in him,</i> or <i>it:</i> and is used in relation to good and to evil.] It is said in the Kur [xxxiii. 10], <span class=\"ar\">وَتَطُنُّونَ بِٱللّٰهِ ٱلظُّنُونَا</span> [<i>And ye were thinking, of God,</i> various <i>thoughts</i>]. (M.) Accord. to Sb, <span class=\"ar\">ظَنَنْتُ بِهِ</span> means <i>I made him,</i> or <i>it, the place</i> [i. e. <i>object</i>] <i>of my</i> <span class=\"ar\">ظَنّ</span> [or <i>thought,</i> &amp;c.]. (M.) [In all these exs. the verb denotes a state of mind between doubt and certainty, but the latter is predominant: and hence <span class=\"ar\">ظَنَّ</span> sometimes means <i>He doubted:</i> and sometimes, <i>he knew, by considering with endeavour to understand, not by ocular perception;</i> being more frequently used in this sense than as meaning “ he doubted, ” though not so frequently as it is in the sense of “ he thought, ” whence the meaning “ he knew ” is held by some to be tropical.] <span class=\"ar\">إِنَّى</span>, <span class=\"ar\">ظَنَنْتُ أَنِّى مُلَاقٍ حِسَابِيَهْ</span>, in the Kur [lxix. 20], means <i>Verily I knew</i> [<i>that I should meet with my reckoning</i>]. (T.) And <span class=\"ar\">ٱلَّذِينَ يَظُنُّونَ أَنَّهُمْ مُلَاقُو</span> <span class=\"ar\">رَبِّهِمْ</span>, in the same [ii. 43], means <i>Who know</i> [<i>that they shall meet their Lord,</i> lit., <i>be meeters of their Lord</i>]. (Msb.) And <span class=\"ar\">ظَنَنْتُ مَا قَالَ</span>, occurring in a trad., means <i>I knew</i> [<i>what he meant to say</i> by his making a sign with his hand]. (TA.) -b2- <span class=\"ar\">ظَنَنْتُهُ</span>, (M, Mgh, Msb,) aor. as above, (Msb,) and so the inf. n., (M,) signifies also <i>I suspected him; thought evil of him;</i> (M, Mgh, Msb;) and (M) so <span class=\"ar\"> <span class=\"ar\">اِظَّنَنْتُهُ</span></span> (S, M, Mgh, K) and <span class=\"ar\">اِظْطَنَنْتُهُ</span> (M, TA) and <span class=\"ar\">اِطَّنَنْتُهُ</span>. (TA.) [Thus, too, <span class=\"ar\"> <span class=\"ar\">أَظْنَنْتُهُ</span></span> accord. to several copies of the S and accord. to the CK; but this is app. a mistranscription.] In the saying of Ibn-Seereen, <span class=\"ar\">لَمْ يَكُنْ عَلِىٌّ <span class=\"ar\">يُظَّنُّ</span> فِى قَتْلِ عُثْمَانَ</span>, (T, S, K, but in the T <span class=\"ar\">مَا كَان</span>,) meaning <i>Alee was not suspected</i> [<i>in the case of the slaying of 'Othmán</i>], (T,) <span class=\"ar\">يُظَّنُّ</span> is of the measure <span class=\"ar\">يُفْتَعَلُ</span>, originally <span class=\"ar\">يُظْتَنُّ</span>: (T, S, K:) so says A'Obeyd: (T:) or, as some relate it, the word is <span class=\"ar\">يُطَّنُّ</span>. (TA.) One says, <span class=\"ar\">هُوَ <span class=\"ar\">يُظَّنُّ</span>بِكَذَا</span> and <span class=\"ar\">يُطَّنُّ</span>, meaning <i>He is suspected of such a thing.</i> (TA in art. <span class=\"ar\">طن</span>.) And <span class=\"ar\">طَنَنْتُ بِزَيْدٍ</span> and <span class=\"ar\">ظَنَنْتُ زَيْدًا</span> <i>I suspected Zeyd:</i> in this sense the verb has a single objective complement. (TA.)</p><p><b>4.</b> <b class=\"ar\">أَظْنَنْتُهُ الشَّىْءَ</b> <i>I made him to think the thing.</i> (M, TA.) -b2- And <span class=\"ar\">أَظْنَنْتُ بِهِ النَّاسَ</span> [<i>I made the people to suspect him:</i> or] <i>I exposed him to suspicion;</i> (M, Msb, TA;) [and] so <span class=\"ar\">أَظنَنْتُهُ</span> [alone]. (K.) -b3- See also 1, last quarter.</p><p><b>5.</b> <b class=\"ar\">التَّظَنِّى</b> means <i>The exercising, employing,</i> or <i>using, of</i> <span class=\"ar\">الظَّنّ</span> [i. e. <i>thought,</i> &amp;c.]; originally <span class=\"ar\">التَّظَنُّنُ</span>. (S, K.) A'Obeyd says, <span class=\"ar\">تَظَنَّيْتُ</span> is from <span class=\"ar\">ظَنَنْتُ</span>, and is originally <span class=\"ar\">تَظَنَّنْتُ</span>; the <span class=\"ar\">ن</span> being many, one of them is changed into <span class=\"ar\">ى</span>: it is like <span class=\"ar\">قَصَّيْتُ</span>, which is originally <span class=\"ar\">قَصَّصْتُ</span>. (T.) -A2- See also 1, first sentence.</p><p><b>8.</b> <b class=\"ar\">إِظْتَنَنَ</b> see 1, first sentence: -b2- and again, in the last quarter, in three places.</p><p><b class=\"ar\">ظَنٌّ</b> is a simple subst. as well as an inf. n.; (TA;) and signifies <i>Thought, opinion, supposition,</i> or <i>conjecture:</i> (Er-Rághib, Mgh, TA:) or <i>a preponderant belief, with the admission that the contrary may be the case:</i> (KT, El-Munáwee, TA:) or <i>a preponderating wavering between the two extremes in indecisive belief:</i> (K:) or <i>an inference from a sign,</i> or <i>mark,</i> or <i>token; when strong, leading to knowledge; and when weak, not exceeding the limit of</i> <span class=\"ar\">وَهْم</span>: (Er-Rághib, TA:) or <i>doubt</i> or <i>uncertainty;</i> (T, M;) or it has this meaning also; (Er-Rághib, TA;) <i>contr. of</i> <span class=\"ar\">يَقِينٌ</span>: (Msb:) and sometimes it is put in the place, (S, K,) or used in the sense, (Mgh, Msb,) of <span class=\"ar\">عِلْمٌ</span>, (S, Mgh, K,) or <span class=\"ar\">يَقِينٌ</span>, (Msb,) [i. e. <i>knowledge,</i> or <i>certainty,</i>] in which sense it is [held by some to be] tropical; (Mgh;) or it signifies also <i>knowledge,</i> or <i>certainty,</i> (<span class=\"ar\">يَقِينٌ</span>, T, M,) <i>such as is obtained by considering with endeavour to understand, not by ocular perception,</i> (M,) or <i>not such as relates to an object of sense:</i> (MF:) and it also means <i>suspicion,</i> or <i>evil opinion:</i> (Er-Rághib, TA: [but in this last sense, <span class=\"ar\">ظِنَّةٌ</span> is more common:]) as a subst., (TA,) its pl. is <span class=\"ar\">ظُنُونٌ</span> and <span class=\"ar\">أَظَانِينُ</span>, (M, K, TA,) the latter anomalous, or (as ISd says, TA) it may be pl. of <span class=\"ar\"> <span class=\"ar\">أُظْنُونَةٌ</span></span>, but this I do not know. (M, TA.) One says, <span class=\"ar\">هُوَ سَيِّئُ الظَّنِّ بِكُلِّ أَحَدٍ</span> [<i>He is evil in opinion of everyone</i>]. (M.) [And <span class=\"ar\">سَآءَ ظَنُّهُ بِفُلَانٍ</span> <i>His opinion of such a one was evil.</i>] And <span class=\"ar\">عِلْمُهُ</span> <span class=\"ar\">بِالشَّىْءِ ظُنُونٌ</span> [<i>His knowledge is</i> but <i>opinions</i>]; meaning that no confidence is to be placed in him. (TA.)</p><p><b class=\"ar\">ظِنَّةٌ</b> <i>Suspicion,</i> or <i>evil opinion;</i> (T, S, M, Mgh, Msb, K;) as also <span class=\"ar\">طِنَّةٌ</span>; the <span class=\"ar\">ظ</span> being changed into <span class=\"ar\">ط</span>, though there is no <span class=\"ar\">إِدْغَام</span> in this case, because of their being accustomed to say <span class=\"ar\">اِطَّنَّ</span> [for <span class=\"ar\">اِظَّنَّ</span>, which is for <span class=\"ar\">اِظْطَنَّ</span>]; an instance like <span class=\"ar\">الدِّكْرُ</span>, which is made to accord with <span class=\"ar\">اِدَّكَرَ</span> [for <span class=\"ar\">اِذَّكَرَ</span>, which is for <span class=\"ar\">اِذْدَكَرَ</span>], as mentioned by Sb; (M;) and <span class=\"ar\"> <span class=\"ar\">ظَنَانَةٌ</span></span>, (so accord. to a copy of the M,) or <span class=\"ar\"> <span class=\"ar\">ظِنَانَةٌ</span></span>, like <span class=\"ar\">كِتَابَةٌ</span>, (TA,) signifies the same: (M, TA:) the pl. of <span class=\"ar\">ظِنَّةٌ</span> is <span class=\"ar\">ظِنَنٌ</span>. (S, K.) One says, <span class=\"ar\">عِنْدَهُ ظِنَّتِى</span> and <span class=\"ar\">هُوَ ظِنَّتِى</span>, meaning <i>He is the place</i> [i. e. <i>object</i>] <i>of my suspicion.</i> (TA.) -b2- And [hence] (assumed tropical:) <i>A little</i> [like the French “ soupçon ”] of a thing. (TA.)</p><p><b class=\"ar\">ظُنَنٌ</b> : see <span class=\"ar\">ظَنَّانٌ</span>.</p><p><b class=\"ar\">ظَنُونٌ</b> A man <i>who thinks evil</i> (S, M) <i>of everyone.</i> (M.) -b2- A man <i>possessing little good</i> or <i>goodness:</i> or, as some say, <i>of whom one asks</i> [<i>a thing</i>] <i>thinking that he will refuse, and who is as he was thought to be:</i> (M:) [or] <span class=\"ar\"> <span class=\"ar\">ظَنِينٌ</span></span> has this latter meaning. (TA.) -b3- A man <i>in whose goodness no trust,</i> or <i>confidence, is to be placed.</i> (M.) And Anything <i>in which no trust,</i> or <i>confidence, is to be placed,</i> (M, TA,) of water, and of other things; (TA;) as also <span class=\"ar\"> <span class=\"ar\">ظَنِينٌ</span></span>. (M, TA.) A well (<span class=\"ar\">بِئْرٌ</span>) <i>having little water,</i> (S, M, K,) <i>in the water of which no trust,</i> or <i>confidence, is to be placed:</i> (M:) or a well, (S, K,) or a drinkingplace, (M,) <i>of which one knows not whether there be in it water or not:</i> (S, M, K:) or water <i>which one imagines,</i> or <i>supposes, to exist, but of which one is not sure.</i> (TA.) <span class=\"ar\">كُلُّ مَنِيَّةٍ ظَنُونٌ</span> <span class=\"ar\">إِلَّا القَتْلَ فِى سَبِيلِ ٱللّٰهِ</span> is a saying mentioned, but not expl., by IAar; [app. meaning <i>Every death is doubtful as to its consequence except slaughter in the way,</i> or <i>cause, of God;</i> but ISd says,] in my opinion the meaning is that it <i>is of little good and profit.</i> (M.) <span class=\"ar\">دَيْنٌ ظَنُونٌ</span> means <i>A debt of which one knows not whether he who owes it will pay it or not:</i> (A'Obeyd, T, S, M, * K:) it is said in a trad. of 'Omar that there is no poorrate in the case of such a debt. (TA.) -b4- Also A man <i>suspected in relation to his intellect,</i> or <i>intelligence.</i> (Aboo-Tálib, TA.) And A woman <i>suspected in relation to her grounds of pretension to respect,</i> or <i>honour, on account of lineage &amp;c.</i> (TA.) And A woman <i>of noble rank</i> or <i>quality, who is taken in marriage,</i> (M, K,) <i>from a desire of obtaining off spring by her, when she is advanced in age.</i> (M.) -b5- Also A <i>weak</i> man. (K. [See also <span class=\"ar\">ظَنينٌ</span>.]) -b6- And A man <i>having little artifice, cunning, ingenuity,</i> or <i>skill.</i> (K.)</p><p><b class=\"ar\">ظَنِينٌ</b> <i>Suspected;</i> (T, S, M, Mgh, Msb, K;) applied to a man; (S, M;) <i>i. q.</i> <span class=\"ar\"> <span class=\"ar\">مَظْنُونٌ</span></span>, (Mbr, Msb,) in this sense: (Msb:) pl. <span class=\"ar\">أَظِنَّآءُ</span>. (M, TA.) Thus in the saying in the Kur [lxxxi. 24], <span class=\"ar\">وَمَا هُوَ عَلَى ٱلْغَيْبِ بِظَنِينٍ</span>, (T, M, Msb,) meaning <i>And he is not suspected as to</i> what he makes known from God, of the knowledge of <i>that which is undiscoverable,</i> as is related on the authority of 'Alee: or, accord. to Fr, it may mean <i>weak;</i> for <span class=\"ar\">ظَنِينٌ</span> may have this meaning like as <span class=\"ar\">ظَنُونٌ</span> has: (T:) some read <span class=\"ar\">بِضَنينٍ</span>. (TA in art. <span class=\"ar\">ضن</span>, q. v.) <span class=\"ar\">شَهَادَةُ ظَنِينٍ</span>, which is said in a trad. to be not allowable, is <i>The testimony of one who is suspected</i> as to his religion. (TA.) And <span class=\"ar\"> <span class=\"ar\">ظَنَّآءُ</span>نَفْسٌ</span> means [<i>A soul,</i> or <i>person,</i>] <i>suspected.</i> (TA.) -b2- Also One <i>who treats</i> or <i>regards another,</i> or <i>others, with enmity,</i> or <i>hostility;</i> (T, M;) because of his evil opinion and the evil opinion of which he is an object. (M.) -b3- See also <span class=\"ar\">ظَنُونٌ</span>, in two places.</p><p><b class=\"ar\">ظَنَانَةٌ</b> or <span class=\"ar\">ظِنَانَةٌ</span>: see <span class=\"ar\">ظِنَّةٌ</span>.</p><p><b class=\"ar\">ظَنَّآءُ</b> : see <span class=\"ar\">ظَنِينٌ</span>.</p><p><b class=\"ar\">ظَنَّانٌ</b> One <i>who opines,</i> or <i>conjectures, much</i> [and] <i>in an evil manner;</i> as also <span class=\"ar\"> <span class=\"ar\">ظُنَنٌ</span></span>. (TA.)</p><p><b class=\"ar\">أَظَنُّ</b> [<i>Such as is more,</i> or <i>most, fit that one should think of him</i> to do a thing]. You say, <span class=\"ar\">نَظَرْتُ إِلَى أَظَنِّهِمْ أَنْ يَفْعَلَ ذٰلِكَ</span> <i>I looked towards him who was the most fit of them that I should think of him to do that.</i> (M, TA.)</p><p><b class=\"ar\">أُظْنُونَةٌ</b> : see <span class=\"ar\">ظَنٌّ</span>, near the end.</p><p><b class=\"ar\">مَظِنَّةٌ</b> , (M, Mgh, Msb, TA,) of which <span class=\"ar\">مَظَنَّةٌ</span>, mentioned by Ibn-Málik and others, and <span class=\"ar\">مِظَنَّةٌ</span>, are dial. vars., (TA,) or [rather] <span class=\"ar\">مَظِنَّةُ شَىْءٍ</span>, (IF, S, Msb, K, TA,) signifies The <i>place,</i> (IF, S, Msb, K, TA,) and the <i>accustomed place,</i> (IF, S, Msb, TA,) <i>in which is thought to be the existence,</i> (S, K, TA,) <i>of a thing;</i> (IF, S, Msb, K, TA;) [<i>a place</i>] <i>where a thing is thought to be:</i> (M:) or it signifies, (Mgh, Msb,) or signifies also, (S,) <i>a place where a thing is known to be:</i> (S, Mgh, Msb:) [<i>a thing,</i> and <i>a person, in which,</i> or <i>in whom, a thing,</i> or <i>quality, is thought, supposed, presumed, suspected, inferred, known,</i> or <i>accustomed, to be,</i> or <i>exist:</i>] accord. to IAth, by rule it should be <span class=\"ar\">مَظَنَّةٌ</span>: (TA:) [it may therefore be properly rendered <i>a cause of thinking,</i> &amp;c., <i>the existence</i> of a thing; and <span class=\"ar\">مَظِنَّةٌ لِكَذَا</span> may be well expl. as meaning <i>a thing,</i> and <i>a person, that occasions one's thinking, supposing, presuming suspecting, inferring,</i> or <i>knowing, the existence of such a thing</i> or <i>quality, in it,</i> or <i>in him:</i> and hence, <i>an indication,</i> or <i>evidence,</i> or <i>a symptom, diagnostic, characteristic, sign, mark,</i> or <i>token, of the existence of such a thing</i> or <i>quality:</i>] the pl. is <span class=\"ar\">مَظَانُّ</span>. (M, Mgh, Msb, TA.) One says, <span class=\"ar\">مَوْضِعُ</span> <span class=\"ar\">كَذَا مَظِنَّةٌ مِنْ فُلَانٍ</span> i. e. <i>Such a place is a place in which such a one is known</i> [&amp;c.] <i>to be.</i> (S, TA.) And <span class=\"ar\">فُلَانٌ مَظِنَّةٌ مِنْ كَذَا</span> i. e. <i>Such a one is one in whom such a thing,</i> or <i>quality, is known</i> [&amp;c.] <i>to be.</i> (Lh, T.) And <span class=\"ar\">فُلَانٌ مَظِنَّةٌ لِلْخَيْرِ</span> i. e. <i>Such a one is one in whom good,</i> or <i>goodness, is thought</i> [&amp;c.] <i>to be.</i> (Ham p. 437.) And En-Nábighah says, <span class=\"ar\">فَإِنْ يَكُ عَامِرٌ قَدْ قَالَ جَهْلًا</span> <span class=\"ar\">فَإِنَّ مَظِنَّةَ الجَهْلِ الشَّبَابُ</span> [<i>And if 'Ámir has spoken ignorantly, verily youthfulness is a state in which ignorance is usually found to exist</i>]: (S, Msb: *) or, as some relate the verse, <span class=\"ar\">السِّبَابُ</span> [so that the meaning is, <i>mutual reviling is an act in which</i> &amp;c.]: (S:) or, accord. to another relation, the latter hemistich is <span class=\"ar\">فَإِنَّ مَطِيَّةَ الجَهْلِ الشَّبَابُ</span> (S, * TA;) because one finds it [i. e. youthfulness] to be easy like as he does the beast on which one rides. (TA.) And one says also, <span class=\"ar\">طَلَبَهُ مَظَانَّهُ</span> [<i>He sought him,</i> or <i>it, in the places where he,</i> or <i>it, was thought to be;</i>] meaning, <i>by night and by day.</i> (TA.) And <span class=\"ar\">إِنَّهُ لَمَظِنَّةٌ أَنْ</span> <span class=\"ar\">يَفْعَلَ ذٰلِكَ</span> i. e. <i>Verily he is apt, meet, fitted,</i> or <i>suited, for one to think of his doing that:</i> and in like manner one says of two, and of a pl. number, and of a female. (Lh, M.)</p><p><b class=\"ar\">مَظْنُونٌ</b> [<i>Thought, opined,</i> &amp;c.: see its verb: and] see <span class=\"ar\">ظَنِينٌ</span>. Applied to a narrative, or story, it means [<i>Doubted;</i> or] <i>of which one is not to be made to know the real state.</i> (TA in art. <span class=\"ar\">رجم</span>.) In lexicology, A word <i>of the class termed</i> <span class=\"ar\">آحَادٌ</span> [q. v.]. (Mz 3rd <span class=\"ar\">نوع</span>.)</p>"},"ظهر":{"mf":"الظَّهْرُ الجارحةُ، وجمعه ظُهُورٌ. قال عزّ وجل:<br>وَأَمَّا مَنْ أُوتِيَ كِتابَهُ وَراءَ ظَهْرِهِ<br>[الانشقاق/ ١٠]، مِنْ ظُهُورِهِمْ ذُرِّيَّتَهُمْ<br>[الأعراف/ ١٧٢]، أَنْقَضَ ظَهْرَكَ<br>[الشرح/ ٣]، والظَّهْرُ هاهنا استعارة تشبيها للذّنوب بالحمل الذي ينوء بحامله، واستعير لِظَاهِرِ الأرضِ، فقيل: ظَهْرُ الأرضِ وبطنها. قال تعالى: ما تَرَكَ عَلى ظَهْرِها مِنْ دَابَّةٍ<br>[فاطر/ ٤٥]، ورجلٌ مُظَهَّرٌ: شديدُ الظَّهْرِ، وظَهِرَ: يشتكي ظَهْرَهُ.<br>ويعبّر عن المركوب بِالظَّهْرِ، ويستعار لمن يتقوّى به، وبعير ظَهِيرٌ: قويّ بيّن الظَّهَارَةِ، وظِهْرِيٌّ:<br>معدّ للرّكوب، والظِّهْرِيُّ أيضا: ما تجعله بِظَهْرِكَ فتنساه. قال تعالى: وَراءَكُمْ ظِهْرِيًّا<br>[هود/ ٩٢]، وَظَهَرَ عليه: غلبه، وقال: إِنَّهُمْ إِنْ يَظْهَرُوا عَلَيْكُمْ<br><strong>[الكهف/ ٢٠]، وظاهَرْتُهُ:</strong><br>عاونته. قال تعالى: وَظاهَرُوا عَلى إِخْراجِكُمْ<br>[الممتحنة/ ٩]، وَإِنْ تَظاهَرا عَلَيْهِ<br>[التحريم/ ٤]، أي: تعاونا، تَظاهَرُونَ عَلَيْهِمْ بِالْإِثْمِ وَالْعُدْوانِ<br>[البقرة/ ٨٥]، وقرئ: (تَظَّاهَرَا) <strong>«٢»</strong>، الَّذِينَ ظاهَرُوهُمْ<br>[الأحزاب/ ٢٦]، وَما لَهُ مِنْهُمْ مِنْ ظَهِيرٍ<br>[سبأ/ ٢٢]، أي: معين <strong>«٣»</strong>. فَلا تَكُونَنَّ ظَهِيراً لِلْكافِرِينَ<br>[القصص/ ٨٦]، وَالْمَلائِكَةُ بَعْدَ ذلِكَ ظَهِيرٌ<br>[التحريم/ ٤]، وَكانَ الْكافِرُ عَلى رَبِّهِ ظَهِيراً<br>[الفرقان/<br><br>٥٥]، أي: معينا للشّيطان على الرّحمن. وقال أبو عبيدة <strong>«١»</strong> : الظَّهِيرُ هو المَظْهُورُ به. أي: هيّنا على ربّه كالشّيء الذي خلّفته، من قولك:<br>ظَهَرْتُ بكذا، أي: خلفته ولم ألتفت إليه.<br>والظِّهَارُ: أن يقول الرّجل لامرأته: أنت عليّ كَظَهْرِ أمّي، يقال: ظَاهَرَ من امرأته. قال تعالى:<br>وَالَّذِينَ يُظاهِرُونَ مِنْ نِسائِهِمْ<br>[المجادلة/ ٣]، وقرئ: يظاهرون <strong>«٢»</strong> أي: يَتَظَاهَرُونَ، فأدغم، ويَظْهَرُونَ<br><strong>«٣»</strong>، وظَهَرَ الشّيءُ أصله:<br>أن يحصل شيء على ظَهْرِ الأرضِ فلا يخفى، وبَطَنَ إذا حصل في بطنان الأرض فيخفى، ثمّ صار مستعملا في كلّ بارز مبصر بالبصر والبصيرة. قال تعالى: أَوْ أَنْ يُظْهِرَ فِي الْأَرْضِ الْفَسادَ<br>[غافر/ ٢٦]، ما ظَهَرَ مِنْها وَما بَطَنَ<br>[الأعراف/ ٣٣]، إِلَّا مِراءً ظاهِراً<br>[الكهف/ ٢٢]، يَعْلَمُونَ ظاهِراً مِنَ الْحَياةِ الدُّنْيا<br>[الروم/ ٧]، أي: يعلمون الأمور الدّنيويّة دون الأخرويّة، والعلمُ الظَّاهِرُ والباطن تارة يشار بهما إلى المعارف الجليّة والمعارف الخفيّة، وتارة إلى العلوم الدّنيوية، والعلوم الأخرويّة، وقوله: باطِنُهُ فِيهِ الرَّحْمَةُ وَظاهِرُهُ مِنْ قِبَلِهِ الْعَذابُ<br>[الحديد/ ١٣]، وقوله: ظَهَرَ الْفَسادُ فِي الْبَرِّ وَالْبَحْرِ<br>[الروم/ ٤١]، أي: كثر وشاع، وقوله: نِعَمَهُ ظاهِرَةً وَباطِنَةً<br>[لقمان/ ٢٠]، يعني بالظَّاهِرَةِ: ما نقف عليها، وبالباطنة: ما لا نعرفها، وإليه أشار بقوله: وَإِنْ تَعُدُّوا نِعْمَةَ اللَّهِ لا تُحْصُوها [النحل/ ١٨]، وقوله: قُرىً ظاهِرَةً<br>[سبأ/ ١٨]، فقد حمل ذلك على ظَاهِرِهِ، وقيل: هو مثل لأحوال تختصّ بما بعد هذا الكتاب إن شاء الله، وقوله:<br>فَلا يُظْهِرُ عَلى غَيْبِهِ أَحَداً<br>[الجن/ ٢٦]، أي: لا يطلع عليه، وقوله: لِيُظْهِرَهُ عَلَى الدِّينِ كُلِّهِ<br>[التوبة/ ٣٣]، يصحّ أن يكون من البروز، وأن يكون من المعاونة والغلبة، أي: ليغلّبه على الدّين كلّه. وعلى هذا قوله: إِنْ يَظْهَرُوا عَلَيْكُمْ يَرْجُمُوكُمْ<br>[الكهف/ ٢٠]، وقوله تعالى: يا قَوْمِ لَكُمُ الْمُلْكُ الْيَوْمَ ظاهِرِينَ فِي الْأَرْضِ<br>[غافر/ ٢٩]، فَمَا اسْطاعُوا أَنْ يَظْهَرُوهُ<br>[الكهف/ ٩٧]، وصلاة الظُّهْرِ معروفةٌ، والظَّهِيرَةُ: وقتُ الظُّهْرِ، وأَظْهَرَ فلانٌ: حصل في ذلك الوقت، على بناء أصبح وأمسى <strong>«٤»</strong>. قال تعالى:<br>وَلَهُ الْحَمْدُ فِي السَّماواتِ وَالْأَرْضِ وَعَشِيًّا وَحِينَ تُظْهِرُونَ<br>[الروم/ ١٨].<br>تمّ كتاب الظاء<br><br>كتاب العين","mq":[["قوة وبروز"],"الظاء والهاء والراء أصلٌ صحيح واحدٌ يدلُّ على قوّة وبروز.<br>من ذلك ظَهَر الشئُ يظهر ظهوراً فهو ظاهر، إِذا انكشف وبرز. ولذلك سمِّى وقت الظُّهر والظَّهيرة، وهو أظهر أوقات النّهار وأضوؤُها. والأصل فيه كلّه ظهر الإنسان، وهو خلافُ بطنه، وهو يجمع البُروزَ والقوّة. ويقال للرِّكاب الظَّهر، لأنَّ الذى يَحمِل م"],"ln":"<p><b>1.</b> <b class=\"ar\">ظَهَرَ</b> , (S, Msb, K, &amp;c.,) aor. <b class=\"ar\">ظَهَرَ</b> , (Msb,) inf. n. <span class=\"ar\">ظُهُورٌ</span>, (S, Mgh, Msb, K, &amp;c.,) [<i>It was,</i> or <i>became, outward, exterior, external, extrinsic,</i> or <i>exoteric:</i> and hence,] <i>it appeared; became apparent, overt, open, perceptible</i> or <i>perceived, manifest, plain,</i> or <i>evident;</i> (S, Mgh, Msb, K, TA;) <i>after having been concealed,</i> or <i>latent:</i> (Msb, TA:) and <span class=\"ar\"> <span class=\"ar\">تظاهر</span></span> signifies the same. (Har p. 85.) Hence the phrase <span class=\"ar\">ظَهَرَ لِى رَأْىٌ</span> (assumed tropical:) [<i>An idea,</i> or <i>opinion, occurred to me</i>], said when one knows what he did not know before. (Msb.) [And <span class=\"ar\">هٰذَا مَا يَظْهَرُ لِى</span> (assumed tropical:) <i>This is what appears to me</i> to be the case, or to be the right way or course; or <i>this is my opinion.</i>] <span class=\"ar\">ظَهَرَ الحَمْلُ</span>, inf. n. as above, means <i>Pregnancy became apparent,</i> or <i>manifest:</i> it is said that this is not the case in less than three months. (Msb.) And it is said in a trad. of 'Áïsheh, <span class=\"ar\">كَانَ يُصَلِّى العَصْرَ</span> <span class=\"ar\">فِى حُجْرَتِى قَبْلَ أَنْ تَظْهَرَ</span> i. e. [<i>He used to perform the prayer of the afternoon in my chamber</i>] <i>before it</i> (meaning the sun) <i>became high and apparent:</i> (TA:) or <span class=\"ar\">وَالشَّمْسُ فِى حُجْرَتِى لَمْ تَظْهَرْ</span> <span class=\"ar\">بَعْدُ</span> i. e. [<i>when the sun was in my chamber,</i>] <i>it not having risen high</i> so as to be on the flat roof [thereof]: referring to the Prophet. (O. [But <span class=\"ar\">العَصْرَ</span> must be a mistranscription for <span class=\"ar\">الفَجْرَ</span>, i. e. <i>the prayer of the dawn.</i>]) The saying in the Kur [xxiv. 31], <span class=\"ar\">وَلَا يُبْدِينَ زِينَتَهُنَّ إِلَّا مَا ظَهَرَ مِنْهَا</span> [which is app. best rendered <i>And that they discover not their ornature except what is external thereof</i>] has been expl. in seven different ways, most correctly as meaning the clothes: (O, TA:) accord. to 'Áïsheh, it means the bracelet (<span class=\"ar\">القُلْب</span>) and the ring (<span class=\"ar\">الفَتَخَة</span>): and accord. to I'Ab, the hand and the signet-ring and the face. (TA.) -b2- Also <i>He went forth,</i> or <i>out,</i> (Mgh, TA,) <i>to the outside of a place.</i> (O, TA.) -b3- And <i>He</i> (a bird) <i>migrated,</i> or <i>went down,</i> from one country or region to another: used in this sense by AHn in relation to the vulture, migrating to Nejd. (L.) -b4- <span class=\"ar\">ظَهَرَ عَنْهُ</span>, said of a vice, or fault, (O, TA,) or a disgrace, (JK, A, O,) (tropical:) <i>It did not cleave to him;</i> (A, O, TA;) <i>it was remote from him;</i> (TA;) <i>it quitted him,</i> or <i>departed from him.</i> (JK.) -b5- <span class=\"ar\">ظَهَرْتُ بِهِ</span>, (O, TA,) inf. n. <span class=\"ar\">ظَهْرٌ</span>, (K,) (assumed tropical:) <i>I gloried,</i> or <i>boasted, by reason of it.</i> (O, K * TA.) [Respecting a meaning assigned to <span class=\"ar\">ظَهَرَ</span> <span class=\"ar\">بِفُلَانٍ</span> in the K, see 4.] -b6- <span class=\"ar\">أَكَلَ الرَّجُلُ أُكْلَةً</span> <span class=\"ar\">ظَهَرَ مِنْهَا ظَهْرَةً</span> means (assumed tropical:) [<i>The man ate some food</i>] <i>in consequence of which</i>] <i>he became fat.</i> (TA.) -A2- <span class=\"ar\">ظَهَرَهُ</span> <i>He mounted it; went,</i> or <i>got, upon it,</i> or <i>upon the top of it;</i> (S, A, * Mgh, O, Msb, K;) as also <span class=\"ar\">ظَهَرَ عَلَيْهِ</span>; (O;) namely, a house, (S,) or a house-top, (A, Mgh, O,) and a mountain, (A,) and a wall; (O, Msb;) properly, <i>he became upon its back:</i> (Mgh:) and [in like manner] one says, <span class=\"ar\"> <span class=\"ar\">ظَهَّرَ</span>فُلَانٌ نَجْدًا</span>, inf. n. <span class=\"ar\">تَظْهِيرٌ</span>, <i>Such a one mounted,</i> or <i>went up, upon the high region</i> (<span class=\"ar\">ظَهْر</span>) <i>of Nejd.</i> (O.) -b2- Hence, (Mgh, Msb,) <span class=\"ar\">ظَهَرَ عَلَيْهِ</span> (S, Mgh, O, Msb, K) and <span class=\"ar\">بِهِ</span>, (K,) inf. n. <span class=\"ar\">ظُهُورٌ</span> (Bd in xxiv. 31) and <span class=\"ar\">ظَهْرٌ</span> also, (Ham p. 301,) <i>He overcame, conquered, subdued, overpowered,</i> or <i>mastered, him; gained the mastery</i> or <i>victory,</i> or <i>prevailed, over him;</i> (S, Mgh, O, Msb, K;) namely, his enemy; (Msb;) and in like manner, [<i>he conquered, won, achieved,</i> or <i>attained, it,</i> i. e.] a thing. (O, TA.) [The saying <span class=\"ar\">فُلَانٌ لَا يَظْهَرُ</span> <span class=\"ar\">عَلَيْهِ أَحَدٌ</span> is expl. in the L and TA by the words <span class=\"ar\">اى لا يَسْلَم</span>, and said to be tropical: but Ibr D thinks that the correct reading is <span class=\"ar\">لا يُسَلِّمُ</span>, from <span class=\"ar\">التَّسْلِيمُ</span>; and that it is said of one who will not give up, or resign, what is in his hand; so that the meaning is, (tropical:) <i>Such a one is a person whom no one will overcome in respect of that which he holds in his possession.</i>] -b3- And [hence also] <span class=\"ar\">ظَهَرَ عَلَيْهِ</span>, (Msb, TA,) inf. n. <span class=\"ar\">ظُهُورٌ</span>, (TA,) <i>He knew, became acquainted with,</i> or <i>got knowledge of, him,</i> or <i>it.</i> (Msb, TA.) So in the Kur xxiv. 31, <span class=\"ar\">وَٱلطِّفْلُ</span> <span class=\"ar\">ٱلَّذِينَ لَمْ يَظْهَرُوا عَلَى عَوْرَاتِ ٱلنِّسَآءِ</span> [<i>And the young children</i>] <i>who have not attained knowledge of the</i> <span class=\"ar\">عورات</span>, (Bd, Jel,) meaning [<i>pudenda,</i> or] <i>parts between the navel and the knee,</i> (Jel,) <i>of women,</i> by reason of their want of discrimination: (Bd:) or (tropical:) <i>who have not attained to the generative faculty;</i> (O, Bd, * TA;) from <span class=\"ar\">الظُّهُورُ</span> in the sense of <span class=\"ar\">الغَلَبَةُ</span>. (Bd.) So too in the Kur [xviii. 19], <span class=\"ar\">إِنْ يَظْهَرُوا عَلَيْكُمْ</span> <i>If they get knowledge of you.</i> (O, TA.) -b4- And [hence] <span class=\"ar\">ظَهَرَ عَلَيْهِ</span>, (Fr, A, O, TA,) and <span class=\"ar\"> <span class=\"ar\">استظهرهُ</span></span>, (S, A, O, K,) (tropical:) <i>He knew it,</i> or <i>learned it, by heart;</i> namely, the Kur-án; (A, O, TA;) and <i>he recited it by heart:</i> (A, * TA; and so in the S and O in explanation of the latter:) or [simply] <i>he recited it by heart;</i> namely, the Kur-án; as also <span class=\"ar\"> <span class=\"ar\">اظهرهُ</span></span>: (O, K, TA:) in the copies of the K we find <span class=\"ar\">أَظْهَرْتُ عَلَى القُرْآنِ</span> and <span class=\"ar\">أَظْهَرْتُهُ</span>; but the former is a mistake for <span class=\"ar\">ظَهَرْتُ</span>, aor. <b class=\"ar\">ظَهَرَ</b> . (TA.) -A3- For another signification of <span class=\"ar\">ظَهَرَ عَلَيْهِ</span>, see 3. -A4- <span class=\"ar\">ظَهَرَ بِحَاجَتِى</span>, (S, A, K,) aor. <b class=\"ar\">ظَهَرَ</b> , (TA,) inf. n. <span class=\"ar\">ظَهْرٌ</span>; (TK;) and <span class=\"ar\"> <span class=\"ar\">ظهّرها</span></span>, (K, TA,) in some copies of the K <span class=\"ar\">ظَهَرَهَا</span>; (TA;) and <span class=\"ar\"> <span class=\"ar\">اظهرها</span></span>, (K,) inf. n. <span class=\"ar\">إِظْهَارٌ</span>; (TA;) and <span class=\"ar\"> <span class=\"ar\">اِظَّهَرَهَا</span></span>, (K,) of the measure <span class=\"ar\">اِفْتَعَلَ</span>; (TA;) (tropical:) <i>He held the object of my want in little,</i> or <i>light, estimation,</i> or <i>in contempt;</i> (S, A;) [lit.] <i>he put it behind</i> [<i>his</i>] <i>back;</i> (S, K;) <i>as though he put it away,</i> [<i>out of his sight,</i>] <i>and paid no regard to it.</i> (S, TA.) One says also, <span class=\"ar\">يَظْهَرُونَ بِهِمْ وَلَا يَلْتَفِتُونَ</span> <span class=\"ar\">إِلَى أَرْحَامِهِمْ</span> [<i>They hold them in contempt, and do not pay any regard to their ties of relationship</i>]. (S.) -b2- See also 10, in three places. -A5- <span class=\"ar\">ظَهَرَهُ</span>, (O, K,) aor. <b class=\"ar\">ظَهَرَ</b> , inf. n. <span class=\"ar\">ظَهْرٌ</span>, (K,) <i>He struck,</i> or <i>smote,</i> (TA,) or <i>hit,</i> or <i>hurt,</i> (O, K,) <i>his back.</i> (O, K, TA.) -A6- <span class=\"ar\">ظَهِرَ</span>, (S, O, K,) aor. <b class=\"ar\">ظَهَرَ</b> , (K,) inf. n. <span class=\"ar\">ظَهَرٌ</span>, (O, K,) <i>He</i> (a man, S, O) <i>had a complaint of his back.</i> (S, O, K.) -A7- <span class=\"ar\">ظَهُرَ</span>, (JK, O, L,) or <span class=\"ar\">ظَهَرَ</span>, (K, [but this is app. a mistranscription,]) inf. n. <span class=\"ar\">ظَهَارَةٌ</span>, (S, O, L, K,) said of a camel, (JK, S, O,) <i>He was,</i> or <i>became, strong</i> (JK, S, O, L, K) <i>in the back.</i> (L, K.)</p><p><b>2.</b> <b class=\"ar\">ظَهَّرَ</b> see 1, near the middle: -b2- and again, in the last quarter: -b3- and see also 3. -b4- <span class=\"ar\">ظهّر الثَّوْبَ</span> [and <span class=\"ar\"> <span class=\"ar\">اظهرهُ</span></span>, <i>contr. of</i> <span class=\"ar\">بطّنهُ</span> and <span class=\"ar\">ابطنهُ</span>,] <i>He faced the garment,</i> or <i>piece of cloth; put a facing,</i> or <i>an outer covering,</i> (<span class=\"ar\">ظِهَارَة</span>,) <i>to it.</i> (TA.) -A2- See also 4, last sentence.</p><p><b>3.</b> <b class=\"ar\">ظاهرهُ</b> , (A,) inf. n. <span class=\"ar\">مُظَاهَرَةٌ</span>, (S, O, Msb,) <i>He aided,</i> or <i>assisted, him;</i> (S, A, O, Msb;) as also <span class=\"ar\"> <span class=\"ar\">ظَهَرَ</span>عَلَيْهِ</span>. (Th, K.) And <span class=\"ar\">ظاهر عَلَيْهِ</span> <i>He aided,</i> or <i>assisted, against him.</i> (TA.) -b2- <span class=\"ar\">ظاهر بِهِ</span>: see 10. -b3- <span class=\"ar\">ظاهر بَيْنَهُمَا</span>, (K,) i. e. (TA) <span class=\"ar\">بَيْنَ ثَوْبَيْنِ</span>, (S, A, Mgh, TA,) and <span class=\"ar\">دِرْعَيْنِ</span>, (A, Mgh, TA,) and <span class=\"ar\">نَعْلَيْنِ</span>, (TA,) <i>i. q.</i> <span class=\"ar\">طَارَقَ بَيْنَهُمَا</span>, (S, TA,) or <span class=\"ar\">طَابَقَ</span>, (A, K, TA,) i. e. (TA) <i>He put them on,</i> or <i>attired himself with them,</i> [namely, <i>two garments,</i> and <i>two coats of mail,</i> and <i>two sandals</i> or <i>soles,</i> or rather, when relating to two soles, <i>he sewed them together,</i>] <i>one over,</i> or <i>outside, the other:</i> (Mgh, TA:) app. from <span class=\"ar\">تَظَاهُرٌ</span> in the sense of “ mutual aiding or assisting. ” (IAth.) The phrase <span class=\"ar\">ظاهر بِدِرْعَيْنِ</span> requires consideration; and the <span class=\"ar\">ب</span> in it should be regarded as meant to denote conjunction; not as a part of the necessary complement of the verb. (Mgh.) <span class=\"ar\">ظاهر الدِّرْعَ</span> is said to signify <span class=\"ar\">لَأَمَ بَعْضَهَا عَلَى بَعْضٍ</span> [app. meaning <i>He folded over and fastened one part of the coat of mail upon another</i>]. (TA.) And <span class=\"ar\">ظاهر عَلَيْهِ</span> <span class=\"ar\">جِلَالًا</span> means <i>He threw upon him</i> (i. e. a horse) <i>housings</i> or <i>coverings</i> [<i>one over another</i>]. (TA in art. <span class=\"ar\">حنذ</span>.) -A2- <span class=\"ar\">ظاهر مِنِ ٱمْرَأَتِهِ</span>, (S, Mgh, O, Msb, K,) inf. n. <span class=\"ar\">ظِهَارٌ</span> (S, Mgh, Msb, K) and <span class=\"ar\">مُظَاهَرَةٌ</span>; (JK, TA;) and <span class=\"ar\"> <span class=\"ar\">تظاهر</span>مِنْهَا</span>, (A, Mgh, O, TA,) and <span class=\"ar\"> <span class=\"ar\">اِظَّاهَرَ</span></span>; (Mgh;) and <span class=\"ar\"> <span class=\"ar\">تظهّر</span>منها</span>, (S, Msb, K,) and <span class=\"ar\"> <span class=\"ar\">اِظَّهَّرَ</span></span>; (O, TA;) and <span class=\"ar\"> <span class=\"ar\">ظهّر</span>منها</span>, (S, O, K,) inf. n. <span class=\"ar\">تَظْهِيرٌ</span>; (S;) signify the same; (O;) <i>He said to his wife</i> <span class=\"ar\">أَنْتِ عَلَىَّ كَظَهْرِ أُمِّى</span> [<i>Thou art to me like the back of my mother</i>]; (S, Mgh, Msb, K;) [as though he said <span class=\"ar\">رُكُوبُكِ</span> <span class=\"ar\">حَرَامٌ عَلَىَّ</span>;] meaning <span class=\"ar\">رُكُوبُكِ لِلنِّكَاحِ حَرَامٌ عَلَىَّ</span> <span class=\"ar\">كَرُكُوبِ أُمِّى لِلنِّكَاحِ</span>; the back being specified in preference to the <span class=\"ar\">بَطْن</span> or <span class=\"ar\">فَخِذ</span> or <span class=\"ar\">فَرْج</span> because the woman is likened to a beast that is ridden, and the act of <span class=\"ar\">نِكَاح</span> to that of <span class=\"ar\">رُكُوب</span>: the phrase being a form of divorce used by the Arabs in the Time of Ignorance. (Msb, * TA.) In the Kur lviii. 2 [and 4], some read <span class=\"ar\"> <span class=\"ar\">يَظَّهَّرُونَ</span></span>; some <span class=\"ar\"> <span class=\"ar\">يَظَّاهَرُونَ</span></span>; and 'Ásim read <span class=\"ar\">يُظَاهِرُونَ</span>. (Bd.) The verb is made trans. by means of <span class=\"ar\">مِن</span> because the man who uttered this sentence estranged himself from his wife. (IAth.)</p><p><b>4.</b> <b class=\"ar\">اظهرهُ</b> <i>He made it apparent, overt, open, perceptible</i> or <i>perceived, manifest, plain,</i> or <i>evident; he showed, exhibited, manifested, displayed, discovered, revealed,</i> or <i>evinced, it;</i> or <i>put it forth:</i> (S, O, K:) [it is also used in relation to a saying, and an action, and the like, as meaning <i>it showed,</i> &amp;c., as above, or <i>it bespoke, it:</i>] and Mtr relates his having heard from one worthy of reliance of the people of Baghdád, that they say <span class=\"ar\"> <span class=\"ar\">تظاهرتُ</span> بِهِ</span> in the place of <span class=\"ar\">أَظْهَرْتُهُ</span>, and scarcely ever employ <span class=\"ar\">اظهر</span> in its usual sense. (Har p. 85.) [Hence, <span class=\"ar\">اظهر التَّضْعِيفَ</span> <i>He made the doubling of a letter distinct;</i> as in <span class=\"ar\">لَحِحَتْ</span>; which, accord. to a general rule, should be <span class=\"ar\">لَحَّتْ</span>: opposed to <span class=\"ar\">أَدْغَمَ</span>. And <span class=\"ar\">اظهر لَهُ كَذَا</span> <i>He showed,</i> &amp;c., <i>to him such a thing:</i> and <i>he made a show of, professed, pretended,</i> or <i>feigned, to him such a thing:</i> as, for instance, love.] -b2- <span class=\"ar\">أَظْهَرْتُ بِفُلَانٍ</span> means <span class=\"ar\">أَعْلَيْتُ بِهِ</span> [a phrase which I have not found except in this instance, app. <i>I elevated,</i> or <i>exalted, such a one:</i> like <span class=\"ar\">أَعْلَيْتُهُ</span>, which has this meaning]: (S, IKtt, L, TA:) or <span class=\"ar\">أَعْلَنْتُ بِهِ</span> [app. meaning <i>I made such a one to be,</i> or <i>become, publicly known</i>]: (So in the O:) [but the former explanation seems to be regarded by SM as the right; for he remarks that,] accord. to all the copies of the K, the explanation is <span class=\"ar\">أَعْلَنَ بِهِ</span>, and refers to <span class=\"ar\">ظَهَرَ بِفُلَانٍ</span> [instead of <span class=\"ar\">أَظْهَرَ</span>]; so that what its author says in this case differs in two points of view from what is found in the “ Kitáb el-Abniyeh ” of IKtt, in which the <span class=\"ar\">ى</span> in <span class=\"ar\">أَعْلَيْتُ</span> has been marked as correct, and in the L [as well as in the S]. (TA.) -A2- <span class=\"ar\">اظهرهُ ٱللّٰهُ عَلَى عَدُوِّهِ</span> means <i>God made him to overcome, conquer, subdue, overpower, master, gain the victory over,</i> or <i>prevail over, his enemy.</i> (S, A, O, TA.) -b2- And [hence] <span class=\"ar\">اظهرهُ</span> <span class=\"ar\">عَلَيْهِ</span> <i>He</i> (God) <i>made him to know it,</i> or <i>become acquainted with it:</i> you say, <span class=\"ar\">أَظْهَرَنِى ٱللّٰهُ عَلَى مَا</span> <span class=\"ar\">سُرِقَ مِنِّى</span> <i>God made me to know</i> [or <i>discover</i>] <i>what had been stolen from me.</i> (TA.) -A3- See also 1, last quarter, in two places. -A4- And see 2. -A5- <span class=\"ar\">اظهر</span> signifies also <i>He entered upon the time called the</i> <span class=\"ar\">ظَهِيرَة</span>: (A, Msb, K:) or <i>the time called the</i> <span class=\"ar\">ظُهْر</span>. (Msb.) And <i>He went,</i> or <i>journeyed, in the time called the</i> <span class=\"ar\">ظَهِيرَة</span>; as also <span class=\"ar\"> <span class=\"ar\">ظهّر</span></span>, (K,) inf. n. <span class=\"ar\">تَظْهِيرٌ</span>: (TA:) or <i>the time called the</i> <span class=\"ar\">ظُهْر</span>. (S, O.)</p><p><b>5.</b> <b class=\"ar\">تظهّر</b> and <b class=\"ar\">اِظَّهَّرَ</b> : see 3, latter half, in three places.</p><p><b>6.</b> <b class=\"ar\">تَظَاْهَرَ</b> see 1, first sentence: -b2- and see also 4, first sentence. -b3- <span class=\"ar\">تظاهروا</span> <i>They aided,</i> or <i>assisted, one another.</i> (S, O, * K.) And <span class=\"ar\">تظاهروا عَلَى فُلَانٍ</span> <i>They leagued together, and aided one another, against such a one.</i> (Ibn-Buzurj, TA in art. <span class=\"ar\">ضفر</span>.) -b4- Also <i>They regarded,</i> or <i>treated, one another with enmity,</i> or <i>hostility;</i> or <i>severed themselves, one from another:</i> (S, Msb, K:) as though they turned their backs, one upon another: (S:) or, because they who do so turn their backs, one upon another. (Msb.) Thus the verb has two contr. meanings. (K.) -b5- <span class=\"ar\">تظاهر مِنِ ٱمْرَأَتِهِ</span> and <span class=\"ar\">اِظَّاهَرَ</span>: see 3, latter half, in three places.</p><p><b>8.</b> <b class=\"ar\">اِظَّهَرَ</b> : see 1, last quarter.</p><p><b>10.</b> <b class=\"ar\">استظهر بِهِ</b> <i>He sought aid,</i> or <i>assistance, in,</i> or <i>by means of, him,</i> or <i>it,</i> (S, O, Msb, K, TA,) <span class=\"ar\">عَلَيْهِ</span> [<i>against him,</i> or <i>it</i>]; as also <span class=\"ar\">استظهرهُ</span>. (TA.) [In the CK, after the explanation of <span class=\"ar\">استظهر به</span>, is an omission, to be supplied by the insertion of <span class=\"ar\">وَقَرَأَهُ</span>.] One says, <span class=\"ar\">استظهر بِٱلْغِنَى عَلَى النَّوَائِبِ</span> [<i>He sought aid in wealth against calamities,</i> or <i>afflictions</i>]. (Msb.) And <span class=\"ar\"> <span class=\"ar\">ظاهر</span>بِهِ</span> signifies the same as <span class=\"ar\">استظهر</span> [in this sense or in another of the senses expl. in what follows]. (TA.) -b2- And <span class=\"ar\">استظهرتُ بِالشَّىْءِ</span>, and <span class=\"ar\"> <span class=\"ar\">ظَهَرْتُ</span>بِهِ</span>, and <span class=\"ar\"> <span class=\"ar\">ظَهَرْتُهُ</span></span>, <i>I put the thing behind my back for protection,</i> or <i>security.</i> (Har p. 265.) -b3- And <span class=\"ar\">استظهر</span> <i>He prepared for himself a camel,</i> or <i>two camels,</i> or <i>more, for future need:</i> (T:) and <span class=\"ar\">استظهرهُ</span>, and <span class=\"ar\"> <span class=\"ar\">ظَهَرَ</span>بِهِ</span>, <i>He prepared him,</i> namely, a camel, <i>for future need:</i> (K:) and <span class=\"ar\">استظهر بِبَعِيرَيْنِ</span> <span class=\"ar\">ظِهْرِيَّيْنِ</span> <i>He prepared for himself two camels for future need.</i> (T. [See <span class=\"ar\">ظِهْرِىٌّ</span>.]) -b4- Hence, (T,) <span class=\"ar\">استظهر</span> signifies also <i>He used precaution</i> (T, Msb) with respect to anything: (T:) <i>he secured himself,</i> (<span class=\"ar\">اِسْتَوْثَقَ</span>,) <i>by using precaution;</i> as, for instance, a woman does by remaining three days, before she performs the ablution termed <span class=\"ar\">غُسْل</span>, and prays, after the usual period of the menses. (T, L.) One says, <span class=\"ar\">يُسْتَحَبُّ الاِسْتِظْهَارُ بِغَسْلَةٍ ثَانِيَةٍ</span> <span class=\"ar\">وَثَالِثَةٍ</span> <i>The using precaution by a second and a third washing,</i> to make sure of being pure, <i>is approved.</i> (Er-Ráfi'ee, Msb.) And <span class=\"ar\">استظهرتُ</span> <span class=\"ar\">فِى طَلَبِ الشَّىْءِ</span> <i>I adopted the most fit,</i> or <i>proper, way, and used precaution, in seeking to attain the thing.</i> (Msb.) -b5- See also 1, in the middle of the latter half.</p><p><b class=\"ar\">ظَهْرٌ</b> The <i>back; contr. of</i> <span class=\"ar\">بَطْنٌ</span>: (S, A, O, Msb, K:) in a man, <i>from the hinder part of the</i> <span class=\"ar\">كَاهِل</span> [or <i>base of the neck</i>] <i>to the nearest part of the buttocks, where it terminates:</i> (TA:) in a camel, the <i>part containing six vertebræ on the right and left of which are</i> [<i>two portions of flesh and sinew called the</i>] <span class=\"ar\">مَتْنَانِ</span>: (AHeyth, T, O:) of the masc. gender: (Lh, A, K:) pl. [of pauc.] <span class=\"ar\">أَظْهُرٌ</span>, and [of mult.] <span class=\"ar\">ظُهُورٌ</span> and <span class=\"ar\">ظُهْرَانٌ</span>. (Msb, K.) -b2- <span class=\"ar\">رَجُلٌ</span> <span class=\"ar\">خَفِيفُ الظَّهْرِ</span> (tropical:) <i>A man having a small household to maintain:</i> and <span class=\"ar\">ثَقِيلُ الظَّهْرِ</span> (tropical:) <i>having a large household to maintain.</i> (K, * TA.) -b3- <span class=\"ar\">أَنْت عَلَىَّ كَظَهْرِ</span> <span class=\"ar\">أُمِّى</span> <i>Thou art to me like the back of my mother:</i> said by a man to his wife. (S, Mgh, Msb, K.) [This has been expl. above: see 3.] -b4- <span class=\"ar\">عَدَا فِى</span> <span class=\"ar\">ظَهْرِهِ</span> (tropical:) <i>He stole what was behind him:</i> (A:) [or <i>he acted wrongfully in respect of what was behind him:</i> for] <span class=\"ar\">لِصٌّ عَادِى ظَهْرٍ</span> is expl. by the words <span class=\"ar\">عَدَا فِى ظَهْرٍ فَسَرَقَهُ</span> [so that it app. means (tropical:) <i>A thief who has acted wrongfully in respect of what was behind one, and stolen it</i>]. (O, K.) -b5- <span class=\"ar\">أَقْرَانُ الظَّهْرِ</span> (S, O, K) and <span class=\"ar\">الظُّهُورِ</span> (O, TA) <i>Adversaries who come to one from behind his back, in war,</i> or <i>fight.</i> (S, O, K, * TA.) In the copies of the K, <span class=\"ar\">يُحِبُّونَكَ</span> is erroneously put for <span class=\"ar\">يَجِيؤُونَكَ</span>. (TA.) You say also, <span class=\"ar\">فُلَانٌ قِرْنُ الظَّهْرِ</span> <i>Such a one is an adversary who comes to one from behind, unknown.</i> (IAar, As.) -b6- <span class=\"ar\">قَتَلَهُ ظَهْرًا</span> <i>He slew him unexpectedly; he assassinated him;</i> syn. <span class=\"ar\">غِيلَةٌ</span>. (IAar, TA.) -b7- <span class=\"ar\">جَعَلَنِى بِظَهْرٍ</span> (tropical:) <i>He cast me off.</i> (TA.) And <span class=\"ar\">جَعَلتُ حَاجَتَهُ بِظَهْرٍ</span> (tropical:) <i>I cast his want behind my back:</i> (AO, K:) and <span class=\"ar\">جَعَلَهَا <span class=\"ar\">ظِهْرِيَّةً</span></span> signifies the same: (S:) and <span class=\"ar\">اِتَّخَذَهَا <span class=\"ar\">ظِهْرِيًّا</span></span>, (K,) and <span class=\"ar\"> <span class=\"ar\">ظِهْرِيَّةً</span></span>: (TA:) or the former of the last two phrases signifies <i>he held it in contempt;</i> as though <span class=\"ar\">ظهريّا</span> were an irreg. rel. n. from <span class=\"ar\">ظَهْرٌ</span>: (TA:) or <span class=\"ar\">اِتَّخَذَهُ <span class=\"ar\">ظِهْرِيًّا</span></span> signifies <i>he neglected,</i> or <i>forgot,</i> (S, O, * Msb,) <i>him,</i> as in the Kur xi. 94, (S, O,) or <i>it,</i> namely, what was said. (Msb.) And <span class=\"ar\">لَا تَجْعَلْ حَاجَتِى</span> <span class=\"ar\">بِظَهْرٍ</span> (tropical:) <i>Forget not thou,</i> or <i>neglect not, my want:</i> (S:) and <span class=\"ar\">جَعَلَهُ <span class=\"ar\">ظِهْرِيًّا</span></span> signifies <i>he forgot it;</i> as well as <span class=\"ar\">جعله بِظَهْرٍ</span>. (A.) And <span class=\"ar\">جَعَلْتُ هٰذَا الأَمْرَ</span> <span class=\"ar\">بِظَهْرٍ</span>, and <span class=\"ar\">رَمَيْتُهُ بِظَهْرٍ</span>, (tropical:) <i>I cared not for this thing.</i> (Th, O.) -b8- <span class=\"ar\">فُلَانٌ مِنْ وَلَدِ الظَّهْرِ</span> (assumed tropical:) <i>Such a one is of those who do not belong to us:</i> or <i>of those to whom no regard is paid:</i> (TA:) or <i>of those who are held in contempt, and to whose ties of relationship no regard is paid.</i> (S, TA.) -b9- <span class=\"ar\">هُوَ ٱبْنُ عَمِّهِ ظَهْرًا</span> (tropical:) [<i>He is his cousin on the father's side,</i>] <i>distantly related: contr. of</i> <span class=\"ar\">دِنْيًا</span> [<i>and</i> <span class=\"ar\">لَحًّا</span>]. (As, A, O, TA.) -b10- <span class=\"ar\">رَجَعَ عَلَى ظَهْرِهِ</span> [<i>He receded, retired,</i> or <i>retreated</i>]. (K in art. <span class=\"ar\">ثبجر</span>.) -b11- <span class=\"ar\">هُوَ نَازِلٌ بَيْنَ ظَهْرَيْهِمْ</span>, and <span class=\"ar\">بين <span class=\"ar\">ظَهْرَانَيْهِمْ</span></span>, (S, A, O, Msb, K, *) in which latter the <span class=\"ar\">ا</span> and <span class=\"ar\">ن</span> are said by some to be added for corroboration, (Msb,) and for which one should not say <span class=\"ar\">ظَهْرَانِيهِمْ</span>, (IF, S, O, Msb, K,) and <span class=\"ar\">بين أَظْهُرِهِمْ</span>, (Msb, K,) (tropical:) <i>He is making his abode in the midst of them; in the main body of them:</i> (K, TA:) originally meaning he is making his abode among them for the purpose of seeking aid of them and staying himself upon them: as though it meant that the back of one of them was before him, and that of another behind him, so that he was defended in either direction: afterwards, by reason of frequency of usage, it came to be employed to signify abiding among a people absolutely. (IAth, Msb.) You say also <span class=\"ar\">هُوَ بَيْنَ</span> <span class=\"ar\">ظَهْرَيْهِ</span>, and <span class=\"ar\">بَيْنَ <span class=\"ar\">ظَهْرَانَيْهِ</span></span>, meaning <i>It</i> (anything) <i>is in the midst,</i> or <i>main part, of it,</i> namely, another thing. (TA.) -b12- <span class=\"ar\">لَقِيتُهُ بَيْنَ الظَّهْرَيْنِ</span>, and <span class=\"ar\">بَيْنَ <span class=\"ar\">الظَّهْرَانَيْنِ</span></span>, (S, O, Msb, K,) (tropical:) <i>I met him during the day,</i> (Msb,) or <i>during the two days,</i> (S, O, K,) or <i>during the three days,</i> (K,) or <i>the days:</i> (S, O, Msb:) from the next preceding phrase. (TA.) And <span class=\"ar\">أَتَيْتُهُ مَرَّةً بَيْنَ الظَّهَرْينِ</span> (tropical:) <i>I came to him one day:</i> or, accord. to Aboo-Fak'as, <i>on a day between two years.</i> (Fr.) And <span class=\"ar\">رَأَيْتُهُ بَيْنَ <span class=\"ar\">ظَهْرَانَىِ</span>اللَّيْلِ</span> (tropical:) <i>I saw him between nightfall and daybreak.</i> (TA.) And <span class=\"ar\">جِئْتُهُ بَيْنَ <span class=\"ar\">ظَهْرَانَىِ</span>النَّهَارِ</span> (tropical:) [<i>I came to him between the beginning and end of the day</i>]. (A.) -b13- <span class=\"ar\">تَقَلَّبَ ظَهْرًا لِبَطْنٍ</span> (assumed tropical:) <i>It turned over and over,</i> or <i>upside down,</i> (lit. <i>back for belly,</i>) as a serpent does upon ground heated by the sun. (S and TA in art. <span class=\"ar\">قلب</span>.) [Hence,] <span class=\"ar\">قَلَبْتُ الأَرْضَ ظَهْرًا لِبَطْنٍ</span> (tropical:) [<i>I turned the earth over, upside-down</i>]. (A.) And [hence,] <span class=\"ar\">قَلَّبَ أَمْرَهُ ظَهْرًا لِبَطْنٍ</span>, (O, * TA,) and <span class=\"ar\">ظَهْرَهُ لِبَطْنٍ</span>, and <span class=\"ar\">ظَهْرَهُ لِبَطْنِهِ</span>, and <span class=\"ar\">ظَهْرَهُ لِلْبَطْنِ</span>, which last form is preferred by El-Farezdak to the second, because [as in the third form] the second of the two words is determinate like the first word, (tropical:) <i>He meditated,</i> or <i>managed, the affair with forecast, and well.</i> (O, * TA.) -b14- The Arabs used to say, <span class=\"ar\">هٰذَا ظَهْرُ السَّمَآءِ</span> and <span class=\"ar\">هذا بَطْنُ</span> <span class=\"ar\">السَّمَآءِ</span>, both meaning (tropical:) <i>This is the apparent, visible, part of the sky.</i> (Fr, Az.) And the like is said of the side of a wall, which is its <span class=\"ar\">بَطْن</span> to a person on the same side, and its <span class=\"ar\">ظَهْر</span> to one on the other side. (Az.) -b15- <span class=\"ar\">مَا نَزَلَ مِنَ القُرْآنِ آيَةٌ إِلَّا</span> <span class=\"ar\">لَهَا ظَهْرٌ وَبَطْنٌ</span>, [part of] a saying of Mohammad, [of which see the rest voce <span class=\"ar\">مُطَّلَعٌ</span>,] means (assumed tropical:) <i>Not a verse of the Kur-án has come down but it has a verbal expression and an interpretation:</i> (K, * TA:) or <i>a verbal expression and a meaning:</i> or <i>that which has an apparent and a known</i> [or <i>an exoteric</i>] <i>interpretation and that which has an intrinsic</i> [or <i>esoteric</i>] <i>interpretation:</i> (TA:) or <i>narration</i> (K, TA) <i>and admonition:</i> (TA:) or [<i>it is to be read and to be understood and taught;</i> for] by the <span class=\"ar\">ظهر</span> is meant the reading; and by the <span class=\"ar\">بطن</span>, the understanding and teaching. (TA.) [See also <span class=\"ar\">بَطْنٌ</span>.] -b16- <span class=\"ar\">ظَهْرٌ</span> signifies also (tropical:) <i>Camels on which people ride, and which carry goods;</i> (S, * A, * O, K, * TA;) <i>camels that carry burdens upon their backs in journeying:</i> (TA:) [or] <i>a beast:</i> or <i>a camel for riding:</i> (Mgh:) pl. <span class=\"ar\">ظُهْرَانٌ</span>. (TA.) It is said in a trad. of 'Arfajeh, <span class=\"ar\">فَتَنَاوَلَ</span> <span class=\"ar\">السَّيْفَ مِنَ الظَّهْرِ</span> <i>And he reached,</i> or <i>took in his hand, the sword from the camels for carrying burdens and for riding:</i> and in another, <span class=\"ar\">أَتَأْذَنُ</span> <span class=\"ar\">لَنَا فِى نَحْرِ ظَهْرِنَا</span> <i>Dost thou permit us to slaughter our camels which we ride?</i> (TA.) And one says also, <span class=\"ar\">هُوَ عَلَى ظَهْرٍ</span> (tropical:) <i>He is determined upon travel:</i> (K:) as though he had already mounted a beast for that purpose. (TA.) -b17- [Hence, app.,] (assumed tropical:) <i>Property consisting of camels and sheep</i> or <i>goats:</i> (TA:) or <i>much property.</i> (K, TA.) -b18- (assumed tropical:) The <i>short side</i> [or <i>lateral half</i>] <i>of a feather:</i> (S, O, K:) pl. <span class=\"ar\">ظُهْرَانٌ</span>: (S, M, K, TA, &amp;c.:) opposed to <span class=\"ar\">بَطْنٌ</span>, sing. of <span class=\"ar\">بُطْنَانٌ</span>, (TA,) which latter signifies the “ long sides: ” (S, TA:) and <span class=\"ar\"> <span class=\"ar\">ظُهَارٌ</span></span> signifies the same as <span class=\"ar\">ظَهْرٌ</span>, (K,) or the same as <span class=\"ar\">ظُهْرَانٌ</span>, being an irregular pl.; and this is meant by the saying <span class=\"ar\">الظُّهَارُ بِالضَّمِ الجَمَاعَةُ</span>, mentioned in a later place in the K [in such a manner as to have led to the supposition that <span class=\"ar\">ظُهَارٌ</span> is also syn. with <span class=\"ar\">جَمَاعَةٌ</span>]: (TA:) AO says that among the feathers of arrows are the <span class=\"ar\">ظُهَار</span>, which are <i>those that are put</i> [<i>upon an arrow</i>] <i>of the</i> <span class=\"ar\">ظَهْر</span> [or <i>outer side</i>] <i>of the</i> <span class=\"ar\">عَسِيب</span> [app. here meaning the <i>shaft</i>] <i>of the feather;</i> (S, TA;) i. e., the <i>shorter side,</i> which is the best kind of feather; as also <span class=\"ar\">ظُهْرَان</span>: sing. <span class=\"ar\">ظَهْرٌ</span>: (TA:) ISd says that the <span class=\"ar\">ظُهْرَان</span> are <i>those parts of the feathers of the wing that are exposed to the sun and rain:</i> (TA:) Lth says that the <span class=\"ar\">ظُهَار</span> are <i>those parts of the feathers of the wing that are apparent.</i> (O, TA.) One says, <span class=\"ar\">رِشْ سَهْمَكَ بِظُهْرَانٍ وَلَا تَرِشْهُ بِبُطْنَانٍ</span> [<i>Feather thine arrow with short sides of feathers, and feather it not with long sides of feathers</i>]. (S, TA.) [De Sacy supposes that <span class=\"ar\">ظُهُورٌ</span> and <span class=\"ar\">بُطُونٌ</span> are also pls. of <span class=\"ar\">ظَهْرٌ</span> and <span class=\"ar\">بَطْنٌ</span> thus used: (see his “ Chrest. Arabe, ” sec. ed., tome ii., p. 374:) but his reasons do not appear to me to be conclusive.] <span class=\"ar\"> <span class=\"ar\">ظُهَارٌ</span></span> and <span class=\"ar\">ظُهْرَانٌ</span> are also used as epithets: you say, <span class=\"ar\">رِيشٌ ظُهَارٌ</span> and <span class=\"ar\">رِيشٌ ظُهْرَانٌ</span>. (TA.) -b19- [<span class=\"ar\">ظَهْرُ الكَفِّ</span> and <span class=\"ar\"> <span class=\"ar\">ظَاهِرُهَا</span></span> mean (assumed tropical:) <i>The back of the hand.</i> And in like manner, <span class=\"ar\">ظَهْرُ القَدَمِ</span> and <span class=\"ar\"> <span class=\"ar\">ظَاهِرُهَا</span></span> mean (assumed tropical:) <i>The upper,</i> or <i>convex, side,</i> or <i>back, of the human foot, corresponding to the back of the hand, including the instep:</i> opposed to <span class=\"ar\">بَطْن</span> and <span class=\"ar\">بَاطِن</span>. And <span class=\"ar\">ظَهْرُ اللِّسَانِ</span> means (assumed tropical:) <i>The upper surface of the tongue.</i>] -b20- And <span class=\"ar\">ظَهْرٌ</span> also signifies (tropical:) <i>A way by land.</i> (S, M, O, Msb, K.) This expression is used when there is a way by land and a way by sea. (M.) You say, <span class=\"ar\">سَارُوا</span> <span class=\"ar\">فِى طَرِيقِ الظَّهْرِ</span> (tropical:) <i>They journeyed by land.</i> (A.) -b21- And (assumed tropical:) <i>An elevated tract</i> of land or ground; as also <span class=\"ar\"> <span class=\"ar\">ظَاهِرةٌ</span></span>: (A:) or <i>rugged and elevated land</i> or <i>ground;</i> (JK, K;) as also <span class=\"ar\"> <span class=\"ar\">ظَاهِرَةٌ</span></span>: (JK:) opposed to <span class=\"ar\">بَطْنٌ</span>, which signifies “ soft and plain and fine and low land or ground: ” (TA:) and <span class=\"ar\"> <span class=\"ar\">ظَوَاهِرُ</span></span> [pl. of. <span class=\"ar\">ظَاهِرَةٌ</span>] signifies (assumed tropical:) <i>elevated tracts</i> of land or ground: (S, K:) you say, <span class=\"ar\">هَاجَتْ ظَوَاهِرُ الأَرْضِ</span>, meaning, (assumed tropical:) <i>the herbs,</i> or <i>leguminous plants, of the elevated tracts of land,</i> or <i>ground, dried up:</i> (As, S, L:) and <span class=\"ar\"> <span class=\"ar\">ظَاهِرٌ</span></span> signifies (assumed tropical:) <i>the higher,</i> or <i>highest, part</i> of a mountain; (ISh, L, TA;) whether its exterior be plain or not: (TA:) and <span class=\"ar\"> <span class=\"ar\">ظَاهِرَةٌ</span></span>, the same, of anything: (L:) when you have ascended upon the <span class=\"ar\">ظَهْر</span> of a mountain, you are upon its <span class=\"ar\">ظَاهِرَة</span>. (TA.) -b22- <span class=\"ar\">سَالَ وَادِيهِمْ ظَهْرًا</span> means (assumed tropical:) <i>Their valley flowed with the rain of their own land:</i> opposed to <span class=\"ar\">دُرْءًا</span>, meaning, “ from other rain: ” (IAar, O, K: *) or the former signifies <i>their valley flowed</i> <i>with its own rain:</i> and the latter, “ with other than its own rain: ” (TA:) and some say <span class=\"ar\"> <span class=\"ar\">ظُهْرًا</span></span>, which Az thinks the better form. (O, TA.) -b23- [Hence, probably,] <span class=\"ar\">أَصَبْتُ مِنْهُ مَطَرَ ظَهْرٍ</span> (assumed tropical:) <i>I obtained from him,</i> or <i>it, much good.</i> (Sgh, O, K.) -b24- And another signification of <span class=\"ar\">ظَهْرٌ</span> is <i>What is absent,</i> or <i>hidden,</i> or <i>concealed, from one.</i> (O, K.) -b25- It is sometimes prefixed to another noun to give plainness and force to the expression; as in <span class=\"ar\">ظَهْرُ الغَيْبِ</span> and <span class=\"ar\">ظَهْرُ القَلْبِ</span>, meaning <span class=\"ar\">نَفْسُ الغَيْبِ</span> and <span class=\"ar\">نَفْسُ القَلْبِ</span>: (Msb:) or it is redundant in these instances. (Mgh.) Lebeed says, describing a [wild] cow going about after a beast of prey that had eaten her young one, <span class=\"ar\">وَتَسَمَّعَتْ رِزَّ الأَنِيسِ فَرَاعَهَا</span> <span class=\"ar\">عَنْ ظَهْرِ غَيْبٍ وَالأَنِيسُ سَقَامُهَا</span> [<i>And she heard the sound of man, and it frightened her, from a place that concealed what was in it; for man is her malady;</i> i. e., <i>a cause of pain and trouble and death to her</i>]: (TA:) meaning, she heard the sound of the hunters, &amp;c. (TA in art. <span class=\"ar\">غيب</span>.) And you say, <span class=\"ar\">تَنَاوَلَهُ بِظَهْرِ الغَيْبِ بِمَا</span> <span class=\"ar\">يَسُوؤُهُ</span> <i>He carped at him behind the back,</i> or <i>in absence, by saying what would grieve him.</i> (TA in art. <span class=\"ar\">غيب</span>.) And <span class=\"ar\">تَكَلَّمْتُ بِهِ عَنْ ظَهْرِ الغَيْبِ</span> (A, O) or <span class=\"ar\">عن ظَهْرِ غَيْبٍ</span> (TA) [app., (tropical:) <i>I spoke it by memory; in the absence of a book</i> or <i>the like;</i> as one says in modern Arabic, <span class=\"ar\">عَلَى الغَائِب</span>. See also <span class=\"ar\">غَيْبٌ</span>.] And <span class=\"ar\">قَرَأَهُ عَنْ ظَهْرِ القَلْبِ</span> (tropical:) <i>He recited it by heart,</i> or <i>memory; without book:</i> (L, K: [in the latter, <span class=\"ar\">مِنْ</span> is put in the place of <span class=\"ar\">عَنْ</span>; but the right reading is that in the L: and in the CK is an omission here, to be supplied by the insertion of <span class=\"ar\">وَقَرَأَهُ</span>:]) and <span class=\"ar\">قرأه <span class=\"ar\">ظَاهِرًا</span></span> and <span class=\"ar\">قرأه عَلَى</span> <span class=\"ar\">ظَهْرِ لِسَانِهِ</span> [signify the same]. (K.) And <span class=\"ar\">حَمَلَ</span> <span class=\"ar\">القُرْآنَ عَلَى ظَهْرِ لِسَانِهِ</span> like <span class=\"ar\">حَفِظَهُ عَلَى ظَهْرِ قَلْبِهِ</span> (tropical:) [<i>He knew the Kur-án by heart</i>]. (A, * O, TA.) -b26- One says also, <span class=\"ar\">فُلَانٌ يَأْكُلُ عَلَى ظَهْرِ يَدِ فُلَانٍ</span> (tropical:) <i>Such a one eats at the expense of such a one.</i> (A, O, K. *) And in like manner, <span class=\"ar\">الفُقَرَآءُ يَأْكُلُونَ</span> <span class=\"ar\">عَلَى ظَهْرِ أَيْدِى النَّاسِ</span> (tropical:) <i>The poor eat at the expense of the people.</i> (A, TA.) And <span class=\"ar\">أَعْطَاهُ عَنْ</span> <span class=\"ar\">ظَهْرِ يَدٍ</span> (tropical:) <i>He gave him originally; without compensation.</i> (O, * K; but in some copies of the K we find <span class=\"ar\">مِنْ</span> in the place of <span class=\"ar\">عَنْ</span>.) It is said [in a trad.], <span class=\"ar\">أَفْضَلُ الصَّدَقَةِ مَا كَانَ عَنْ ظَهْرِ غِنًى</span> (tropical:) <i>The most excellent of alms is that which is</i> [<i>derived</i>] <i>from competence;</i> <span class=\"ar\">ظهر</span>: (Msb:) or simply <span class=\"ar\">عَنْ غِنًى</span>, the word <span class=\"ar\">ظهر</span> being here redundant: (Mgh:) or <i>from manifest competence upon which one relies, and in which he seeks aid against calamities,</i> or <i>afflictions:</i> or <i>from what remains after fight:</i> (Msb:) or <i>from superfluous property.</i> (TA.) -A2- See also <span class=\"ar\">ظَهِيرٌ</span> -A3- <span class=\"ar\">قِدْرُ ظَهْرٍ</span> means (assumed tropical:) <i>An old cooking-pot:</i> (O, K: *) pl. <span class=\"ar\">قُدُورُ ظُهُورٍ</span>: (O:) as though, because of its oldness, it were thrown behind the back. (TA.)</p><p><b class=\"ar\">ظُهْرٌ</b> <i>Midday,</i> or <i>noon:</i> (IAth, TA:) or the <i>time when the sun declines from the meridian:</i> (Msb, * K, * O, * TA:) or [the <i>time immediately</i>] <i>after the declining of the sun:</i> (S, Mgh:) masc. and fem.; unless when the word <span class=\"ar\">صَلَاة</span> is prefixed to it, in which case it is fem. only: (Msb:) [pl. <span class=\"ar\">أَظْهَارٌ</span>. See also <span class=\"ar\">ظَهِيرَةٌ</span>.] <span class=\"ar\">صَلَاةُ الظُّهْرِ</span> means <i>The prayer</i> [i. e. <i>the divinely-ordained prayer</i>] <i>of midday,</i> or <i>noon:</i> (IAth, TA:) or <i>of the time after the declining of the sun.</i> (S, O.) In the phrases <span class=\"ar\">أَبْرِدُوا بِالظُّهْرِ</span> [<i>Defer ye the prayer of midday until the cooler time of day</i>] and <span class=\"ar\">صَلَّى الظُّهْرَ</span> [<i>He performed the prayer of midday</i>], the prefixed noun (<span class=\"ar\">صَلَاة</span>) is suppressed. (Mgh.) -A2- <span class=\"ar\">سَالَ</span> <span class=\"ar\">وَادِيهِمْ ظُهْرًا</span>: see <span class=\"ar\">ظَهْرٌ</span>, last quarter.</p><p><b class=\"ar\">ظَهِرٌ</b> , (S,) or <span class=\"ar\"> <span class=\"ar\">ظَهِيرٌ</span></span>, (K,) [the former agreeable with analogy, being derived from <span class=\"ar\">ظَهِرَ</span>,] A man (S,) <i>having a complaint of the back:</i> (S, K:) or <i>having a pain in the back:</i> as also <span class=\"ar\"> <span class=\"ar\">مَظْهُورٌ</span></span>. (O, TA.)</p><p><b class=\"ar\">ظُهْرَةٌ</b> : see <span class=\"ar\">ظَهِيرٌ</span>, in three places. -A2- Also The <i>tortoise.</i> (O, K.)</p><p><b class=\"ar\">ظِهْرَةٌ</b> : see <span class=\"ar\">ظَهِيرٌ</span>, in six places.</p><p><b class=\"ar\">ظَهَرَةٌ</b> The <i>goods,</i> or <i>furniture and utensils, of a house</i> or <i>tent;</i> (IAar, S, O, K, TA;) as also <span class=\"ar\">أَهَرَةٌ</span>: (IAar, TA:) or the former signifies the <i>exterior of a house,</i> or <i>tent;</i> and the latter, the “ interior thereof. ” (Th, TA.) -b2- And <i>Abundance</i> of <span class=\"ar\">مَال</span> [i. e. property, or cattle]. (TA.) -A2- See also <span class=\"ar\">ظَهِيرٌ</span>.</p><p><b class=\"ar\">ظِهْرِىٌّ</b> A camel <i>prepared for future need;</i> (T, S, O, K;) <i>taken, by way of precaution, to bear the burden of any camel that may happen to fail in a journey:</i> sometimes two or more unladen camels are taken for this purpose: some say that such a camel is thus called because its owner puts it behind his back, not riding it nor putting any burden upon it: (T, TA:) the word appears to be an irreg. rel. n. from <span class=\"ar\">ظَهْرٌ</span>: (ISd, TA:) pl. <span class=\"ar\">ظَهَارِىٌّ</span>, imperfectly decl., because the rel. <span class=\"ar\">ى</span> retains its place in the sing. [inseparably; there being no such word as <span class=\"ar\">ظِهْر</span>: but if it be a rel. n., this pl. is irreg., like <span class=\"ar\">مَهَارِىٌّ</span>]. (S, O, K.) -b2- See <span class=\"ar\">ظَهْرٌ</span>, first quarter, in five places, for examples of <span class=\"ar\">ظِهْرِىٌّ</span> and <span class=\"ar\">ظِهْرِيَّةٌ</span> used tropically.</p><p><b class=\"ar\">ظُهْرَان</b> [app. <span class=\"ar\">ظُهْرَانٌ</span> (which is also a pl. of <span class=\"ar\">ظَهْرٌ</span> used in several senses), or, perhaps <span class=\"ar\">ظُهْرَانِ</span>, as having a dual meaning,] The <i>upper, thick, pair of wings of the locust.</i> (AHn, TA.) -b2- [See also <span class=\"ar\">ظَهْرٌ</span>.]</p><p><b class=\"ar\">بَيْنَ ظَهْرَانَيْهِمْ</b> , and <span class=\"ar\">ظَهْرَانَيْهِ</span>, and <span class=\"ar\">الظَّهْرَانَيْنِ</span>, &amp;c.: see <span class=\"ar\">ظَهْرٌ</span>, former half, in five places.</p><p><b class=\"ar\">ظَهَارٌ</b> The <i>exterior</i> (K, TA) <i>and elevated</i> (TA) <i>part of a</i> [<i>stony tract such as is called</i>] <span class=\"ar\">حَرَّة</span>. (K, TA.)</p><p><b class=\"ar\">ظُهَارٌ</b> <i>Pain in the back.</i> (Az, O, TA.) -A2- See also <span class=\"ar\">ظَهْرٌ</span>, third quarter, in two places.</p><p><b class=\"ar\">ظَهِيرٌ</b> : see <span class=\"ar\">ظَاهِرٌ</span>. -A2- Also <i>An aider,</i> or <i>assistant;</i> (S, A, O, Msb, K;) and so <span class=\"ar\"> <span class=\"ar\">ظِهْرَةٌ</span></span> (S, K) and <span class=\"ar\"> <span class=\"ar\">ظُهْرَةٌ</span></span>: (K:) [in one place, in the K, <span class=\"ar\">ظِهْرَةٌ</span> is expl. by <span class=\"ar\">عَوْن</span>; but by this is meant, as will be seen below, the same as is meant by <span class=\"ar\">مُعِين</span>, by which all the three words are expl. in another place in the K, as well as in the S &amp;c.:] and <i>aiders,</i> or <i>assistants;</i> (S, Msb;) as also <span class=\"ar\"> <span class=\"ar\">ظِهْرَةٌ</span></span> and <span class=\"ar\"> <span class=\"ar\">ظُهْرَةٌ</span></span> and <span class=\"ar\"> <span class=\"ar\">ظَهْرٌ</span></span>: (TA:) the pl. of <span class=\"ar\">ظَهِيرٌ</span> is <span class=\"ar\">ظُهَرَآءُ</span>. (O.) It is said in the Kur [xxv. 57], <span class=\"ar\">وَكَانَ الكَافِرُ عَلَى رَبِّهِ ظَهِيرًا</span> <i>And the unbeliever is an aider</i> of the enemies of God [<i>against his Lord</i>]. (Ibn-'Arafeh.) You say also, <span class=\"ar\">فُلَانٌ <span class=\"ar\">ظِهْرَتِى</span> عَلَى فُلَانٍ</span> <i>Such a one is my aider</i> (<span class=\"ar\">عَوْن</span>) <i>against such a one:</i> and <span class=\"ar\">أَنَا <span class=\"ar\">ظِهْرَتُكَ</span>عَلَى هٰذَا الأَمْرِ</span> <i>I am thine aider against this thing,</i> or <i>affair.</i> (S, O.) And it is also said in the Kur [lxvi. 4], <span class=\"ar\">وَٱلْمَلَائِكَةُ بَعْدَ ذٰلِكَ ظَهِيرٌ</span> [<i>And the angels after that</i> will be his <i>aiders</i>]: and instance of <span class=\"ar\">ظهير</span> in a pl. sense: (S, O, Msb:) for words of the measures <span class=\"ar\">فَعُولٌ</span> and <span class=\"ar\">فَعِيلٌ</span> are sometimes masc. and fem. [and sing.] and pl. (S.) You also say, <span class=\"ar\">جَآءَ فُلَانٌ فِى <span class=\"ar\">ظِهْرَتِهِ</span></span>, (S, A, K,) and <span class=\"ar\"> <span class=\"ar\">ظُهْرَتِهِ</span></span>, (A, K,) and <span class=\"ar\"> <span class=\"ar\">ظَهَرَتِهِ</span></span>, and <span class=\"ar\"> <span class=\"ar\">ظَاهِرَتِهِ</span></span>, (K,) <i>Such a one came among his people,</i> (S,) or <i>kinsfolk,</i> (K,) <i>and those who performed his affairs for him,</i> (S, A,) i. e., <i>his aiders,</i> or <i>assistants.</i> (A.) And <span class=\"ar\">هُمْ فِى <span class=\"ar\">ظِهْرَةٍ</span>وَاحِدَةٍ</span> <i>They aid one another against the enemies.</i> (TA.) -b2- Also <i>Strong in the back;</i> (K;) <i>sound therein:</i> (Lth:) and so <span class=\"ar\"> <span class=\"ar\">مُظَهَّرٌ</span></span>: (S, O, K:) applied to a man: (S:) or <i>hard and strong;</i> whether in the back or any other part is not said: (TA:) in this sense, (TA,) or as signifying <i>strong,</i> (S, O,) applied to a camel: fem. with <span class=\"ar\">ة</span>. (S, O, TA.) -b3- Also A camel <i>whose back is not used, on account of galls,</i> or <i>sores, upon it:</i> or <i>unsound in the back by reason of galls,</i> or <i>sores,</i> or <i>from some other cause.</i> (Th.) Thus it has two contr. significations. (TA.) -A3- See also <span class=\"ar\">ظَهِرٌ</span>.</p><p><b class=\"ar\">ظِهَارَةٌ</b> [The <i>facing,</i> or <i>outer covering,</i> or] <i>what is uppermost,</i> (TA,) <i>what is apparent</i> (Msb, TA) <i>to the eye,</i> (Msb,) <i>not next the body,</i> of a garment; (TA;) and in like manner, <i>what is uppermost and apparent, not next the ground,</i> of a carpet; (TA;) as also <span class=\"ar\"> <span class=\"ar\">ظَاهِرَةٌ</span></span>: (JK:) <i>contr. of</i> <span class=\"ar\">بِطَانَةٌ</span>: (S, O, Msb, K:) pl. <span class=\"ar\">ظَهَائِرُ</span>. (TA.)</p><p><b class=\"ar\">ظَهِيرَةٌ</b> The <i>point of midday:</i> (M, A, K:) or only <i>in summer:</i> (M, K:) or <i>i. q.</i> <span class=\"ar\">هَاجِرَةٌ</span> [i. e. <i>midday in summer</i> or <i>when the heat is vehement:</i> or the <i>period from a little before, to a little after, midday in summer:</i> or <i>midday, when the sun declines from the meridian, at the</i> <span class=\"ar\">ظُهْر</span>: or <i>from its declining until the</i> <span class=\"ar\">عَصْر</span>]: (S, O, TA:) or the <span class=\"ar\">هَاجِرَة</span>, which is <i>when the sun declines from the meridian:</i> (Msb:) or the <i>vehement heat of midday:</i> (IAth, TA:) or <i>i. q.</i> <span class=\"ar\">ظُهْرٌ</span> [q. v.]: (Az, TA:) pl. <span class=\"ar\">ظَهَائِرُ</span>. (TA.) You say, <span class=\"ar\">أَتْيْتُهُ حَدَّ الظَّهِيرَةِ</span> [<i>I came to him at the point of midday in summer;</i> &amp;c.]: and <span class=\"ar\">حِينَ قَامَ قَائِمُ الظَّهِيرَةِ</span> [<i>when the sun had become high, and the shade had almost disappeared:</i> so expl. in art. <span class=\"ar\">قوم</span>]. (S, O.) And <span class=\"ar\">أَبْرِدْ عَنْكَ مِنَ الظَّهِيرَةِ</span> <i>Stay thou until the middayheat shall have become assuaged, and the air be cool.</i> (L in art. <span class=\"ar\">فيح</span>.) And hence, in a trad. of 'Omar, when a man came to him complaining of gout in the feet, he said, <span class=\"ar\">كَذَبَتْكَ الظَّهَائِرُ</span>, meaning <i>Take thou to walking during the heat of the middays in summer.</i> (TA.)</p><p><b class=\"ar\">ظُهَارِيَّةٌ</b> <i>One of the modes of seizing</i> [<i>and throwing down</i>] <i>in wrestling:</i> or <i>i. q.</i> <span class=\"ar\">شَغْزَبِيَّةٌ</span>: (K:) the <i>twisting one's leg with the leg of another in the manner that is termed</i> <span class=\"ar\">شَغْزَبِيَّة</span>, <i>and so throwing him down:</i> one says, <span class=\"ar\">أَخَذَهُ الظُّهَارِيَّةَ</span> and <span class=\"ar\">الشَّغْزَبِيَّةَ</span> [<i>He seized him and threw him down by the trick above described</i>]: both signify the same: (ISh, O:) or <span class=\"ar\">ظُهَارِيَّةٌ</span> signifies the <i>throwing one down upon the back.</i> (Ibn-'Abbád, O, K.) -b2- And (hence, as being likened thereto, TA) (tropical:) <i>A certain mode,</i> or <i>manner, of compressing,</i> or <i>coïtus.</i> (O, K, TA.) -b3- And <span class=\"ar\">أَوْثَقَهُ الظُّهَارِيَّةَ</span> <i>He bound his hands behind his back.</i> (Ibn-Buzurj, O, K, TA.)</p><p><b class=\"ar\">ظَاهِرٌ</b> [<i>Outward, exterior, external, extrinsic,</i> or <i>exoteric:</i> and hence, <i>appearing, apparent, overt, open, perceptible</i> or <i>perceived, manifest, conspicuous, ostensible, plain,</i> or <i>evident:</i> in all these senses] <i>contr. of</i> <span class=\"ar\">بَاطِنٌ</span>: (S, K, TA:) and so <span class=\"ar\"> <span class=\"ar\">ظَهِيرٌ</span></span>. (TA.) [Hence, <span class=\"ar\">ظَاهِرًا</span> <i>Outwardly,</i> &amp;c.: and <i>apparently;</i> &amp;c.: and <span class=\"ar\">فِى الظَّاهِرِ</span> <i>in appearance.</i> And <span class=\"ar\">الظَّاهِرُ أَنَّهُ كَذَا</span> <i>It appears,</i> or <i>it seems,</i> or <i>what seems to be the case is, that it is so,</i> or <i>thus.</i> And <span class=\"ar\">ظَاهِرُ كَذَا</span> for <span class=\"ar\">ظَاهِرٌ فِيهِ كَذَا</span>, meaning A person, or thing, <i>in whom,</i> or <i>in which, such a quality is apparent,</i> or <i>manifest,</i> &amp;c.: see an ex. in a verse cited in the first paragraph of art. <span class=\"ar\">طعن</span>.] See also <span class=\"ar\">مُظْهَرٌ</span>. -b2- [Hence also,] <span class=\"ar\">عَيْنٌ ظَاهِرَةٌ</span> <i>A prominent eye;</i> (S, O, K, TA;) <i>that fills its cavity.</i> (TA.) -b3- And <span class=\"ar\">هٰذَا</span> <span class=\"ar\">أَمْرٌ ظَاهِرٌ عَنْكَ عَارُهُ</span> (tropical:) <i>This is a thing,</i> or <i>an affair, of which the disgrace is remote from thee:</i> (S, TA:) or <i>does not cleave to thee.</i> (TA.) And <span class=\"ar\">هٰذَا عَيْبٌ ظَاهِرٌ عَنْكَ</span> (tropical:) <i>This is a vice,</i> or <i>fault, that does not cleave to thee.</i> (A.) A poet says, (namely, Kutheiyir, accord. to a copy of the S, or Aboo-Dhu-eyb, TA,) <span class=\"ar\">وَعَيَّرَهَا الوَاشُونَ أَنِّى أُحِبُّهَا</span> <span class=\"ar\">وَتِلْكَ شَكَاةٌ ظَاهِرٌ عَنْكَ عَارُهَا</span> (tropical:) [<i>And the slanderers taunted her with the fact of my loving her; but that is a fault of which the disgrace is remote from thee</i>]. (S, TA.) -b4- [<span class=\"ar\">الظَّاهِرُ</span> also signifies <i>The outside,</i> or <i>exterior,</i> of a thing. You say, <span class=\"ar\">نَزَلَ ظَاهِرَ المَدِينَةِ</span> <i>He alighted,</i> or <i>took up his abode, outside the city:</i> comp. <span class=\"ar\">ظَاهِرَةٌ</span>. Hence,] <span class=\"ar\">ظَاهِرُ الكَفِّ</span> and <span class=\"ar\">ظَاهِرُ</span> <span class=\"ar\">القَدَمِ</span>; and another signification of <span class=\"ar\">ظَاهِرٌ</span>: for all of which see <span class=\"ar\">ظَهْرٌ</span>, third quarter. -b5- [Also <i>The external, outward,</i> or <i>extrinsic, state, condition,</i> or <i>circumstances,</i> of a man: and <i>the outward,</i> or <i>apparent, character,</i> or <i>disposition of the mind:</i> opposed to <span class=\"ar\">البَاطِنُ</span>.] -b6- One says also, <span class=\"ar\">فُلَانٌ ظَاهِرٌ</span> <span class=\"ar\">عَلَى فُلَانٍ</span> <i>Such a one has the ascendancy,</i> or <i>mastery, over such a one; is conqueror of him,</i> or <i>victorious over him.</i> (TA.) And <span class=\"ar\">هٰذَا أَمْرٌ</span> <span class=\"ar\">ظَاهِرٌ بِكَ</span> <i>This is a thing,</i> or <i>an affair, that overcomes,</i> or <i>overpowers, thee.</i> (TA.) And <span class=\"ar\">هٰذَا أَمْرٌ</span> <span class=\"ar\">أَنْتَ بِهِ ظَاهِرٌ</span> <i>This is an affair which thou hast power to do.</i> (TA.) [And <span class=\"ar\">هُوَ ظَاهِرٌ عَلَى كَذَا</span> <i>He is a conqueror, a winner, an achiever,</i> or <i>an attainer, of such a thing:</i> see an ex. voce <span class=\"ar\">غَرَبٌ</span>, near the end.] And <span class=\"ar\">الظَّاهِرُ</span> is one of the names of God, meaning <i>The Ascendant,</i> or <i>Predominant, over all things:</i> or, as some say, <i>He who is known -by inference of the mind from what appears to mankind of the effects of his actions and his attributes.</i> (IAth, TA.) -b7- <span class=\"ar\">حَاجَتُهُ عِنْدَكَ ظَاهِرَةٌ</span> means (tropical:) <i>His want is in thine estimation</i> [<i>an object of contempt,</i> or <i>neglect, as though</i>] <i>cast behind the back.</i> (O, * TA.) -b8- <span class=\"ar\">قَرَأَهُ ظَاهِرًا</span>: see <span class=\"ar\">ظَهْرٌ</span>, towards the end of the paragraph. -A2- <span class=\"ar\">شَآءٌ ظَوَاهِرُ</span> <i>Sheep,</i> or <i>goats, that come to the water every day at noon.</i> (TA.)</p><p><b class=\"ar\">ظَاهِرَةٌ</b> as a subst.; and its pl. <span class=\"ar\">ظَوَاهِرُ</span>: see <span class=\"ar\">ظَهْرٌ</span>, in four places, in the third quarter of the paragraph. [Hence,] <span class=\"ar\">قُرَيْشُ الظَّوَاهِرِ</span> <i>Those, of Kureysh, that dwell in the exterior of Mekkeh,</i> (O,) <i>upon the mountains thereof,</i> (K, * TA,) or <i>upon the higher parts of Mekkeh:</i> (TA:) those who dwell in the lower parts are called <span class=\"ar\">قُرَيْشُ البِطَاحِ</span>; (O, * TA;) and these are the more honourable, (O, TA, *) because they are neighbours of the House of God. (O.) -b2- See also <span class=\"ar\">ظِهَارَةٌ</span>. -A2- And see <span class=\"ar\">ظَهِيرٌ</span>. -A3- Also The <i>coming</i> of camels, (S, O, K, TA,) and of sheep or goats, (TA,) <i>to the water every day, at noon.</i> (S, O, K, TA.) One says, of camels, [and of sheep or goats,] <span class=\"ar\">تَرِدُ الظَّاهِرَةَ</span> [<i>They come to the water every day, at noon</i>]: and Sh says that they return from the water at the <span class=\"ar\">عَصْر</span>. (TA.) And <span class=\"ar\">شَرِبَ الفَرَسُ ظَاهِرَةً</span> <i>The horse drank every day, at noon.</i> (TA.) <span class=\"ar\">ظَاهِرَةُ الغِبِّ</span> [<i>The coming to the water at noon on alternate days</i>] is for sheep or goats; scarcely ever, or never, for camels; and is a little shorter [in the interval] than what is called [simply] <span class=\"ar\">الغِبُّ</span>. (O, TA.)</p><p><b class=\"ar\">مَظْهَرٌ</b> <i>i. q.</i> <span class=\"ar\">مَصْعَدٌ</span> [i. e. <i>A place of ascent,</i> or <i>a place to which one ascends</i>]; (O, K; in some copies of the latter of which, both words are erroneously written with damm to the <span class=\"ar\">م</span>; TA;) and <span class=\"ar\">دَرَجَةٌ</span> [as meaning <i>a degree, grade, rank, condition,</i> or <i>station,</i> or <i>an exalted,</i> or <i>a high, grade,</i> &amp;c.]: (O:) used by En-Nábighah ElJaadee as meaning <i>Paradise.</i> (O, TA.)</p><p>[ <b class=\"ar\">مُظْهَرٌ</b> <i>Made apparent,</i> &amp;c. -b2- And hence, as also <span class=\"ar\"> <span class=\"ar\">ظَاهِرٌ</span></span>, but the former more commonly, applied to a noun, <i>Explicit;</i> and, elliptically, <i>an explicit noun;</i> opposed to <span class=\"ar\">مُضْمَرٌ</span> and <span class=\"ar\">ضَمِيرٌ</span> (a concealed noun, i. e. a pronoun); and to <span class=\"ar\">مُبْهَمٌ</span> (a noun of vague signification).]</p><p><b class=\"ar\">مُظْهِرٌ</b> <i>Possessing camels for riding</i> or <i>for carrying goods:</i> pl. <span class=\"ar\">مُظْهِرُونَ</span>. (S, * K, * TA.) -A2- And A camel <i>made to sweat by the</i> <span class=\"ar\">ظَهِيرَة</span> [or <i>vehement heat of midday in summer</i>]. (Sgh, K, TA.) And accord. to As, one says, <span class=\"ar\">أَتَانَا فُلَانٌ <span class=\"ar\">مُظَهِّرًا</span></span>, meaning <i>Such a one came to us in the time of the</i> <span class=\"ar\">ظَهِيرَة</span> [or <i>midday in summer,</i> &amp;c.]: but accord. to A 'Obeyd, others say <span class=\"ar\">مُظْهِرًا</span>, without teshdeed; and this is the proper form: (S) or both mean, <i>in the time of the</i> <span class=\"ar\">ظُهْر</span>. (O.)</p><p><b class=\"ar\">مُظَهَّرٌ</b> : see <span class=\"ar\">ظَهِيرٌ</span>, near the end of the paragraph.</p><p><b class=\"ar\">مُظَهِّرٌ</b> : see <span class=\"ar\">مُظْهِرٌ</span>.</p><p><b class=\"ar\">مُظْهُورٌ</b> pass. part. n. of <span class=\"ar\">ظَهَرَ</span> [q. v.]. -b2- See also <span class=\"ar\">ظَهِرٌ</span>.</p>"},"ظلل":{"mf":"الظِّلُّ: ضدُّ الضَّحِّ، وهو أعمُّ من الفيء، فإنه يقال: ظِلُّ اللّيلِ، وظِلُّ الجنّةِ، ويقال لكلّ موضع لم تصل إليه الشّمس: ظِلٌّ، ولا يقال الفيءُ إلّا لما زال عنه الشمس، ويعبّر بِالظِّلِّ عن العزّة والمنعة، وعن الرّفاهة، قال تعالى: إِنَّ الْمُتَّقِينَ فِي ظِلالٍ<br><strong>[المرسلات/ ٤١]، أي:</strong><br>في عزّة ومناع، قال: أُكُلُها دائِمٌ وَظِلُّها<br>[الرعد/ ٣٥]، هُمْ وَأَزْواجُهُمْ فِي ظِلالٍ [يس/ ٥٦]، يقال: ظَلَّلَنِي الشّجرُ، وأَظَلَّنِي.<br>قال تعالى: وَظَلَّلْنا عَلَيْكُمُ الْغَمامَ<br>[البقرة/ ٥٧]، وأَظَلَّنِي فلانٌ: حرسني، وجعلني في ظِلِّهِ وعزّه ومناعته. وقوله: يَتَفَيَّؤُا ظِلالُهُ<br>[النحل/ ٤٨]، أي: إنشاؤه يدلّ على وحدانيّة الله، وينبئ عن حكمته. وقوله: وَلِلَّهِ يَسْجُدُ إلى قوله: وَظِلالُهُمْ<br><strong>«٢»</strong>. قال الحسن: أمّا ظِلُّكَ<br><br>فيسجد لله، وأمّا أنت فتكفر به <strong>«١»</strong>، وظِلٌّ ظَلِيلٌ:<br>فائض، وقوله: وَنُدْخِلُهُمْ ظِلًّا ظَلِيلًا<br>[النساء/ ٥٧]، كناية عن غضارة العيش، وَالظُّلَّةُ: سحابةٌ تُظِلُّ، وأكثر ما يقال فيما يستوخم ويكره. قال تعالى: كَأَنَّهُ ظُلَّةٌ<br>[الأعراف/ ١٧١]، عَذابُ يَوْمِ الظُّلَّةِ<br>[الشعراء/ ١٨٩]، أَنْ يَأْتِيَهُمُ اللَّهُ فِي ظُلَلٍ مِنَ الْغَمامِ<br>[البقرة/ ٢١٠]، أي: عذابه يأتيهم، والظُّلَلُ: جمعُ ظُلَّةٍ، كغُرْفَةٍ وغُرَفٍ، وقُرْبَةٍ وقُرَبٍ، وقرئ: (في ظِلَالٍ) <strong>«٢»</strong> وذلك إمّا جمع ظُلَّةٍ نحو: غُلْبَةٍ وغِلَابٍ، وحُفْرَةٍ وحِفَارٍ، وإمّا جمعُ ظِلّ نحو: يَتَفَيَّؤُا ظِلالُهُ<br>[النحل/ ٤٨]، وقال بعض أهل اللّغة: يقال للشّاخص ظِلٌّ. قال: ويدلّ على ذلك قول الشاعر:<br><span class=\"num\">٣٠٥-</span><br>لمّا نزلنا رفعنا ظِلَّ أخبيةٍ<br><strong>«٣»</strong> وقال: ليس ينصبون الظِّلَّ الذي هو الفيء إنّما ينصبون الأخبية، وقال آخر:<br><span class=\"num\">٣٠٦-</span><br>يتبع أفياء الظِّلَالِ عشيّة<br><strong>«٤»</strong> أي: أفياء الشّخوص، وليس في هذا دلالة فإنّ قوله: (رفعنا ظِلَّ أخبيةٍ)، معناه: رفعنا الأخبية فرفعنا به ظِلَّهَا، فكأنّه رفع الظِّلَّ. وقوله:<br>أفياءُ الظِّلَالِ فَالظِّلَالُ عامٌّ والفيءُ خاصّ، وقوله: (أفياءُ الظِّلَالِ)، هو من إضافة الشيء إلى جنسه. والظُّلَّةُ أيضا: شيءٌ كهيئة الصُّفَّة، وعليه حمل قوله تعالى: وَإِذا غَشِيَهُمْ مَوْجٌ كَالظُّلَلِ<br>[لقمان/ ٣٢]، أي: كقطع السّحاب. وقوله تعالى: لَهُمْ مِنْ فَوْقِهِمْ ظُلَلٌ مِنَ النَّارِ وَمِنْ تَحْتِهِمْ ظُلَلٌ<br>[الزمر/ ١٦]، وقد يقال: ظِلٌّ لكلّ ساتر محمودا كان أو مذموما، فمن المحمود قوله: وَلَا الظِّلُّ وَلَا الْحَرُورُ<br>[فاطر/ ٢١]، وقوله: وَدانِيَةً عَلَيْهِمْ ظِلالُها<br>[الإنسان/ ١٤]، ومن المذموم قوله: وَظِلٍّ مِنْ يَحْمُومٍ<br>[الواقعة/ ٤٣]، وقوله: إِلى ظِلٍّ ذِي ثَلاثِ شُعَبٍ<br>[المرسلات/ ٣٠]، الظِّلُّ هاهنا كالظُّلَّةِ لقوله: ظُلَلٌ مِنَ النَّارِ<br>[الزمر/ ١٦]، وقوله: لا ظَلِيلٍ<br>[المرسلات/ ٣١]، لا يفيد فائدة الظِّلِّ في كونه واقيا عن الحرّ، وروي: «أنّ النبيّ صلّى الله عليه وسلم كان إذا<br><br>مشى لم يكن له ظِلٌّ» <strong>«١»</strong>، ولهذا تأويل يختصّ بغير هذا الموضع <strong>«٢»</strong>. وظَلْتُ وظَلِلْتُ بحذف إحدى اللّامين يعبّر به عمّا يفعل بالنهار، ويجري مجرى صرت، فَظَلْتُمْ تَفَكَّهُونَ<br>[الواقعة/ ٦٥]، لَظَلُّوا مِنْ بَعْدِهِ يَكْفُرُونَ<br>[الروم/ ٥١]، ظَلْتَ عَلَيْهِ عاكِفاً<br>[طه/ ٩٧].","mq":[["ستر شي لشي، وهو الذي يسمي الظل"],"الظاء واللام أصلٌ واحد، يدلُّ على ستر شئٍ لشئ، وهو الذى يُسمَّى الظّلّ. و [كلمات] البابِ عائدةٌ إليه. فالظِّلّ: ظِلّ الإنسان وغيرِه، ويكونُ بالغداة والعَشىّ، والفئُ لا يكون إلا بالعشىّ. وتقول: أظَّلْتنى الشّجرة.<br>وظِلٌّ ظليل: [دائم (٢)<br>]. واللَّيل ظِلٌّ (٣)<br>. قال:<br>قد أَعْسِفُ النّازحَ المجهولَ مَعْسِ"],"ln":"<p><b>1.</b> <b class=\"ar\">ظَلَّ</b> , aor. <span class=\"ar\">يَظِلُّ</span>, inf. n. <span class=\"ar\">ظِلَالَةٌ</span>: see 4. -A2- <span class=\"ar\">ظَلَّ</span>, (T, M, Msb, K,) first pers. <span class=\"ar\">ظَلِلْتُ</span>, (T, S, M, O, Msb, K,) [and accord. to SM <span class=\"ar\">ظَلَلْتُ</span> also, for he says that] the verb is of the class of <span class=\"ar\">مَنَعَ</span> as well as of the class of <span class=\"ar\">تَعِبَ</span>, (TA,) and <span class=\"ar\">ظَلْتُ</span>, (T, S, * M, O, K,) likened to <span class=\"ar\">لَسْتُ</span>, (M, K, *) formed by rejecting the former <span class=\"ar\">ل</span> in <span class=\"ar\">ظَلِلْتُ</span>, (T, O,) and <span class=\"ar\">ظِلْتُ</span>, which is [also] originally <span class=\"ar\">ظَلِلْتُ</span>, (Sb, T, M, O, K,) formed by transferring to the <span class=\"ar\">ظ</span> the vowel of the rejected <span class=\"ar\">ل</span>, (Sb, T, M, O,) anomalously, (Sb, M,) the latter of the dial. of the people of El-Hijáz; (T;) aor. <span class=\"ar\">يَظَلُّ</span>; (S, * M, O, * Msb, K;) imperative <span class=\"ar\">اِظْلَلْ</span> and <span class=\"ar\">ظَلْ</span> (T) [and it is implied in the M voce <span class=\"ar\">قَرَّ</span> that one says also <span class=\"ar\">اِظْلِلْ</span> and <span class=\"ar\">ظِلْ</span>, which indicates that the aor. is also <span class=\"ar\">يَظِلُّ</span>, but this requires confirmation, which I have not anywhere found]; inf. n. <span class=\"ar\">ظُلُولٌ</span> (T, S, M, O, Msb, K) and <span class=\"ar\">ظَلٌّ</span> (M, K) and <span class=\"ar\">ظِلٌّ</span>; (thus also in a copy of the M; [but this I think doubtful;]) accord. to Lth, (T,) or Kh, (Msb,) [i. e. accord. to the author of the 'Eyn,] is said only of a thing that is done in the day, or daytimes; (T, S, M, O, Msb;) like as <span class=\"ar\">بَاتَ</span>, aor. <span class=\"ar\">يَبِيتُ</span>, is said only of a thing that is done in the night: (T:) it is an incomplete [i. e. a non-attributive] verb, relating to a time in which is a shade from the sun, from morning to evening, or from sunrise to sunset: (Esh-Shiháb, TA:) one says, <span class=\"ar\">ظَلَّ</span> <span class=\"ar\">فُلَانٌ نَهَارَهُ صَائِمًا</span> [<i>Such a one was during his day fasting;</i> or <i>he passed his day fasting</i>]: (Lth, T:) and <span class=\"ar\">ظَلَّ نَهَارَهُ يَفْعَلُ كَذَا</span> [<i>He was in,</i> or <i>during, his day doing such a thing;</i> or <i>he passed his day doing such a thing</i>]: (M, K:) and <span class=\"ar\">ظَلِلْتُ أَعْمَلُ</span> <span class=\"ar\">كَذَا</span> [<i>I was in the day</i> or <i>daytime,</i> or <i>I passed the day, doing such a thing;</i> or] <i>I did such a thing in the day</i> or <i>daytime.</i> (S, O, Msb. *) In the saying of 'Antarah, <span class=\"ar\">وَلَقَدْ أَبِيتُ عَلَى الطَّوَى وَأَظَلُّهُ</span> <span class=\"ar\">حَتَّى أَنَالَ بِهِ كَرِيمَ المَأْكَلِ</span> [app. meaning <i>And verily I pass the night in hunger, and I pass the day in it, that I may attain thereby plentiful eating</i>], <span class=\"ar\">أَظَلُّهُ</span> is for <span class=\"ar\">أَظَلُّ</span> <span class=\"ar\">عَلَيْهِ</span>. (S, O.) And accord. to some, (TA,) <span class=\"ar\">ظَلَّ</span> <span class=\"ar\">لَيْلَهُ</span> occurs in poetry; (M, K, TA;) so that one says, <span class=\"ar\">ظَلَّ لَيْلَهُ يَفْعَلُ كَذَا</span> [<i>He was in,</i> or <i>during, his night,</i> or <i>he passed his night, doing such a thing</i>]: but it is said that in this case the verb has the meaning next following. (TA.) -b2- And it signifies also <i>He,</i> or <i>it, became;</i> syn. <span class=\"ar\">صَارَ</span>: (Er-Rághib, TA:) being in this sense likewise an incomplete [i. e. a non-attributive] verb, divested of that meaning of time which it radically denotes; as in the phrase in the Kur [xvi. 60 and xliii. 16], <span class=\"ar\">ظَلَّ وَجْهُهُ مُسْوَدًّا</span> [<i>His face becomes black</i>]: so says Ibn-Málik: (TA:) or this may mean <i>his face continues all the day black:</i> (Bd in xvi. 60:) and one says also, <span class=\"ar\">ظَلَّ</span> <span class=\"ar\">يَفْعَلُ كَذَا</span> meaning <i>He continued doing such a thing:</i> this too is mentioned by Ibn-Málik, and is of the dial. of the people of Syria. (TA.) -b3- It is also a complete [i. e. an attributive] verb as meaning <i>He,</i> or <i>it, continued;</i> as is said in the Expos. of the “ Shifè, ” and by Ibn-Málik; and, as Ibn-Málik likewise says, <i>it was,</i> or <i>became, long.</i> (TA.)</p><p><b>2.</b> <b class=\"ar\">ظللّٰهُ عَلَيْهِ</b> [<i>He made it to give shade over him,</i> or <i>it,</i>] (M,) inf. n. <span class=\"ar\">تَظْلِيلٌ</span>. (O.) It is said in the Kur [vii. 160, and the like is said in ii. 54], <span class=\"ar\">وَظَلَّلْنَا عَلَيْهِمُ الغَمَامَ</span> <i>And we made the clouds to give shade over them.</i> (M.) -b2- [And <span class=\"ar\">ظللّٰهُ</span> signifies <i>He shaded him,</i> or <i>it.</i> See an ex. in a verse of Jereer in art. <span class=\"ar\">ردف</span>, conj. 3.] <span class=\"ar\">لٰكِنْ عَلَى</span> <span class=\"ar\">الأَثَلَاتِ لَحْمٌ لَا يُظَلَّلُ</span> [<i>But at the tamarisk-trees is flesh that will not be shaded,</i> or, accord. to the reading given by Meyd, <span class=\"ar\">بِالأَثَلَاتِ</span>,] is a prov., said by Beyhes, in allusion to the flesh of his slain brothers, on the occasion of persons saying, <span class=\"ar\">ظَلِّلُوا لَحْمَ جَزُورِكُمْ</span> [<i>Shade ye the flesh of your slaughtered camel</i>]. (S, O.) -A2- See also 4. -A3- One says also <span class=\"ar\">ظلّل بِالسَّوْطِ</span>, meaning <i>He made a sign with the whip for the purpose of frightening.</i> (Ibn-'Abbád, O, K.)</p><p><b>4.</b> <b class=\"ar\">اظلّ</b> , said of a day, <i>It was,</i> (S, O,) or <i>became,</i> (M, K,) <i>shady,</i> or <i>a day having shade:</i> (S, M, O, K:) or <i>it was a day having clouds,</i> or <i>other</i> [<i>causes of shade</i>]: (T:) or <i>it was continually shady;</i> as also <span class=\"ar\"> <span class=\"ar\">ظَلَّ</span></span>, aor. <span class=\"ar\">يَظِلُّ</span>, inf. n. <span class=\"ar\">ظِلَالَةٌ</span>. (Msb.) -b2- And, said of a thing, [<i>It extended its shade;</i> or] <i>its shade extended;</i> as also <span class=\"ar\"> <span class=\"ar\">ظلّل</span></span>. (Msb.) -A2- <span class=\"ar\">أَظَلَّتْنِى الشَّجَرَةُ</span> [<i>The tree shaded me,</i> or <i>afforded me shade</i>]: and in like manner one says of other things than trees. (S, O.) <span class=\"ar\">أَظَلَّكَ</span> said of a building, or of a mountain, or of a cloud, means <i>It protected thee,</i> and <i>cast its shade upon thee.</i> (Mgh.) -b2- [Hence,] <span class=\"ar\">اظلّهُ</span> (assumed tropical:) <i>He took him into his shelter,</i> or <i>protection:</i> (TA:) or <i>he guarded,</i> or <i>protected, him,</i> and <i>placed him within the scope of his might,</i> or <i>power of resistance</i> or <i>defence.</i> (Er-Rághib, TA.) -b3- And <span class=\"ar\">أَظَلَّنِى</span> (assumed tropical:) <i>It</i> (a thing) <i>covered me:</i> (M, K:) or <i>it approached me,</i> or <i>drew near to me, so as to cast its shade upon me:</i> (K:) or it has both of these meanings: (M:) or <span class=\"ar\">أَظَلَّكَ</span> means <i>he,</i> (T, S,) or <i>it,</i> (O,) <i>approached thee,</i> or <i>drew near to thee, as though he,</i> or <i>it, cast his,</i> or <i>its, shade upon thee.</i> (T, S, O.) And hence one says, <span class=\"ar\">أَظَلَّكَ أَمْرٌ</span> (assumed tropical:) <i>An event approached thee,</i> or <i>drew near to thee:</i> (S, O:) and in like manner one says of a month. (T, S, O.) And <span class=\"ar\">اظلّ</span> [alone] (assumed tropical:) <i>It</i> (a thing) <i>advanced:</i> or <i>approached,</i> or <i>drew near.</i> (Msb.) And <i>i. q.</i> <span class=\"ar\">أَشْرَفَ</span> [app. as meaning (assumed tropical:) <i>He,</i> or <i>it, became within sight,</i> or <i>view</i>]. (Msb.)</p><p><b>5.</b> <b class=\"ar\">تَظَلَّلَ</b> see the next paragraph. It is also pronounced <span class=\"ar\">تَظَلَّى</span>: (IAar, T:) and signifies <i>He kept to shady places, and to ease,</i> or <i>repose:</i> (IAar, T and K in art. <span class=\"ar\">ظلى</span>:) it is like <span class=\"ar\">تَظَنَّيْتُ</span> from <span class=\"ar\">الظَّنُّ</span>. (T in that art.)</p><p><b>10.</b> <b class=\"ar\">استظلّ</b> , (T,) or <span class=\"ar\">استظلّ بِالِظِّلِّ</span>, (Msb, TA,) <i>He</i> (a man, T) <i>sheltered,</i> or <i>protected, himself by means of the shade:</i> (T, TA:) or the latter means <i>he inclined to the shade and sat in it.</i> (M, K.) And <span class=\"ar\">استظلّ مِنَ الشَّىْءِ</span> and <span class=\"ar\">بِهِ</span> means <span class=\"ar\"> <span class=\"ar\">تَظَلَّلَ</span></span> [i. e. <i>he shaded himself</i> (<span class=\"ar\">تظلّل</span> being quasi-pass. of <span class=\"ar\">ظَلَّلَهُ</span>) <i>from the thing</i> and <i>by means of it</i>]. (M, K.) You say, <span class=\"ar\">استظلّ بِهِ مِنَ الشَّمْسِ</span> [<i>He shaded himself with it,</i> or <i>by means of it, from the sun</i>]. (T.) And <span class=\"ar\">استظلّ بِالشَّجَرَةِ</span> <i>He shaded and sheltered himself by means of the tree.</i> (Ibn-'Abbád, S, O.) -b2- <span class=\"ar\">استظلّ الدَّمُ</span> <i>The blood was in the</i> <span class=\"ar\">جَوْف</span> [or <i>belly,</i> or <i>interior of the belly,</i> or the <i>chest</i>]. (T, O, K, TA. [In the CK, <span class=\"ar\">من</span> <span class=\"ar\">الجَوْفِ</span> is put for <span class=\"ar\">فِى الجَوْفِ</span>.]) -b3- <span class=\"ar\">استظلّت العَيْنُ</span>, (T, Ibn-'Abbád, O,) or <span class=\"ar\">العُيُونُ</span>, (K,) <i>The eye,</i> (T, Ibn-'Abbád, O,) meaning that of a she-camel, (Ibn-'Abbád, O,) or <i>the eyes,</i> (K,) <i>sank,</i> or <i>became depressed, in the head.</i> (T, Ibn-'Abbád, O, K.) -b4- And <span class=\"ar\">استظلّ الكَرْمُ</span> <i>The grape-vine became luxuriant,</i> or <i>abundant and dense, in its branches whereon were the bunches.</i> (M, K.)</p><p><b class=\"ar\">ظِلٌّ</b> properly signifies <i>Shade;</i> i. e. the <i>light of the sun without the rays:</i> when there is no light, it is <span class=\"ar\">ظُلْمَةٌ</span>, not <span class=\"ar\">ظِلٌّ</span>: (S, O:) <i>contr. of</i> <span class=\"ar\">ضِحٌّ</span>: (M, K:) or <i>i. q.</i> <span class=\"ar\">فَىْءٌ</span>: (K:) so some say: (M:) or so the [common] people say: (IKt, Msb:) or the former is [<i>shade</i>] <i>in the morning;</i> and the latter is in the evening: (M, K:) or, accord. to IKt, the former is <i>in the morning and in the evening;</i> but the latter is only after the declining of the sun from the meridian: ISk says that the former is <i>from the rising of the sun to its declining;</i> and the latter, from the declining to the setting: Th says that the <span class=\"ar\">ظِلّ</span> of a tree &amp;c. is <i>in the morning;</i> and the <span class=\"ar\">فَىْء</span>, in the evening: (Msb:) Ru-beh says, (M, Msb,) <i>any place,</i> (M,) or <i>any thing,</i> (Msb,) <i>upon which the sun has been and which it has quitted</i> is termed <span class=\"ar\">ظِلٌّ</span> and <span class=\"ar\">فَىْءٌ</span>; (M, Msb;) but <i>a thing</i> [or <i>place</i>] <i>upon which the sun has not been</i> is termed <span class=\"ar\">ظِلٌّ</span> [only]; and hence it is said that the sun annuls, or supersedes, the <span class=\"ar\">ظِلّ</span>, and the <span class=\"ar\">فَىْء</span> annuls, or supersedes, the sun: (Msb:) AHeyth says, the <span class=\"ar\">ظِلّ</span> is <i>anything upon which the sun has not come;</i> and the term <span class=\"ar\">فَىْء</span> is applied only after the declining of the sun; the <span class=\"ar\">فَىْء</span> being eastwards and the <span class=\"ar\">ظِلّ</span> being westwards; and the <span class=\"ar\">ظِلّ</span> being termed <span class=\"ar\">ظِلّ</span> <i>from the beginning of the day to the declining of the sun;</i> after which it is termed <span class=\"ar\">فَىْء</span> until the night: (T, TA:) one says the <span class=\"ar\">ظِلّ</span> of Paradise, but not its <span class=\"ar\">فَىْء</span>, because the sun will never replace its <span class=\"ar\">ظِلّ</span>; but En-Nábighah El-Jaadee has assigned to Paradise <span class=\"ar\">فَىْء</span> having <span class=\"ar\">ظِلَال</span>: (M, TA:) in a verse of Aboo-Sakhr ElHudhalee, <span class=\"ar\">ظِلٌّ</span> is made fem. as meaning <span class=\"ar\">مَنِيَّة</span> [i. e. <i>death</i>]: (Ham p. 161:) the pl. [of mult.] is <span class=\"ar\">ظِلَالٌ</span> (S, M, O, K) and <span class=\"ar\">ظُلُولٌ</span> and [of pauc.] <span class=\"ar\">أَظْلَالٌ</span>. (M, O, K.) The saying of a rájiz, <span class=\"ar\">كَأَنَّمَا وَجْهُكَ ظِلٌّ مِنْ حَجَرْ</span> [<i>As though thy face were a shade of a stone</i>] is said to mean hardness of face, and shamelessness: or the being black in the face: (T, TA:) for the Arabs say that there is nothing more dense in shade than a stone. (TA.) <span class=\"ar\">قَدْ ضَحَا ظِلُّهُ</span> [<i>His shade,</i> or <i>shadow, has become sun</i>] is said of the dead. (TA.) <span class=\"ar\">مَرَّ بِنَا كَأَنَّهُ ظِلُّ ذِئْبٍ</span> [<i>He passed by us as though he were the shadow of a wolf</i>] means swiftly, as does a wolf. (M.) <span class=\"ar\">اِنْتَعَلَتْ</span> <span class=\"ar\">ظِلَالَهَا</span> (assumed tropical:) [<i>They made their shadows to be as though they were sandals to them</i>] is said of camels or other beasts when it is midday in summer and they have no shadow [but such as is beneath them]: a rájiz says, <span class=\"ar\">قَدْ وَرَدَتْ تَمْشِى عَلَى ظِلَالِهَا</span> <span class=\"ar\">وَذَابَتِ الشَّمْسُ عَلَى قِلَالِهَا</span> [<i>They came to the water walking upon their shadows, and the sun was intensely hot upon the tops of their heads and humps</i>]. (T.) And one says, <span class=\"ar\">هُوَ يَتْبَعُ ظِلَّ نَفْسِهِ</span> (tropical:) [<i>He follows the shadow of himself;</i> i. e. a thing that he will not overtake; for], as a poet says, the shadow that goes with thee thou wilt not overtake by following: and <span class=\"ar\">هُوَ يُبَارِى ظِلَّ نَفْسِهِ</span> (tropical:) [<i>He strives to outstrip the shadow of himself</i>], meaning that he walks with a proud and self-conceited gait: so in the A. (TA.) And <span class=\"ar\">اِنْتَقَلْتُ عَنْ ظِلِّى</span> (tropical:) <i>I left my state,</i> or <i>condition.</i> (TA.) And <span class=\"ar\">تَرَكَ الظَّبْىُ ظِلَّهُ</span>: so in the T and S and O: (TA:) but [said to be] correctly, <span class=\"ar\">أَتْرُكُهُ تَرْكَ الظَّبْىِ ظِلَّهُ</span>, (K,) or <span class=\"ar\">لَأَتْرُكَنَّهُ</span>, (M, TA,) i. e. [<i>I will forsake him,</i> or <i>I will assuredly forsake him, as the gazelle forsakes</i>] <i>the place of its shade:</i> (O, TA:) [each, however, is app. right; and the former is the more agreeable with the following explanations:] a prov., (M,) applied to the man who is wont to take fright and flee; for the gazelle, when it takes fright and flees from a thing, never returns to it: (S, O, K:) by the <span class=\"ar\">ظِلّ</span> is here meant the covert in which it shades and shelters itself in the vehemence of the heat; then the hunter comes to it and rouses it, and it will not return thither; and one says, <span class=\"ar\">تَرَكَ الظَّبْىُ ظِلَّهُ</span>, meaning the place of its shade: it is applied to him who takes fright and flees from a thing, and forsakes it so as not to return to it; and to the case of a man's forsaking his companion. (Meyd.) [<span class=\"ar\">ثَقِيلُ الظِّلِّ</span> as applied to a man, see expl. in art. <span class=\"ar\">ثقل</span>: see also Har p. 250, where it is indicated that it may be rendered One <i>whose shadow,</i> even, <i>is oppressive,</i> and therefore much more so is his person.] In the phrase <span class=\"ar\">وَلَا ٱلظِّلُّ وَلَا ٱلْحَرُورُ</span>, (M, K) in the Kur [xxxv. 20], Th says, accord. to some, (M,) <span class=\"ar\">الظِّلُّ</span> means <i>Paradise;</i> (M, K;) and <span class=\"ar\">الحَرُورُ</span>, the fire [of Hell]: but he adds, I say that <span class=\"ar\">الظِّلُّ</span> is the <span class=\"ar\">ظِلّ</span> itself [i. e. <i>shade</i>], and <span class=\"ar\">الحَرُورُ</span> is the <span class=\"ar\">حَرّ</span> itself [i. e. heat]: (M: [see also <span class=\"ar\">حَرُورٌ</span>:]) and Er-Rághib says that <span class=\"ar\">ظِلٌّ</span> is sometimes assigned to anything; whether it be approved, as in the phrase above mentioned; or disapproved, as in <span class=\"ar\">وَظِلٍّ مِنْ يَحْمُومٍ</span> in the Kur [lvi. 42, meaning <i>And shade of smoke,</i> or <i>black smoke</i>]. (TA.) And <span class=\"ar\">الظِّلَالُ</span> means <span class=\"ar\">ظِلَالُ الجَنَّةِ</span> [<i>The shades of Paradise</i>]: (Fr, T, O, K, TA:) in some copies of the K, <span class=\"ar\">وَالظِّلَالُ</span> <span class=\"ar\">الجَنَّةُ</span>, which is a mistake: (TA:) [but this requires consideration; for] El-'Abbás Ibn- 'Abd-El-Muttalib says, <span class=\"ar\">مِنْ قَبْلِهَا طِبْتَ فِى الظِّلَالِ وَفِى</span> <span class=\"ar\">مُسْتَوْدَعٍ حَيْثُ يُخْصَفُ الوَرَقُ</span> [<i>Before it thou wast good in,</i> or <i>in the shades of, Paradise, and in a depositary in the part where leaves are sewed together to conceal the pudenda</i>]; (T, O, TA;) i. e. before thy descent to the earth (to which the pronoun in <span class=\"ar\">قبلها</span> relates), thou wast good in the loins of Adam when he was in Paradise. (TA.) <span class=\"ar\">الجَنَّةُ تَحْتَ ظِلَالِ السُّيُوفِ</span> [<i>Paradise is beneath the shades of the swords</i>] is a trad., meaning that fighting against unbelievers is a way of attaining to Paradise. (Marg. note in a copy of the “ Jámi' es-Sagheer.) <span class=\"ar\">مُلَاعِبُ ظِلِّهِ</span> is an appellation of <i>A certain bird;</i> [see art. <span class=\"ar\">لعب</span>;] and one says <span class=\"ar\">مُلَاعِبَا ظِلِّهِمَا</span>; and <span class=\"ar\">مُلَاعِبَاتُ</span> <span class=\"ar\">ظِلِّهِنَّ</span>: but when you make them indeterminate, you say <span class=\"ar\">مُلَاعِبَاتُ أَظْلَالِهِنَّ</span>. (T, O, K. [But in the TA in art. <span class=\"ar\">لعب</span>, it is said that one dualizes and pluralizes both nouns, because the appellation becomes determinate.]) -b2- <span class=\"ar\">ظِلُّ اللَّيْلِ</span> means (tropical:) <i>The blackness of the night:</i> (T, S, O, Msb;) metaphorically thus termed; (S;) as in the saying, <span class=\"ar\">أَتَانَا فِى ظِلِّ اللَّيْلِ</span> [<i>He came to us in the blackness of the night</i>]: (S, O:) or it signifies <span class=\"ar\">جُنْحُ اللَّيْلِ</span> [app. as meaning the <i>darkness,</i> and <i>confusedness, of the night;</i> see <span class=\"ar\">جُنْحٌ</span>]; (M, TA;) or so <span class=\"ar\">الظِّلُّ</span>: (K:) or this means <i>the night,</i> (M, K, TA,) <i>itself;</i> (M, TA;) so the astronomers say: (TA:) <i>all the night</i> is <span class=\"ar\">ظِلٌّ</span>: and so is <i>all the period from the shining of the dawn to the rising of the sun.</i> (T.) -b3- <span class=\"ar\">ظِلُّ النَّهَارِ</span> <i>is The colour of the day when the sun predominates over it</i> [app. meaning <i>when the light of the sun predominates over that of the early dawn</i>]. (K.) -b4- <span class=\"ar\">ظِلُّ</span> <span class=\"ar\">السَّحَابِ</span> means <i>Such, of the clouds, as conceal the sun:</i> or <i>the blackness of the clouds.</i> (M, K.) -b5- And <span class=\"ar\">ظِلَالُ البَحْرِ</span> means <i>The waves of the sea;</i> (O, K, TA;) because they are raised so as to shade the ship and those that are in it. (TA.) -b6- <span class=\"ar\">ظِلٌّ</span> also signifies <i>A</i> <span class=\"ar\">خَيَال</span> (M, O, K) <i>that is seen,</i> (M, K,) [i. e. <i>an apparition, a phantom,</i> or <i>a thing that one sees like a shadow,</i> i. e. what we term <i>a shade,</i>] <i>of the jinn,</i> or <i>genii,</i> and <i>of others:</i> (M, O, K:) or the <i>like of a</i> <span class=\"ar\">خَيَال</span> <i>of the jinn.</i> (T.) -b7- Also <i>Anything that shades one.</i> (TA.) -b8- And it is the subst. from <span class=\"ar\">أَظَلَّنِى الشَّىْءُ</span> meaning “ the thing covered me; ” (M, K;) [i. e. it means <i>A covering;</i>] in which sense Th explains it in the phrase <span class=\"ar\">إِلَى ظِلٍّ ذِى ثَلَاثِ شُعَبٍ</span> [in the Kur lxxvii. 30, <i>Unto a covering having three parts,</i> or <i>divisions</i>]; saying, the meaning is that the fire will have covered them; not that its <span class=\"ar\">ظِلّ</span> will be like that of the present world. (M. [See <span class=\"ar\">شُعْبَةٌ</span>.]) And <span class=\"ar\">ظِلُّ الشَّىْءِ</span> means (assumed tropical:) <i>That which serves for the veiling, covering,</i> or <i>protecting, of the thing;</i> syn. <span class=\"ar\">كِنُّهُ</span>. (M.) [Hence] one says, <span class=\"ar\">فُلَانٌ يَعِيشُ فِى ظِلِّ فُلَانٍ</span> i. e. (assumed tropical:) [<i>Such a one lives</i>] <i>in the shelter,</i> or <i>protection, of such a one.</i> (T, * S, O, Msb, * K. *) And <span class=\"ar\">السُّلْطَانُ ظِلُّ ٱللّٰهِ فِى الأَرْضِ</span>, (O, TA,) a saying of the Prophet, (O,) [meaning (assumed tropical:) <i>The sovereign,</i> or <i>ruling, power is God's means of defence in the earth,</i>] because he wards off harm from the people like as the <span class=\"ar\">ظِلّ</span> [properly so called] wards off the harm of the heat of the sun: (TA:) or the meaning is, (assumed tropical:) <i>God's means of protection:</i> or <i>God's</i> <span class=\"ar\">خَاصَّة</span> [or <i>special servant</i>]. (O, TA.) -b9- Also (assumed tropical:) <i>Might;</i> or <i>power of resistance</i> or <i>defence:</i> (M, K, TA:) whence [as some say] its usage in the Kur xiii. 35, and the usage of [the pl.] <span class=\"ar\">ظِلَال</span> in xxxvi. 56 and in lxxvii. 41: [but the primary signification is more appropriate in these instances:] and so in the saying, <span class=\"ar\">جَعَلَنِى فِى ظِلِّهِ</span> [i. e. (assumed tropical:) <i>He placed me within the scope of his might,</i> or <i>power of resistance</i> or <i>defence</i>]: so says Er-Rághib. (TA.) -b10- And (assumed tropical:) <i>A state</i> of life <i>ample in its means</i> or <i>circumstances, unstraitened,</i> or <i>plentiful, and easy, pleasant, soft,</i> or <i>delicate.</i> (TA.) -b11- Also (assumed tropical:) The <i>beginning</i> of winter. (T, O. [Accord. to the copies of the K, of youthfulness: but I think that <span class=\"ar\">الشَّبَاب</span> in this instance, in the K, is evidently a mistranscription for <span class=\"ar\">الشِّتَآء</span>.]) And (assumed tropical:) The <i>vehemence</i> (T, O, K) <i>of the heat</i> (T, O) of summer. (T, O, K.) -b12- Also (assumed tropical:) The <span class=\"ar\">شَخْص</span> [as meaning <i>person</i> of a human being, and as meaning the <i>bodily</i> or <i>corporeal form</i> or <i>figure</i> or <i>substance which one sees from a distance,</i> or the <i>material substance,</i>] of anything; (M, K, TA; [in the second and third of which is added, “ or its <span class=\"ar\">كِنّ</span>, ” a signification which I have mentioned above on the authority of the M;]) because of its [apparent] blackness [or darkness, resembling that of a shade or shadow]: (M, TA:) whence the saying, <span class=\"ar\">لَا يُفَارِقُ ظِلِّى ظِلَّكَ</span> (assumed tropical:) [<i>My person will not quit thy person</i>]; like the saying, <span class=\"ar\">لَا يُفَارِقُ</span> <span class=\"ar\">سَوَادِى سَوَادَكَ</span>: and the following exs. have been cited as instances of <span class=\"ar\">ظِلّ</span> in the sense of <span class=\"ar\">شَخْص</span>: the saying of a poet, <span class=\"ar\">لَمَّا نَزَلْنَا رَفَعْنَا ظِلَّ أَخْبِيَةٍ</span> [as though meaning <i>When we alighted, we raised the material fabric of tents</i>], for it is said that they do not set up the <span class=\"ar\">ظِلّ</span> which is the <span class=\"ar\">فَىْء</span>, but they only set up the tents; and the saying of another, <span class=\"ar\">تَتَبَّعَ أَفْيَآءَ الظِّلَالِ عَشِيَّةً</span> [as though meaning <i>He followed the shadows of the material objects in the evening</i>]: but Er-Rághib says that the former means, we raised the tents, and so raised the <span class=\"ar\">ظِلّ</span> thereof; and in the other ex., <span class=\"ar\">الظلال</span> is a general term, and <span class=\"ar\">الفَىْء</span> [or <span class=\"ar\">افيآء</span>] is a special term, so that it is an instance of the <span class=\"ar\">إِضَافَة</span> of a thing to its kind [i. e. of prefixing a noun to one significant of its kind]. (TA.) [See also <span class=\"ar\">ظَلَالَةٌ</span>.] -b13- And accord. to Ibn- 'Abbád, (O,) it signifies also The <i>nap,</i> or <i>villous substance, upon the surface of a garment,</i> or <i>piece of cloth;</i> syn. <span class=\"ar\">زِئْبِرٌ</span>. (O, K.)</p><p><b class=\"ar\">ظَلَّةٌ</b> <i>i. q.</i> <span class=\"ar\">إِقَامَةٌ</span> [<i>Continuance, residence, abode,</i> &amp;c.]. (K.) -b2- And <i>i. q.</i> <span class=\"ar\">صِحَّةٌ</span>: thus accord. to the copies of the K; but this may be a mistranscription; for Az and others mention, among the significations of <span class=\"ar\">ظلّة</span>, [in a copy of the T, written in this case, as in others, <span class=\"ar\"> <span class=\"ar\">ظُلَّة</span></span>,] that of <span class=\"ar\">صَيْحَةٌ</span> [q. v.]. (TA.)</p><p><b class=\"ar\">ظُلَّةٌ</b> <i>A thing that covers,</i> or <i>protects,</i> [or <i>shades,</i>] <i>one, overhead:</i> accord. to Lth, <i>i. q.</i> <span class=\"ar\"> <span class=\"ar\">مَظَلَّةٌ</span></span> or <span class=\"ar\">مِظَلَّةٌ</span> meaning <i>a thing that shades one from the sun:</i> (T:) see an ex. voce <span class=\"ar\">مِظَلَّةٌ</span>: <i>a covering:</i> and <i>i. q.</i> <span class=\"ar\">بُرْطُلَّةٌ</span>: (M, K:) this latter word correctly signifies <i>a</i> <span class=\"ar\">مِظَلَّة</span> <i>for the summer:</i> (TA in art. <span class=\"ar\">برطل</span>:) and <i>a thing by which one is protected from the cold and the heat:</i> (M:) <i>anything that protects and shades one, as a building</i> or <i>a mountain</i> or <i>a cloud:</i> (Mgh:) the <i>first portion that shades</i> (AZ, S, K) <i>of a cloud</i> (AZ, S) or <i>of clouds;</i> (K;) accord. to Er-Rághib, mostly said of that which is deemed unwholesome, and which is disliked; whence the use of the word in the Kur vii. 170: (TA:) and <i>what shades one, of trees:</i> (K:) or <i>anything that forms a covering over one,</i> (T, TA,) or <i>shades one:</i> (T:) and [particularly] <i>a thing like the</i> <span class=\"ar\">صُفَّة</span> [q. v.], (S, M, O, K,) <i>by which one protects himself from the heat and the cold:</i> (K:) or, accord. to the lawyers, <span class=\"ar\">ظُلَّةُ الدَّارِ</span> means <i>the</i> <span class=\"ar\">سُدَّة</span> [or <i>projecting roof</i>] <i>over the door of the house:</i> or <i>that of which the beams have one end upon the house and the other end upon the wall of the opposite neighbour:</i> (Mgh:) pl. <span class=\"ar\">ظُلَلٌ</span> (S, M, O, K) and <span class=\"ar\">ظِلَالٌ</span>. (M, K.) [See also <span class=\"ar\">ظَلَالٌ</span>.] One says also, <span class=\"ar\">دَامَتْ ظُلَّةُ</span> <span class=\"ar\">الظِّلِّ</span> and <span class=\"ar\"> <span class=\"ar\">ظِلَالَةُ</span>الظِّلِّ</span>, meaning <i>That whereby one shades himself,</i> (K, TA,) <i>of trees,</i> or <i>of stones,</i> or <i>of other things,</i> (TA,) [<i>continued.</i>] <span class=\"ar\">عَذَابُ يَوْمِ</span> <span class=\"ar\">الظُّلَّةِ</span>, in the Kur. [xxvi. 189], is said to mean [<i>The punishment of the day of</i>] <i>clouds beneath which was a hot wind</i> (<span class=\"ar\">سَمُوم</span>): (S, O, K:) or <i>an overshadowing cloud, beneath which they collected themselves together, seeking protection thereby from the heat that came upon them, whereupon it covered them,</i> (T, * K, TA,) <i>and they perished beneath it:</i> (T, TA:) or, accord. to some, <i>i. q.</i> <span class=\"ar\">عَذَابُ يَوْمِ الصُّفَّةِ</span>. (T: see art. <span class=\"ar\">صف</span>.) And <span class=\"ar\">لَهُمْ مِنْ فَوْقِهِمْ ظُلَلٌ مِنَ ٱلنَّارِ وَمِنْ تَحْتِهِمْ ظُلَلٌ</span>, in the Kur [xxxix. 18], means <i>To them</i> shall be <i>above them coverings of fire, and beneath them coverings</i> to those below them; Hell consisting of stages, one beneath another. (T, TA.) Seditions, or conflicts and factions, are mentioned in a trad. as being like <span class=\"ar\">ظُلَل</span>, by which are meant <i>Mountains,</i> and <i>clouds:</i> and El-Kumeyt likens waves of the sea to <span class=\"ar\">ظُلَل</span>. (TA.) And [the pl.] <span class=\"ar\">ظُلَلٌ</span> is used as meaning The <i>chambers of a prison.</i> (M, TA.) -A2- See also <span class=\"ar\">ظَلَّةٌ</span>.</p><p><b class=\"ar\">ظِلَّةٌ</b> <i>i. q.</i> <span class=\"ar\">ظِلَالٌ</span>; (T, K, TA;) app. a pl. of <span class=\"ar\">ظَلِيلٌ</span>, like as <span class=\"ar\">طِلَّةٌ</span> is of <span class=\"ar\">طَلِيلٌ</span>. (TA.)</p><p><b class=\"ar\">ظَلَلٌ</b> <i>Water that is beneath a tree,</i> (O,) or <i>beneath trees,</i> (K,) <i>upon which the sun does not come.</i> (O, K.) [See also <span class=\"ar\">ضَلَلٌ</span>.]</p><p><b class=\"ar\">ظَلَالٌ</b> , like <span class=\"ar\">سَحَابٌ</span>, [so accord. to the K, but in my copies of the S, <span class=\"ar\"> <span class=\"ar\">ظِلَال</span></span>,] <i>A thing that shades one,</i> (IAar, S, O, K, TA,) <i>such as a cloud,</i> (IAar, S, TA,) and <i>the like.</i> (IAar, TA.) [See also <span class=\"ar\">ظُلَّةٌ</span>.]</p><p><b class=\"ar\">ظِلَالٌ</b> pl. of <span class=\"ar\">ظِلٌّ</span>: (S, M, O, K:) -b2- and of <span class=\"ar\">ظُلَّةٌ</span>. (M, K.) -b3- [Also, app., pl. of <span class=\"ar\">ظَلِيلٌ</span>: see <span class=\"ar\">ظِلَّةٌ</span>. -b4- Freytag has app. understood it to be expl. in the K as syn. with <span class=\"ar\">مَظَلَّةٌ</span>; though it certainly is not.] -b5- See also <span class=\"ar\">ظَلَالٌ</span>.</p><p><b class=\"ar\">مَكَانٌ ظَلِيلٌ</b> <i>A place having shade:</i> (M, K:) or <i>having constant shade.</i> (T, S, M, O, K.) And hence <span class=\"ar\">ظِلٌّ ظَلِيلٌ</span> (M, K) <i>Constant shade:</i> (S:) or <i>extensive shade:</i> (O:) or in this case the latter word denotes intensiveness [meaning <i>dense</i>]; (M, K, TA;) being like <span class=\"ar\">شَاعِرٌ</span> in the phrase <span class=\"ar\">شِعْرٌ شَاعِرٌ</span>. (TA.) <span class=\"ar\">ظِلًّا ظَلِيلًا</span> in the Kur iv. 60 is said by Er-Rághib to be an allusion to ease and pleasantness of life. (TA.) One says also <span class=\"ar\">أَيْكَةٌ ظَلِيلَةٌ</span> <i>A collection of trees tangled,</i> or <i>luxuriant,</i> or <i>abundant and dense.</i> (TA.) In the saying of Uheyhah Ibn-El-Juláh, describing palm-trees, <span class=\"ar\">هِىَ الظِّلُّ فِى الحَرِّ حَقَّ الظَّلِ</span> <span class=\"ar\">لِ وَالمَنْظَرُ الأَحْسَنُ الأَجْمَلُ</span> The final character of line one and the initial character of line two are unclear. [ISd says] in my opinion, he means <span class=\"ar\">الشَّىْءُ الظَّلِيلُ</span> <span class=\"ar\">حَقَّ الظَّلِيلِ</span>; [so that the verse should be rendered <i>They are the shade in the heat,</i> the shady thing, <i>the extremely shady, and the most goodly, the most beautiful, thing at which one looks;</i> (see the phrase <span class=\"ar\">هٰذَا العَالِمُ حَقَّ العَالِمِ</span>, voce <span class=\"ar\">حَقٌّ</span>;)] the inf. n. being put in the place of the subst. (M.) <span class=\"ar\">لَا ظَلِيلٍ</span> in the Kur [lxxvii. 31] means <i>Not profitable as the shade in protecting from the heat.</i> (TA.)</p><p><b class=\"ar\">ظَلَالَةٌ</b> , (M, TA,) with fet-h, (TA,) the subst. from the verb in the phrase <span class=\"ar\">ظَلَّلْنَا عَلَيْهِمُ الغَمَامَ</span> [expl. above, see 2; as such app. meaning either The <i>making to give shade,</i> like the inf. n. <span class=\"ar\">تَظْلِيلٌ</span>, or <i>a thing that gives shade,</i> like <span class=\"ar\">ظِلَالَةٌ</span>]. (M, TA.) -b2- And <i>i. q.</i> <span class=\"ar\">شَخْصٌ</span> [expl. above, see <span class=\"ar\">ظِلٌّ</span>, last quarter]: (O, K:) and so <span class=\"ar\">طَلَالَةٌ</span>, with <span class=\"ar\">ط</span>. (O.)</p><p><b class=\"ar\">ظِلَالَةٌ</b> : see <span class=\"ar\">ظُلَّةٌ</span>. -b2- Also <i>A cloud that one sees by itself, and of which one sees the shadow upon the earth.</i> (K.) -b3- And one says, <span class=\"ar\">رَأَيْتُ ظِلَالَةً</span> <span class=\"ar\">مِنَ الطَّيْرِ</span> i. e. <span class=\"ar\">غَيَابَةً</span> [app. meaning <i>I saw a covert,</i> or <i>place of concealment, of birds</i>]. (TA.)</p><p><b class=\"ar\">ظَلِيلَةٌ</b> <i>A place in which a little water collects and stagnates in a water-course</i> and <i>the like:</i> (Lth, T:) or <i>a place in which water collects and stagnates in the lower part of the torrent of a valley:</i> (M, K:) or the <i>like of an excavated hollow in the interior of a water-course, such that the water stops, and remains therein:</i> (AA, O:) pl. <span class=\"ar\">ظَلَائِلُ</span>. (Lth, AA, T, O.) And <i>A meadow</i> (<span class=\"ar\">رَوْضَة</span>) <i>abounding with collections of trees,</i> or <i>of dense and tangled trees:</i> (AA, T, O, K:) pl. as above. (K.)</p><p><b class=\"ar\">ظُلَّيْلَةٌ</b> <i>A thing which a man makes for himself,</i> <i>of trees,</i> or <i>of a garment,</i> or <i>piece of cloth, by which to protect himself from the heat of the sun:</i> a vulgar word. (TA.)</p><p><b class=\"ar\">ظُلْظُلٌ</b> <i>i. q.</i> <span class=\"ar\">سُعْنٌ</span>, i. e. <i>A</i> <span class=\"ar\"> <span class=\"ar\">مِظَلَّة</span></span> [q. v.; or as expl. in the L, in art. <span class=\"ar\">سعن</span>, <i>a</i> <span class=\"ar\">ظُلَّة</span> (q. v.), or <i>a thing like the</i> <span class=\"ar\">ظُلَّة</span>, <i>which is made upon the flat house-tops, for the purpose of guarding against the dew that comes from the direction of the sea in the time of the greatest heat</i>]; on the authority of IAar. (T. [Accord. to the O and K, <i>i. q.</i> <span class=\"ar\">سُفُنٌ</span>, which is evidently a mistranscription.])</p><p><b class=\"ar\">أَظَلُّ</b> [<i>More,</i> and <i>most, dense in shade</i>]. The Arabs say, <span class=\"ar\">لَيْسَ شَىْءٌ أَظَلَّ مِنْ حَجَرٍ</span> [<i>There is not anything more dense in shade than a stone</i>]. (TA.) -b2- And <span class=\"ar\">أَظَلّ</span>, [as a subst., i. e. <span class=\"ar\">أَظَلٌّ</span> accord. to a general rule, or, if regarded as originally an epithet, it may be <span class=\"ar\">أَظَلُّ</span>,] by poetic license <span class=\"ar\">أَظْلَل</span>, (S, M, O, K,) signifies The <i>under part,</i> (S, O,) or the <i>concealed part,</i> (M, AHei, K,) <i>of the</i> <span class=\"ar\">مَنْسِم</span>, (S, M, O, K,) or <i>of the</i> <span class=\"ar\">خُفّ</span>, (AHei, TA,) [the former app. here used, as it is said be in other cases, in the same sense as the latter, meaning the <i>foot,</i>] of the camel; (S, M, O, AHei, K;) so called because of its being concealed: (AHei, TA:) and, (M, K,) in a human being, (M,) <span class=\"ar\">الأَظَلُّ</span> signifies <span class=\"ar\">بَطْنُ الإِصْبَعِ</span>; (M, K;) and [ISd says] this is in my opinion the right explanation; but it is said that <span class=\"ar\">أَظَلُّ</span> <span class=\"ar\">الإِنْسَانِ</span> signifies <span class=\"ar\">بُطُونُ أَصَابِعِهِ</span>, which means <i>the portion, of what is next to the fore part</i> [<i>of the bottom</i>] <i>of the foot, from the root of the great toe to the root of the little toe, of the human being:</i> (M:) the pl. is <span class=\"ar\">ظُلٌّ</span>, which is anomalous, (M, K,) or formed after the manner of the pl. of an epithet: (M:) or <span class=\"ar\">الظُّلُّ فِى الإِنْسَانِ</span> means <i>the roots,</i> or <i>bases,</i> (<span class=\"ar\">أُصُول</span>) <i>of what are termed</i> <span class=\"ar\">بُطُونُ</span> <span class=\"ar\">الأَصَابِعِ</span>, <i>next to the fore part</i> [<i>of the bottom</i>] <i>of the foot.</i> (Ibn-'Abbád, O.) Hence the prov., <span class=\"ar\">إِنْ يَدْمَ أَظَلُّكَ فَقَدْ نَقِبَ خُفِّى</span> [<i>If the fore part of the sole of thy foot be bleeding, the sole of my foot has become worn through, in holes:</i> see <span class=\"ar\">نَقِبَ</span>]: said to the complainer to him who is in a worse condition than he. (AHei, TA.)</p><p><b class=\"ar\">مظلّ</b> [app. <span class=\"ar\">مَظِلٌّ</span>, being from <span class=\"ar\">ظَلَّ</span> of which the aor. is <span class=\"ar\">يَظِلُّ</span>; <i>A place of shade,</i> or <i>of continual shade</i>]. One says, <span class=\"ar\">هٰذَا مُنَاخِى وَمَحَلِّى وَبَيْتِى وَمظلِّى</span> [<i>This is my nightly resting-place for the camels, and my place of abode, and my tent, and my place of shade,</i> or <i>of continual shade</i>]. (TA.)</p><p><b class=\"ar\">مُظِلٌّ</b> A thing <i>having shade; by means of which one shades himself;</i> as also <span class=\"ar\"> <span class=\"ar\">مُظَلِّلٌ</span></span>. (Msb.) And [A <i>cloudy</i> day;] a day <i>having clouds:</i> or <i>having continual shade.</i> (TA.)</p><p><b class=\"ar\">مِظَلَّةٌ</b> (T, S, M, Msb, K) and <span class=\"ar\">مَظَلَّةٌ</span>, (T, M, Msb, K,) the former with kesr to the <span class=\"ar\">م</span> as an instrumental noun, (Msb,) [and the latter with fet-h as a noun of place,] <i>A large tent of</i> [<i>goats'</i>] <i>hair;</i> (S, O, Msb;) <i>more ample than the</i> <span class=\"ar\">خِبَآء</span>; so says El-Fárábee: (Msb:) <i>one of the kinds of tents of the Arabs of the desert, the largest of the tents of</i> [<i>goats'</i>] <i>hair;</i> next after which is the <span class=\"ar\">وَسُوط</span>; and then, the <span class=\"ar\">خِبَآء</span>, which is the smallest of the tents of [goats'] hair; so says AZ: but Aboo-Málik says that the <span class=\"ar\">مظلّة</span> and the <span class=\"ar\">خبآء</span> are <i>small</i> and <i>large:</i> IAar says that the <span class=\"ar\">خَيْمَة</span> is of poles roofed with [the panic grass called] <span class=\"ar\">ثَمَام</span>, and is not of cloths; but the <span class=\"ar\">مظلّة</span> is <i>of cloths:</i> (T:) or it is <i>of the tents called</i> <span class=\"ar\">أَخْبِيَة</span>; (M;) <i>such as is large, of the</i> <span class=\"ar\">أَخْبِيَة</span>; (K;) and it is said to be <i>only of cloths;</i> and it is <i>large, having a</i> <span class=\"ar\">رِوَاق</span> [q. v.]; but <i>sometimes it is of one oblong piece of cloth</i> (<span class=\"ar\">شُقَّة</span>), and <i>of two such pieces,</i> and <i>of three; and sometimes it has a</i> <span class=\"ar\">كِفَآء</span>, <i>which is its hinder part:</i> or, accord. to Th, <i>it is peculiarly of</i> [<i>goats'</i>] <i>hair:</i> (M:) see also <span class=\"ar\">ظُلَّةٌ</span>, and <span class=\"ar\">ظُلْظُلٌ</span>: the pl. is <span class=\"ar\">مَظَالُّ</span>; (M, Msb;) and <span class=\"ar\">مَظَالِ</span> or <span class=\"ar\">مَظَالِى</span> occurs at the end of a verse of Umeiyeh Ibn-Abee-'Áïdh El-Hudhalee, for <span class=\"ar\">مَظَالِّ</span>; the [latter] <span class=\"ar\">ل</span> being either elided, or changed into <span class=\"ar\">ى</span>. (M.) <span class=\"ar\"> <span class=\"ar\">ظُلَّةٌ</span>عِلَّةٌ مَا عِلَّةُ أَوْتَادٍ وَأَخِلَّةٍ وَعَمَدِ المِظَلَّةِ اُبْرُزُوا لِصِهْرِكُمْ</span> [<i>A pretext: what is the pretext of tentpegs, and of pins for fastening together the edges of the pieces of the tent-cloth, and of the poles of the large tent? go ye forth: he who has married among you has a tent for shade from the sun:</i>] is a prov., and was said by a girl who had been married to a man, and whose family delayed to conduct her to her husband, urging in excuse that they had not the apparatus of the tent: she said this to urge them, and to put a stop to their excuse: (Meyd, TA: *) and the prov. is applied in attributing untruth to pretexts. (Meyd.) -b2- Hence, as being likened thereto, (assumed tropical:) <i>A booth,</i> or <i>shed, made of palm-sticks, and covered with</i> [<i>the panic grass called</i>] <span class=\"ar\">ثُمَام</span>. (Msb.) -b3- And The <i>thing</i> [i. e. <i>umbrella</i>] <i>by means of which kings are shaded on the occasion of their riding;</i> called in Pers. <span class=\"ar\">چَتْر</span>. (TA.)</p><p><b class=\"ar\">عَرْشٌ مُظَلَّلٌ</b> [<i>A booth,</i> or <i>shed, shaded over</i>] is from <span class=\"ar\">الظِّلُّ</span>. (S.)</p><p><b class=\"ar\">مُظَلِّلٌ</b> : see <span class=\"ar\">مُظِلٌّ</span>.</p><p><b class=\"ar\">مُسْتَظِلٌّ</b> Blood <i>that is in the</i> <span class=\"ar\">جَوْف</span> [or <i>belly,</i> or <i>interior of the belly,</i> or the <i>chest</i>]. (T, O.) -b2- And [Az says,] I heard a man of the tribe of Teiyi apply the term <span class=\"ar\">المُسْتَظِلَّاتُ</span> [so accord. to a copy of the T, but in the TA <span class=\"ar\">المُسْتَظِلُّ</span>,] to <i>Certain thin flesh, adhering to the interior of the two fetlock-joints of the camel, than which there is in the flesh of the camel none thinner, nor any softer, but there is in it no grease.</i> (T.)</p>"},"ظفر":{"mf":"الظُّفْرُ يقال في الإنسان وفي غيره، قال تعالى: وَعَلَى الَّذِينَ هادُوا حَرَّمْنا كُلَّ ذِي ظُفُرٍ<br>[الأنعام/ ١٤٦]، أي: ذي مخالب، ويعبّر عن السّلاح به تشبيها بِظُفُرِ الطائرِ، إذ هو له بمنزلة السّلاح، ويقال: فلان كَلِيلُ الظُّفُرِ، وظَفَرَهُ فلانٌ: نشب ظُفُرَهُ فيه، وهو أَظْفَرُ: طويلُ الظُّفُرِ، والظَّفَرَةُ <strong>«١»</strong> : جُلَيْدَةٌ يُغَشَّى البصرُ بها تشبيها بِالظُّفُرِ في الصّلابة، يقال: ظَفِرَتْ عينُهُ، والظَّفَرُ: الفوزُ، وأصله من: ظَفِرَ عليه. أي:<br>نشب ظُفْرُهُ فيه. قال تعالى: مِنْ بَعْدِ أَنْ أَظْفَرَكُمْ عَلَيْهِمْ<br>[الفتح/ ٢٤].","mq":[["يدل احدهما علي القهر والفوز والغلبة","علي قوة في الشي"],"الظاء والفاء والراء أصلانِ صحيحان، يدلُّ أحدُهما على القَهر والفَوز والغَلَبَة، والآخر على قُوَّةٍ فى الشئ. ولعلَّ الأصلينِ يتقاربان فى القياس.<br>فالأوّل الظَّفَر، وهو الفَلْج والفَوْز بالشَّئ. يقال ظَفِر يَظْفَر ظفَراً. واللّه تعالى أَظفَرَه. وقال تعالى: ﴿مِنْ بَعْدِ أَنْ أَظْفَرَكُمْ عَلَيْهِمْ﴾. ور"],"ln":"<p><b>1.</b> <b class=\"ar\">ظَفَرَهُ</b> : see 2. -A2- [See also <span class=\"ar\">ظَفَرٌ</span>. -b2- ] <span class=\"ar\">ظَفِرَتْ</span> <span class=\"ar\">عَيْنُهُ</span>, (T, S, O, K,) aor. <b class=\"ar\">ظَفَرَ</b> , inf. n. <span class=\"ar\">ظَفَرٌ</span> (S, O) and <span class=\"ar\">ظَفَارَةٌ</span>; (O;) and, as some say, <span class=\"ar\">ظُفِرَت</span>; (T;) <i>His eye had what is termed a</i> <span class=\"ar\">ظَفَرَة</span> or <span class=\"ar\">ظُفْر</span>. (T, S, O, K.) -b3- And <span class=\"ar\">ظُفِرَ</span> <i>He</i> (a man) <i>had upon his eye what is termed a</i> <span class=\"ar\">ظَفَرَة</span> or <span class=\"ar\">ظُفْر</span>. (T, O, K.) -A3- <span class=\"ar\">ظَفِرَ</span>, aor. <b class=\"ar\">ظَفَرَ</b> , (Msb,) inf. n. <span class=\"ar\">ظَفَرٌ</span>, <i>He attained, got, got possession of,</i> or <i>acquired, what he desired,</i> or <i>sough:</i> (Lth, * S, * M, * A, * Msb, K: *) he <i>succeeded,</i> or <i>was successful:</i> (Msb:) <i>he won, was victorious,</i> or <i>gained the victory:</i> (Lth, T:) and <span class=\"ar\"> <span class=\"ar\">اِظَّفَرَ</span></span> [originally <span class=\"ar\">اِظْتَفَرَ</span>] signifies the same as <span class=\"ar\">ظَفِرَ</span>. (S.) You say, <span class=\"ar\">ظَفِرَ بِهِ</span> and <span class=\"ar\">عَلَيْهِ</span>, and <span class=\"ar\">ظَفِرَهُ</span>, <i>He attained it, got it, got possession of it,</i> or <i>acquired it;</i> (M, K;) and in like manner <span class=\"ar\"> <span class=\"ar\">اِظَّفَرَ</span></span>, of the measure <span class=\"ar\">اِفْتَعَلَ</span>. (K.) And <span class=\"ar\">ظَفِرْتُ بِالضَّالَّةِ</span> <i>I found the stray,</i> or <i>lost beast.</i> (Msb.) And <span class=\"ar\">ظَفِرَ بِعَدُوِّهِ</span> (S, A, Msb) and <span class=\"ar\">عَلَيْهِ</span>, (Akh, S, A,) and <span class=\"ar\">ظَفِرَهُ</span>, (S,) <i>He gained the victory,</i> or <i>mastery, over his enemy; he overcame him.</i> (S, * A, Msb. *) -b2- [Hence,] <span class=\"ar\">ظَفِرَتِ النَّاقَةُ لَقَحًا</span> (tropical:) <i>The she-camel took,</i> or <i>received, impregnation.</i> (A, TA.) And <span class=\"ar\">مَا ظَفِرَتْكَ عَيْنِى</span> (AZ, T, S, A, K) <span class=\"ar\">مُنْذُ حِينٍ</span> (AZ, T) or <span class=\"ar\">مُنْذُ زَمَانٍِ</span> (S, A) (tropical:) <i>My eye hath not seen thee</i> [<i>for some time</i>]: (AZ, T, S, A, K:) like <span class=\"ar\">مَا أَخَذَتْكَ</span>. (AZ, T.) -A4- [<span class=\"ar\">ظَفَرَ</span> in the dial. of Himyer is said by Freytag, on the authority of the Kitáb el-Addád, to signify <i>He sat.</i>]</p><p><b>2.</b> <b class=\"ar\">ظفّر فِيهِ</b> , (A, K,) inf. n. <span class=\"ar\">تَظْفِيرٌ</span>, (S,) <i>He inserted his nail into it;</i> (S, A, K;) namely, an apple, and the like, (S, K,) a cucumber, and a melon: (A:) and [in like manner] <span class=\"ar\"> <span class=\"ar\">اِظَّفَرَ</span></span>, of the measure <span class=\"ar\">اِفْتَعَلَ</span>, <i>he stuck,</i> or <i>fixed, his nail</i> [into a thing]; (S, K, TA;) and so <span class=\"ar\">اِطَّفَرَ</span>, with the unpointed <span class=\"ar\">ط</span>. (TA.) You say, <span class=\"ar\">ظفّر فُلَانٌ فِى وَجْهِ</span> <span class=\"ar\">فُلَانٍ</span> <i>Such a one stuck his nail into the flesh of the face of such a one, and wounded it.</i> (TA.) And <span class=\"ar\">نَيَّبَ فِى لَحْمِهِ وَظَفَّرَ</span> <i>He stuck his dog-tooth and his nail into his flesh, and wounded it.</i> (A.) And <span class=\"ar\">ظفّر فُلَانٌ فِى كَذَا وَنَيَّبَ</span> (tropical:) <i>Such a one clung to, caught to,</i> or <i>took fast hold upon, such a thing.</i> (A in art. <span class=\"ar\">نيب</span>.) Also <span class=\"ar\">ظفّرهُ</span>; and <span class=\"ar\"> <span class=\"ar\">ظَفَرَهُ</span></span>, aor. <b class=\"ar\">ظَفِرَ</b> ; (M, K;) and <span class=\"ar\"> <span class=\"ar\">اِظَّفَرَهُ</span></span>, in the K erroneously written <span class=\"ar\">أَظْفَرَهُ</span>; (TA;) <i>He stuck his nail into his face;</i> (M, K;) and so <span class=\"ar\">اِطَّفَرَهُ</span>, with <span class=\"ar\">ط</span>. (TA.) And <span class=\"ar\">ظفّرهُ</span> [<i>He clawed it;</i>] <i>he stuck his nail into it,</i> (namely, anything,) <i>and broke it,</i> or <i>made a mark</i> [or <i>scratch</i>] <i>upon it.</i> (M.) And <span class=\"ar\"> <span class=\"ar\">اِظَّفَرَ</span> الصَّقْرُ الطَّائِرَ</span> <i>The hawk seized the bird with his talons.</i> (K.) -b2- <span class=\"ar\">ظفّر</span> said of <span class=\"ar\">بَقْل</span> [or herbs, or leguminous plants,] (tropical:) <i>They put forth what resembled the</i> <span class=\"ar\">أَظْفَار</span> [or <i>talons</i>] <i>of the bird.</i> (M, TA.) And said of the <span class=\"ar\">عَرْفَج</span>, (K, TA,) and of the <span class=\"ar\">أَرْطَى</span>, (TA,) (tropical:) <i>It put forth what resembled</i> <span class=\"ar\">أَظْفَار</span>, (K, TA,) <i>when it put forth its</i> [<i>leaves termed</i>] <span class=\"ar\">خُوص</span>. (TA.) And said of the <span class=\"ar\">نَصِىّ</span>, and of the <span class=\"ar\">وَشِيج</span>, and of the <span class=\"ar\">بَرْدِىّ</span>, and of the <span class=\"ar\">ثُمَام</span>, and of the <span class=\"ar\">صِلِّيَان</span>, and of the <span class=\"ar\">غَرَز</span>, and of <span class=\"ar\">هَدَب</span>, (tropical:) <i>It,</i> or <i>they, put forth yellow shoots, resembling the</i> <span class=\"ar\">ظُفُر</span> [or <i>talon</i>], <i>which are the</i> <span class=\"ar\">خُوص</span> <i>thereof, that come forth therefrom having a dustcoloured flower.</i> (M, TA.) [Or,] said of a plant, (Ks, T, S,) inf. n. as above, (Ks, T,) (assumed tropical:) <i>It came forth;</i> (Ks, T;) from <span class=\"ar\">الأَظْفَار</span>: (T:) or <i>it came forth of the measure of the</i> <span class=\"ar\">ظُفْر</span> [or <i>nail</i>]. (S.) And <span class=\"ar\">ظفّرت الأَرْضُ</span> (assumed tropical:) <i>The land put forth plants,</i> or <i>herbage, that might be uprooted</i> (<span class=\"ar\">يُمْكِنُ</span> <span class=\"ar\">ٱحْتِفَاؤُهُ</span>, so in the M, in the K <span class=\"ar\">ٱحْتِفَارُهُ</span>,) <i>with the nail,</i> (M,) or <i>with the fingers.</i> (K.) -b3- <span class=\"ar\">ظفّر</span> <span class=\"ar\">ثَوْبَهُ</span>, (M, and so in a copy of the K,) inf. n. as above, (K,) (assumed tropical:) <i>He perfumed his garment</i> (M, and thus in that copy of the K) <i>with what is termed</i> <span class=\"ar\">ظُفْر</span>: (M:) or <span class=\"ar\">ظفّر ثَوْبَهُ بِالأَظْفَارِ</span> <i>he perfumed his garment with what are termed</i> <span class=\"ar\">أَظْفَار</span>. (So accord. to other copies of the K.) -b4- And <span class=\"ar\">ظفّر الجِلْدَ</span>, (K,) or <span class=\"ar\">ظَفَّرْتُ الجِلْدَ</span>, (M,) (assumed tropical:) <i>He,</i> (K,) or <i>I,</i> (M,) <i>rubbed the skin in order that its</i> <span class=\"ar\">أَظْفَار</span> (M, K) which means its <i>creased parts</i> (M) <i>might become smooth.</i> (M, K.) -A2- <span class=\"ar\">ظفّرهُ</span> also signifies, and so <span class=\"ar\"> <span class=\"ar\">اظفرهُ</span></span>, [<i>He caused him to attain, get, get possession of,</i> or <i>acquire, what he desired,</i> or <i>sought: he caused him to succeed,</i> or <i>to be successful:</i> and] <i>He</i> (God) <i>caused him to be victorious, to gain the victory,</i> or <i>to overcome.</i> (A.) You say, <span class=\"ar\">ظفّرهُ بِهِ</span> (S, M) and <span class=\"ar\">عَلَيْهِ</span>, (M, TA,) inf. n. as above; (S;) and <span class=\"ar\"> <span class=\"ar\">اظفرهُ</span>به</span> (S, M, Msb) and <span class=\"ar\">عليه</span>; (M, Msb;) <i>He</i> (God, S, M, or a man, Msb) <i>caused him to gain the victory over him,</i> or <i>to overcome him,</i> (M, Msb,) namely, his enemy. (S, Msb.) -b2- And <span class=\"ar\">ظفّرهُ عَلَيْهِ</span> <i>He declared him to have overcome him:</i> said of one who has been asked which of two persons had overcome. (T.) -b3- And <span class=\"ar\">ظفّرهُ</span>, (M, K,) inf. n. as above, (K,) <i>He prayed for him that he might attain what he desired,</i> or <i>sought;</i> or <i>that he might be successful,</i> or <i>victorious.</i> (M, K.)</p><p><b>4.</b> <b class=\"ar\">أَظْفَرَ</b> see the next preceding paragraph, latter part, in two places.</p><p><b>6.</b> <b class=\"ar\">تظافروا عَلَيْهِ</b> and <b class=\"ar\">تضافروا</b> and <span class=\"ar\">تظاهروا</span> all signify the same; so says Ibn-Buzurj; (T, TA;) explaining the meaning to be, <i>They leagued together, and aided one another, against him;</i> i. e. <span class=\"ar\">عَلَى فُلَانٍ</span> [<i>against such a one</i>]: (TA in art. <span class=\"ar\">ضفر</span>:) the first of these has been said to be incorrect; but it is mentioned also by Sgh, as syn. with the third; and by Ibn-Málik, among words that are with <span class=\"ar\">ض</span> and with <span class=\"ar\">ظ</span>. (TA in the present art.)</p><p><b>8.</b> <b class=\"ar\">إِظْتَفَرَ</b> see 2, in three places: -A2- and see also 1, in two places.</p><p><b class=\"ar\">ظَفْرٌ</b> : see the next paragraph.</p><p><b class=\"ar\">ظُفْرٌ</b> (T, S, M, A, Msb, K, &amp;c.) and <span class=\"ar\"> <span class=\"ar\">ظُفُرٌ</span></span>, (Msb, K,) which latter is the most chaste form, and the form adopted by the seven readers in the Kur vi. 147, and the former is a contraction of this, [but is the most common form,] (Msb,) and <span class=\"ar\"> <span class=\"ar\">ظِفْرٌ</span></span>, which is extr., (M, Msb, K,) and disallowed by IDrd, (O,) and <span class=\"ar\"> <span class=\"ar\">ظِفِرٌ</span></span>, which is also extr., (Msb,) and <span class=\"ar\"> <span class=\"ar\">أُظْفُورٌ</span></span>, (T, M, A, Msb, K,) which is erroneously mentioned in the S as a pl. of <span class=\"ar\">ظُفْرٌ</span>, (Sgh, Msb, K,) by an anticipation of the pen; (Msb;) or, accord. to MF, it si said in most of the copies of the S, (but this is not the case,) <span class=\"ar\">ظُفْرٌ</span> has for its pl. <span class=\"ar\">أَظْفَارٌ</span>; and <span class=\"ar\">أُظْفُورٌ</span> [has for its pl.] <span class=\"ar\">أَظَافِيرُ</span>; (TA;) [and this, being the reading in most of the copies of the S seen by MF, is probably what J wrote;] <i>A certain wellknown thing;</i> (M;) [i. e. <i>a nail;</i> and <i>a talon,</i> or <i>claw;</i>] <i>pertaining to a human being,</i> (M, Ibn-Es-Seed, Msb, K,) and <i>to others;</i> (M, K;) <i>to the beasts and birds mentioned in the next following sentence,</i> [as well as to man,] accord. to the authorities there cited; (TA;) and <i>to every ruminant,</i> as syn. with <span class=\"ar\">ظِلْفٌ</span> [i. e. <i>a cloven hoof</i>]: (T and M in art. <span class=\"ar\">ظلف</span>:) or <i>to a beast,</i> or <i>bird, that does not prey;</i> [as well as to man;] that of such as preys being termed <span class=\"ar\">مِخْلَبٌ</span>: (M:) [and in the present day applied also to the <i>spur</i> of a cock:] it is of the masc. gender: (Lh, M, Msb:) the pl. (of <span class=\"ar\">ظُفْرٌ</span>, S, M, Msb, &amp;c.) is <span class=\"ar\">أَظْفَارٌ</span> (S, M, Msb, K, &amp;c.) and sometimes <span class=\"ar\">أَظْفُرٌ</span>, (Msb,) [both of which are pls. of pauc., but the former is used as a pl. of mult. also,]. and (of <span class=\"ar\">أُظْفُورٌ</span>, M, Msb, or of <span class=\"ar\">أَظْفَارٌ</span>, and therefore a pl. pl., M) <span class=\"ar\">أَظَافِيرُ</span>: (M, Msb, K:) that <span class=\"ar\"> <span class=\"ar\">أُظْفُورٌ</span></span> is a sing. [and not like <span class=\"ar\">أُبْقُورٌ</span> which is a quasi-pl. n.] is shown by the saying of a poet, <span class=\"ar\">مَا بَيْنَ لُقْمَتِهَا الأُولَى إِذَا ٱنْحَدَرَتْ</span> <span class=\"ar\">وَبَيْنَ أُخْرَى تَلِيهَا قِيسُ أُظْفُورِ</span> (K) or <span class=\"ar\">قِيدُ أُظْفُورِ</span> (Msb) [i. e. <i>What is between her first morsel, when it descends</i> into her throat, <i>and another that follows it, is the measure of a finger-nail</i>]: or, as some relate it, <span class=\"ar\">إِذَا ٱزْدَرَدَتْ</span> [<i>when she swallows</i>]; and it is thus cited [in the T and] in the “ Basáïr ” of the author of the K. (TA.) The phrase <span class=\"ar\">كُلَّ ذِى ظُفُرٍ</span> in the Kur vi. 147 comprises camels and ostriches; (so in the T and TS and L; but in the K, <span class=\"ar\">الأَنْعَام</span> is erroneously put for <span class=\"ar\">النَّعَام</span>; TA;) because their <span class=\"ar\">مَنَاسِم</span> are like <span class=\"ar\">أَظْفَار</span> to them: (T, K, TA:) I'Ab says that it comprises camels; and also ostriches, because they have nails like camels: or any bird that has a <span class=\"ar\">مِخْلَب</span>, and any beast that has a solid hoof: or, accord. to Mujáhid and Katádeh, every beast and bird that has not divided toes; as the camel and ostrich and goose and duck. (TA.) -b2- [Hence,] <span class=\"ar\">الأَظْفَارُ</span> is the name of (assumed tropical:) <i>Certain small stars;</i> (S;) <i>certain stars before</i> <span class=\"ar\">النَّسْر</span> [meaning <span class=\"ar\">النَّسْر الوَاقِع</span> i. e. <i>the star a of Lyra:</i> app. because regarded as the talons of the <span class=\"ar\">نسر</span>]: (K:) or <i>a certain dim star in</i> <span class=\"ar\">الشَّلْيَاق</span> [q. v., i. e. <i>the constellation Lyra</i>]. (Kzw.) -b3- [Hence also,] <span class=\"ar\">إِنَّهُ لَكَلِيلُ الظُّفْرِ</span>, (T,) or <span class=\"ar\">إِنَّهُ لَمَقْلُومُ الظُّفْرِ</span>, (TA,) (tropical:) <i>Verily he is one who does not slay</i> or <i>wound an enemy:</i> (T, TA:) and <span class=\"ar\">إِنَّهُ مَقْلُومُ الظُّفْرِ عَنْ أَذَى</span> <span class=\"ar\">النَّاسِ</span> (tropical:) <i>Verily he is one who does little hurt to mankind.</i> (T, A, TA.) And <span class=\"ar\">هُوَ كَلِيلُ الظُّفْرِ</span> (tropical:) <i>He is weak,</i> or <i>abject,</i> or <i>despicable;</i> (T, S, K, TA;) said of a man; (K, TA;) or so <span class=\"ar\">مُقَلَّمُ الظُّفْرِ</span>: (K: [in the TA, as from the K, <span class=\"ar\">مُقَلَّمُ الأَظْفَارِ</span>:]) or (tropical:) <i>he is sick,</i> or <i>diseased.</i> (A.) And <span class=\"ar\">بِهِ ظُفْرٌ مِنْ</span> <span class=\"ar\">مَرَضٍ</span> (tropical:) [app. meaning <i>In him is an evil result of a disease, that has clung to him</i>]. (A, TA. [In the A, this immediately follows what here next precedes it; and is immediately followed by the words <span class=\"ar\">وَذُبَابٌ ظَفِرَ مِنْهُ</span>, which seem to be added by way of explanation; thus in my copy; but I think that <span class=\"ar\">ظَفِرَ مِنْهُ</span> here is a mistake for <span class=\"ar\">ظَفَّرَ فِيهِ</span>, and have assumed this to be the case in rendering the phrase.]) -b4- And <span class=\"ar\">قَرَّحْتُهُ مِنْ ظُفْرِهِ إِلَى شُفْرِهِ</span> (tropical:) [lit. <i>I wounded him much, from his nail to the edge of his eyelid;</i> but mentioned as tropical; app. meaning <i>from toe to head</i>]; like as one says, <span class=\"ar\">مِنْ قَرْنِهِ</span>. (A.) -b5- And <span class=\"ar\">مَا بَالدَّارِ ظُفْرٌ</span>, (K,) or <span class=\"ar\">ما بالدار ظُفْرٌ وَلَا شُفْرٌ</span>, (A, O,) (tropical:) <i>There is not in the house any one.</i> (A, O, K.) And <span class=\"ar\">مَا تَرَكَتِ</span> <span class=\"ar\">السَّنَةُ ظُفْرًا وَلَا شُفْرًا</span> (tropical:) <i>The year of drought left not anything:</i> and sometimes they said <span class=\"ar\">شَفْرًا</span>, with fet-h, and in this case they said <span class=\"ar\"> <span class=\"ar\">ظَفْرًا</span></span>, for assimilation. (A in art. <span class=\"ar\">شفر</span>.) And <span class=\"ar\">رَأَيْتُهُ بِظُفْرِهِ</span> (tropical:) <i>I saw him himself.</i> (O, K, TA.) -b6- <span class=\"ar\">ظُفْرُ النَّسْرِ</span> is the name of (assumed tropical:) <i>A certain plant,</i> (K, TA,) <i>resembling what is</i> [<i>properly</i>] <i>thus termed</i> [i. e. <i>the talon of the vulture</i>]. (TA.) And <span class=\"ar\">ظُفْرُ القِطِّ</span> is the name of (assumed tropical:) <i>Another plant.</i> (K, TA.) -b7- And <span class=\"ar\">الظُّفْرُ</span>, (M,) or <span class=\"ar\">الأَظْفَارُ</span>, (T, M, A, Mgh, O, K, &amp;c.,) for this word in the sense here following has no sing. (T, M, O, K) accord. to the author of the 'Eyn, (M,) but sometimes one said <span class=\"ar\"> <span class=\"ar\">أَظْفَارَةٌ</span>وَاحِدَةٌ</span>, which is not allowable by rule, and made the pl. of this to be <span class=\"ar\">أَظَافِيرُ</span>, (T, O, K, * [mentioned in the M as a pl. of <span class=\"ar\">الظُّفْرُ</span>,]) though, if they formed a sing. from it, it should be <span class=\"ar\">ظُفْرٌ</span>, (T, O, K,) signifies (tropical:) <i>A certain odoriferous substance,</i> (T, Mgh, O, K,) or <i>a sort thereof,</i> (M,) [i. e. <i>unguis odoratus,</i> (called in the present day <span class=\"ar\">ظُفْرُ الطِّيبِ</span> and <span class=\"ar\">ظُفْرُ العِفْرِيتِ</span>,) or <i>ungues odorati,</i>] <i>black,</i> (T, M, O,) <i>resembling a</i> <span class=\"ar\">ظُفْر</span> [or <i>nail</i>] (T, M, Mgh, O, K) <i>of a man</i> (M) <i>pulled out</i> (in the M and O and K <span class=\"ar\">مُقْتُلَف</span>, and in the T <span class=\"ar\">مُقَلَّف</span>,) <i>from the root thereof,</i> (T, M, O, K, [but in the M, the words which I have rendered “ pulled out ” &amp;c. immediately follow the words <span class=\"ar\">ضَرْبٌ مِنَ العِطْرِ</span> <span class=\"ar\">أَسْوَدُ</span>,]) or <i>resembling the</i> <span class=\"ar\">أَظْفَار</span> [or <i>finger-nails</i>], (A,) <i>and put into</i> <span class=\"ar\">دُخْتَة</span> [or <i>incense</i>]: (T, M, O:) and, accord. to the K, <span class=\"ar\"> <span class=\"ar\">ظَفَارٌ</span></span>, sometimes imperfectly decl., i. e. <span class=\"ar\"> <span class=\"ar\">ظَفَارُ</span></span>, signifies the same; but this is very strange, for [SM says] I have referred to the M and T and O and other lexicons without finding them to have mentioned in this sense any term but <span class=\"ar\">الأَظْفَارُ</span> or <span class=\"ar\">الظُّفْرُ</span>: accord. to the “ Minháj, ” <span class=\"ar\">أَظْفَارُ الطِّيبِ</span> are <i>pieces of an odoriferous substance resembling the</i> <span class=\"ar\">أَظْفَار</span> [properly so called]; they are said by [the Arabic translator of] Dioscorides to be <i>of the nature of the shards of shells,</i> [so I render <span class=\"ar\">مِنْ جِنْسِ أَخْزَافِ الصَّدَفِ</span>, supposing <span class=\"ar\">اخزاف</span> to be here used tropically,] <i>found in an island of the Sea of India where is the</i> <span class=\"ar\">سُنْبُل</span> [or <i>spikenard</i>], <i>a sort whereof is</i> [<i>called</i>] <span class=\"ar\">قُلْزُمِىّ</span> [i. e. <i>of El-Kulzum</i>], <i>and another which is</i> [<i>called</i>] <span class=\"ar\">بَابِلِىّ</span> [i. e. <i>of Bábil</i>], <i>black and small, and the best is that which inclines to whiteness, which drifts to El-Yemen and El-Bahreyn.</i> (TA.) [Forskål, in his “ Descr. Animalium ” &amp;c., mentions what here follows, among the animal substances of the materia medica of Cairo, in page 143: “ <i>Unguis odoratus.</i> (Opercula Cochl.) <i>Dofr el afrît,</i> <span class=\"ar\">ضفر العفريت</span> i. e. <i>unguis dæmonis.</i> E Mochha per Sués. Arabes etiam afferunt. Nigritis fumigatorium est. ” (<span class=\"ar\">ضفر</span> is here written, agreeably with the usual vulgar pronunciation, for <span class=\"ar\">ظُفْر</span>.) See also <span class=\"ar\">قُسْطٌ</span>,] -b8- <span class=\"ar\">أَظْفَارٌ</span> signifies also (assumed tropical:) <i>Large</i> <span class=\"ar\">قِرْدَان</span> [or <i>ticks</i>]. (S, O, K.) -b9- And (assumed tropical:) The <i>creased parts</i> of a skin. (M, TA.) -b10- And the <span class=\"ar\">ظُفْر</span> of a bow is (tropical:) The <i>part</i> in the curved end <i>that is beyond the place where the string is tied, to the extremity:</i> (As, T, S, M, * O, K: *) or the <i>end</i> of the bow: (K:) or <i>each end</i> of the bow, <i>beyond the place where the string is tied:</i> (A:) pl. <span class=\"ar\">ظِفَرَةٌ</span>. (M, TA.) -b11- See also <span class=\"ar\">ظَفَرَةٌ</span>.</p><p><b class=\"ar\">ظِفْرٌ</b> : see the next preceding paragraph.</p><p><b class=\"ar\">ظَفَرٌ</b> , in a man, The <i>quality of having long nails.</i> (ISk, S, O.) [App., in this sense, an inf. n. of which the verb is <span class=\"ar\">ظَفِرَ</span>; as it is in other senses: see 1.] -A2- See also <span class=\"ar\">ظَفَرَةٌ</span>. -A3- Also <i>Low,</i> or <i>depressed, ground,</i> (S, O, K,) <i>that produces plants,</i> or <i>herbage.</i> (S, O.)</p><p><b class=\"ar\">ظَفِرٌ</b> <i>Sharp in the nail</i> [or <i>having sharp nails</i>]. (A.) -b2- And A man <i>having upon his eye what is termed a</i> <span class=\"ar\">ظَفَرَة</span>; (A;) and so <span class=\"ar\"> <span class=\"ar\">مَظْفُورٌ</span></span>. (T, A, Mgh, K.) -b3- And <span class=\"ar\">عَيْنٌ ظَفِرَةٌ</span> <i>An eye having what is termed a</i> <span class=\"ar\">ظَفَرَة</span>; (T, M, A, K;) as also <span class=\"ar\"> <span class=\"ar\">مَظْفُورَةٌ</span></span>. (A.) -A2- Also [<i>Successful;</i>] <i>victorious;</i> applied to a man; (S;) and so <span class=\"ar\"> <span class=\"ar\">ظَافِرٌ</span></span>: (Msb, TA:) or <span class=\"ar\">ظَفِرٌ</span> (IDrd, M, A, K) and <span class=\"ar\"> <span class=\"ar\">ظَفِيرٌ</span></span> (IDrd, M, K) and <span class=\"ar\"> <span class=\"ar\">ظِفِّيرٌ</span></span>, (IDrd, Sgh, K) but this is said by IDrd to be not of established authority, (TA,) and <span class=\"ar\"> <span class=\"ar\">مُظَفَّرٌ</span></span> (IDrd, M, A, K) and <span class=\"ar\"> <span class=\"ar\">مِظْفَارٌ</span></span>, (IDrd, O, K,) all signify a man <i>very,</i> or <i>often, successful</i> or <i>victorious:</i> (IDrd, O, TA:) or (tropical:) one <i>who does not endeavour after a thing without attaining it.</i> (M, A, K.)</p><p><b class=\"ar\">ظُفُرٌ</b> and <span class=\"ar\">ظِفِرٌ</span>: see <span class=\"ar\">ظُفْرٌ</span>.</p><p><b class=\"ar\">ظُفْرَةٌ</b> <i>A certain plant, burning,</i> or <i>biting, to the tongue,</i> (K, TA,) <i>resembling the</i> <span class=\"ar\">ظُفْر</span> [or <i>nail</i>] <i>in its coming forth,</i> (TA,) <i>that has a beneficial effect upon foul ulcers, and warts.</i> (K, TA.) -b2- And <span class=\"ar\">ظُفْرَةُ العَجُوزِ</span> <i>The rounded head of prickles of the</i> [<i>thistle called</i>] <span class=\"ar\">حَسَك</span>. (K, * TA.) -b3- See also the next paragraph.</p><p><b class=\"ar\">ظَفَرَةٌ</b> <i>A pellicle that comes over the eye,</i> (T, S, Mgh, O, K,) <i>growing from the side next the nose,</i> (T, S, O,) <i>upon the white of the eye,</i> (S, Mgh, O,) <i>extending to the black:</i> (S, O:) sometimes it is cut off: if left, it covers the eye, and obscures the sight: (T:) or <i>a certain disease in the eye, which causes a tegument like the nail to come over it:</i> or <i>a piece of flesh that grows at the inner angle of the eye, extending to the black, and sometimes encroaching upon the black:</i> (M:) it is also called <span class=\"ar\"> <span class=\"ar\">ظُفْرٌ</span></span> (A 'Obeyd, T, S, M, Mgh, O, K) and <span class=\"ar\"> <span class=\"ar\">ظُفْرَةٌ</span></span>, (T, Mgh,) these two terms being applied to it by the physicians, (Mgh,) and <span class=\"ar\"> <span class=\"ar\">ظَفَرٌ</span></span> (TA) and <span class=\"ar\"> <span class=\"ar\">ظِفَارَةٌ</span></span>, (so in a copy of the T, as on the authority of Ibn-Buzurj,) or <span class=\"ar\"> <span class=\"ar\">ظَفَارَةٌ</span></span>. (So in the O.)</p><p><b class=\"ar\">ظَفَارٌ</b> and <span class=\"ar\">ظَفَارُ</span>: see <span class=\"ar\">ظُفْرٌ</span>. -A2- [<span class=\"ar\">ظَفَارِ</span> is well known as the name of a city in El-Yemen; or, accord. to the O, of two cities and two fortresses in El-Yemen. And accord. to the TA, it signifies <i>Any land that is</i> <span class=\"ar\">ذات مَعَزَّة</span>: but the latter of these two words has been altered by an erasure over the second letter, and is perhaps incorrect: if not, it may mean, agreeably with the analogy of many words of the measure <span class=\"ar\">مَفْعَلَةٌ</span>, as <span class=\"ar\">مَقْدَرَةٌ</span> and <span class=\"ar\">مَفْلَحَةٌ</span> and <span class=\"ar\">مَنْجَاةٌ</span> &amp;c., <i>such as possesses means of overcoming,</i> or <i>withstanding, invaders:</i> and it may be that hence <span class=\"ar\">ظَفَارِ</span> is in two instances the name of a fortress.]</p><p><b class=\"ar\">ظَفُورٌ</b> [app. syn. with <span class=\"ar\">ظَفِرٌ</span> and <span class=\"ar\">ظَفِيرٌ</span>] is one of the appellations of the Prophet. (MF, TA.)</p><p><b class=\"ar\">ظَفِيرٌ</b> : see <span class=\"ar\">ظَفِرٌ</span>.</p><p><b class=\"ar\">ظَفَارَةٌ</b> or <span class=\"ar\">ظِفَارَةٌ</span>: see <span class=\"ar\">ظَفَرَةٌ</span>.</p><p><b class=\"ar\">جَزْعٌ ظَفَارِىٌّ</b> [<i>onyx of Dhafári</i>] is so called in relation to <span class=\"ar\">ظَفَارِ</span>, a city of El-Yemen, (T, S, Mgh, O, K,) near <span class=\"ar\">صَنْعَآء</span>, (K,) two days' journey from the latter. (O.) And in like manner, <span class=\"ar\">عُودٌ ظَفَارِىٌّ</span> [<i>Aloes-wood of Dhafári</i>]: i. e. the <span class=\"ar\">عود</span> <i>with which one fumigates:</i> (S:) or <span class=\"ar\">قُسْط</span>, (O, K, TA,) which means the same, (TA, [but see this word,]) is called [<span class=\"ar\">قُسْطُ ظَفَارِ</span> and <span class=\"ar\">قُسْطٌ ظَفَارِىٌّ</span>] in relation to <span class=\"ar\">ظَفَارِ</span>, another city of El-Yemen, near <span class=\"ar\">مِرْبَاط</span>, (O, K, TA,) described by Yákoot as in the furthest part of El-Yemen, on the shore of the Sea of India, near <span class=\"ar\">الشَّحْر</span>; (TA;) because it is brought thither from India. (O, K, TA.)</p><p><b class=\"ar\">ظِفِّيرٌ</b> : see <span class=\"ar\">ظَفِرٌ</span>.</p><p><b class=\"ar\">ظَافِرٌ</b> : see <span class=\"ar\">ظَفِرٌ</span>.</p><p><b class=\"ar\">أَظْفَرُ</b> A man <i>having long nails:</i> (ISk, S, A:) or <i>having long and broad nails:</i> (M, K:) and in like manner applied to a <span class=\"ar\">مَنْسِم</span> [or foot of a camel]: <span class=\"ar\">ظَفْرَآءُ</span> [the reg. fem.] has not been heard. (M.)</p><p><b class=\"ar\">أُظْفُورٌ</b> : see <span class=\"ar\">ظُفْرٌ</span>, in two places. -b2- Also (assumed tropical:) The <i>slender thing</i> [or <i>tendril</i>] <i>that twines upon the branch of a grape-vine.</i> (K.)</p><p><b class=\"ar\">أَظْفَارَةٌ</b> : see <span class=\"ar\">ظُفْرٌ</span>, latter half.</p><p><b class=\"ar\">مُظَفَّرٌ</b> : see <span class=\"ar\">ظَفِرٌ</span>. -A2- <span class=\"ar\">قَوْسٌ مُظَفَّرَةٌ</span> (assumed tropical:) <i>A bow having somewhat cut off from each of its two ends</i> [which are called its <span class=\"ar\">ظُفْرَانِ</span>]. (O, K, TA. [In the CK, <span class=\"ar\">فَرَسٌ</span> is erroneously put for <span class=\"ar\">قَوْسٌ</span>.])</p><p><b class=\"ar\">مِظْفَارٌ</b> : see <span class=\"ar\">ظَفِرٌ</span>. -A2- Also The [<i>instrument called</i>] <span class=\"ar\">مِنْقَاش</span> [q. v.]. (Fr, O, K.)</p><p><b class=\"ar\">مَظْفُورٌ</b> ; and its fem.: see <span class=\"ar\">ظَفِرٌ</span>. -A2- <span class=\"ar\">مَظْفُورٌ بِهِ</span> <i>Overcome,</i> or <i>conquered;</i> [as also <span class=\"ar\">مَظْفُورٌ عَلَيْهِ</span>, and <span class=\"ar\">مَظْفُورٌ</span> alone; (see 1;)] applied to a man. (TA.)</p>"},"ظمأ":{"mf":"الظِّمْءُ: ما بين الشّربتين، والظَّمَأُ: العطش الذي يعرض من ذلك. يقال: ظَمِئَ يَظْمَأُ فهو ظَمْآَنُ. قال تعالى: لا تَظْمَؤُا فِيها وَلا تَضْحى<br>[طه/ ١١٩]، وقال: يَحْسَبُهُ الظَّمْآنُ ماءً حَتَّى إِذا جاءَهُ لَمْ يَجِدْهُ شَيْئاً<br>[النور/ ٣٩].","mq":[["ذبول وقلة ماء"],"الظاء والميم والحرف المعتل والمهموز أصلٌ واحد يدلُّ على ذبولٍ وقلّة ماءٍ. من ذلك: الظَّمَا، غير مهموز: قلّة دم اللِّثة. يقال امرأةٌ ظمياء اللَثاث. وعينٌ ظمياء: رقيقة الجَفن. ثم يحمل عليه فيقال ساقٌ ظمياء:<br>قليلة اللحم.<br>ومن المهموز: الظَّمَأ، وهو العطش، تقول: ظمنت أظمأ ظمَا. فأما الظِّمْ ء فما بين الش"],"ln":"<p><b>1.</b> <b class=\"ar\">ظَمِئَ</b> , (T, S, M, &amp;c.,) aor. <b class=\"ar\">ظَمَاَ</b> , (Msb, K,) inf. n. <span class=\"ar\">ظَمَأٌ</span> (T, S, M, Msb, K) and <span class=\"ar\">ظَمْءٌ</span> (TA) and <span class=\"ar\">ظَمَآءٌ</span> (T, M, K) and <span class=\"ar\">ظَمَآءَةٌ</span>, (M, K, TA,) in one copy of the K <span class=\"ar\">ظَمْأَة</span>, (TA,) <i>He thirsted,</i> or <i>was thirsty:</i> (S, M, Msb, K:) or as some say, <i>he thirsted in the slightest degree.</i> (M, TA.) -b2- Hence, (M,) <span class=\"ar\">ظَمِئَ إِلَى لِقَائِهِ</span> (tropical:) <i>He desired,</i> or <i>longed,</i> [or, as we often say, <i>thirsted,</i>] <i>to meet with him.</i> (S, M, K, * TA.)</p><p><b>2.</b> <b class=\"ar\">ظَمَّاَ</b> see the next paragraph.</p><p><b>4.</b> <b class=\"ar\">اظمأهُ</b> , (T, * S, Msb, K,) inf. n. <span class=\"ar\">إِظْمَآءٌ</span>; (T;) and <span class=\"ar\"> <span class=\"ar\">ظمّأهُ</span></span>, (T, * Msb, K,) inf. n. <span class=\"ar\">تَظْمِئَةٌ</span>; (T, S;) <i>He made him to thirst:</i> (S, Msb, K:) [or <i>to thirst most vehemently:</i> or <i>to thirst in the slightest degree:</i> see 1.] -b2- And (K) (tropical:) <i>He made him lean,</i> or <i>lank,</i> namely, a horse, (T, * K, TA,) <i>by sweating him.</i> (TA.) [See also 4 in art. <span class=\"ar\">ظمى</span>.]</p><p><b>5.</b> <b class=\"ar\">تظمّأ</b> <i>He constrained himself to endure with patience a state of thirst.</i> (A, TA.)</p><p><b class=\"ar\">ظِمْءٌ</b> a subst. from <span class=\"ar\">ظَمِئَ</span> (S, M, K) in both of its senses; (M, K;) [i. e.] it signifies <i>Thirst:</i> (MA:) [or <i>most vehement thirst:</i> or the <i>slightest degree of thirst:</i>] pl. <span class=\"ar\">أَظْمَآءٌ</span>. (MA.) -b2- [And (tropical:) <i>Desire,</i> or <i>a longing,</i> (or, as we often say, <i>a thirsting,</i>) to meet with a person. See 1.] -b3- And (S, M, K) The <i>time,</i> or <i>interval,</i> or <i>period, between two drinkings,</i> or <i>waterings,</i> (T, S, M, K,) <i>in the coming of camels to water:</i> (T:) and the <i>keeping of camels from the water</i> [<i>during that interval,</i> i. e.] <i>until the extreme limit of the coming thereto:</i> (S:) pl. <span class=\"ar\">أَظْمَآءٌ</span>. (T, S, M.) The shortest <span class=\"ar\">ظِمْءٌ</span> of camels is that termed <span class=\"ar\">غِبٌّ</span>, i. e., when they come to the water one day and return, and are in the place of pasture a day, and come to the water [again] on the third day; the interval between their two drinkings being termed a <span class=\"ar\">ظِمْء</span>: this is during the greatest heat: but when Suheyl [i. e. Canopus] rises [aurorally, which it did in Central Arabia, about the commencement of the era of the Flight, on the 4th of August, O. S.], they increase the <span class=\"ar\">ظِمْء</span>, so that the camels remain in the place of pasture two days, and come to the water on the fourth; and one says, <span class=\"ar\">وَرَدَتْ رِبْعًا</span>: then follow the <span class=\"ar\">خِمْس</span> and the <span class=\"ar\">سِدْس</span> to the <span class=\"ar\">عِشْر</span>: and the interval between their two drinkings is termed <span class=\"ar\">ظِمْءٌ</span>, whether long or short. (T.) One says, <span class=\"ar\">مَا بَقِىَ مِنْ عُمُرِهِ إِلَّا ظِمْءُ الحِمَارِ</span>, (T, S, * K, * TA,) meaning <i>There remained not of his life save a little;</i> [lit., <i>save the period between the two drinkings of the ass;</i>] (S, K, * TA;) because there is no beast that bears thirst for a shorter time than the ass; (T, S, * K, * TA;) for he comes to the water in summer every day twice. (T, TA.) -b4- <span class=\"ar\">الظِّمْءُ</span> also signifies (assumed tropical:) <i>The period from birth to death;</i> (K;) or so <span class=\"ar\">ظِمْءُ</span> <span class=\"ar\">الحَيَاةِ</span>. (S, M, TA.) -b5- <span class=\"ar\">ظِمْوٌ</span> is a dial. var. of <span class=\"ar\">ظِمْءٌ</span>. (T and M in art. <span class=\"ar\">ظمو</span>.)</p><p><b class=\"ar\">ظَمِئٌ</b> : see the next paragraph.</p><p><b class=\"ar\">ظَمْآنُ</b> , (T, S, M, Msb, &amp;c.,) fem. <span class=\"ar\">ظَمْأَى</span>, (T, S, M, A, L, Msb,) both imperfectly decl.; (T;) or <span class=\"ar\">ظَمْآنٌ</span>, fem. <span class=\"ar\">ظَمْآنَةٌ</span>; (K; [but this requires consideration, for its correctness is extremely doubtful;]) and <span class=\"ar\"> <span class=\"ar\">ظَمِئٌ</span></span>, (so in the K accord. to the TA, and so in my MS. copy of the K,) like <span class=\"ar\">كَتِفٌ</span>, [agreeably with analogy as part. n. of <span class=\"ar\">ظَمِئَ</span>, and therefore probably correct,] (TA,) or <span class=\"ar\"> <span class=\"ar\">ظَمِىْءٌ</span></span>, (so in a copy of the M and in the CK,) fem. [of the former] <span class=\"ar\">ظَمِئَةٌ</span>, like <span class=\"ar\">فَرِحَةٌ</span>, mentioned by Ibn-Málik, but generally held to be disused; (MF, TA;) and <span class=\"ar\">ظَامٍ</span>, like <span class=\"ar\">رَامٍ</span>; (TA; [app. for <span class=\"ar\"> <span class=\"ar\">ظَامِئٌ</span></span>;]) <i>Thirsty:</i> (S, M, Msb, K:) or <i>most vehemently thirsty:</i> (T, M, K:) or <i>thirsty in the slightest degree:</i> (M, TA:) pl. (of the first, M, Msb, and of the second, M, or of all, mase. and fem., TA) <span class=\"ar\">ظِمَآءٌ</span> (T, S, M, Msb, K) and <span class=\"ar\">ظُمَآءٌ</span>, which is extr., (K, TA,) being of a form applying to only about ten words, (TA,) mentioned on the authority of Lh, (K, TA,) by ISd in the “ Mukhassas. ” (TA.) -b2- [Hence,] one says, <span class=\"ar\">أَنَا ظَمْآنُ إِلَى لِقَائِكَ</span> (tropical:) <i>I am desirous,</i> or <i>longing,</i> [or, as we often say, <i>thirsting,</i>] <i>to meet with thee.</i> (A, TA.) -b3- And <span class=\"ar\">وَجْهٌ ظَمْآنُ</span> (tropical:) <i>A face having little flesh,</i> (T, TA,) <i>the skin of which adheres to the bone, and the sap of which is little:</i> (TA:) an expression of praise: <i>contr. of</i> <span class=\"ar\">وَجْهٌ</span> <span class=\"ar\">رَيَّانُ</span>, which is [said to be] an expression of dispraise. (A, TA.) And <span class=\"ar\">فَرَسٌ ظَمْآنُ الشَّوَى</span> (assumed tropical:) <i>A horse having little flesh upon the legs:</i> (T in art. <span class=\"ar\">روى</span>:) and so <span class=\"ar\">أَظْمَى الشَّوَى</span>. (T in art. <span class=\"ar\">ظمى</span>.) And <span class=\"ar\">سَاقٌ ظَمْأَى</span> (assumed tropical:) <i>A lean shank:</i> (T, TA:) and so <span class=\"ar\">ساق ظَمْيَآءُ</span>. (S and M and K in art. <span class=\"ar\">ظمى</span>.) And <span class=\"ar\">عَيْنٌ ظَمْأَى</span> (assumed tropical:) <i>An eye having a thin,</i> or <i>delicate, lid:</i> (M, TA:) and so <span class=\"ar\">عين ظَمْيَآءُ</span>. (S and M and K in art. <span class=\"ar\">ظمى</span>.) And <span class=\"ar\">فُصُوصُهُ ظِمَآءٌ</span> (said of a horse, T, S, TA) (tropical:) <i>His joints are</i> [<i>firm,</i>] <i>not flabby,</i> or <i>lax,</i> (T, S, K, TA,) <i>nor fleshy;</i> (S, K, TA;) <i>and are well braced;</i> an expression of commendation: (T:) and <span class=\"ar\">مَفَاصِلُ ظِمَآءٌ</span> (tropical:) <i>Hard</i> [or <i>firm</i>] <i>joints, without flabbiness,</i> or <i>laxness:</i> (A, TA:) accord, to IB, belonging to art. <span class=\"ar\">ظمى</span>; but said in the T to be originally from <span class=\"ar\">ظمأ</span>. (TA.) -b4- And <span class=\"ar\">رِيحٌ ظَمْأَى</span> (assumed tropical:) <i>A wind that is hot,</i> (As, T, K,) <i>thirsty, not gentle,</i> (K,) <i>and without moisture.</i> (As, T.)</p><p><b class=\"ar\">ظَمِىْءٌ</b> : see <span class=\"ar\">ظَمْآنُ</span>, first sentence.</p><p><b class=\"ar\">ظَمَآءَةٌ</b> (assumed tropical:) <i>Evilness of nature,</i> of a man, <i>and meanness of disposition, and deficiency of equity to associates:</i> (En-Nadr, T, K:) originating from the fact that he who is given to drink, if of an evil nature, does not act equitably to his associates. (T.)</p><p><b class=\"ar\">ظَامِئٌ</b> : see <span class=\"ar\">ظَمْآنُ</span>, first sentence.</p><p><b class=\"ar\">أَظْمَأُ</b> <i>Tawny;</i> applied to a spear: (A, TA:) and so <span class=\"ar\">أَظْمَى</span>. (TA in art. <span class=\"ar\">ظمى</span>.) -b2- And <i>Black;</i> applied to an antelope and to a camel: pl. <span class=\"ar\">ظُمْءٌ</span>. (A, TA.)</p><p><b class=\"ar\">مَظْمَأٌ</b> <i>A thirsty place of the earth</i> or <i>ground.</i> (M, K.)</p><p><b class=\"ar\">مِظْمَآءٌ</b> A <i>very thirsty</i> man. (K.)</p><p><b class=\"ar\">مِظْمَئِىٌّ</b> <i>Watered</i> [<i>only</i>] <i>by the rain: contr. of</i> <span class=\"ar\">مَسْقَوِىٌّ</span>: (K:) and so <span class=\"ar\">مَظْمِىٌّ</span>: applied to seedproduce. (S and K in art. <span class=\"ar\">ظمى</span>.)</p>"},"ظعن":{"mf":"يقال: ظَعَنَ يَظْعَنُ ظَعْناً: إذا شخص. قال تعالى: يَوْمَ ظَعْنِكُمْ<br>[النحل/ ٨٠]، والظَّعِينَةُ: الهودج إذا كان فيه المرأة، وقد يكنّى به عن المرأة وإن لم تكن في الهودج.","mq":[["الشخوص من مكان الي مكان"],"الظاء والعين والنون أصل واحد صحيح يدلُّ على الشخوص من مكانٍ إلى مكان. تقول: ظَعَنَ يظعَن ظعْناً وظَعَناً، إذا شَخَص. قال اللّه سبحانه: ﴿وَجَعَلَ لَكُمْ مِنْ جُلُودِ اَلْأَنْعامِ بُيُوتاً تَسْتَخِفُّونَها يَوْمَ ظَعْنِكُمْ وَيَوْمَ إِقامَتِكُمْ (١﴾. والظَّعينة، ممّا يقال فيه (٢) فقال قوم: هى المرأة،"],"ln":"<p><b>1.</b> <b class=\"ar\">ظَعَنَ</b> , (S, Msb, K,) aor. <b class=\"ar\">ظَعَنَ</b> , (Msb, K,) inf. n. <span class=\"ar\">ظَعْنٌ</span> (S, Msb, K) and <span class=\"ar\"> <span class=\"ar\">ظَعَنٌ</span></span>, (S, K,) or the latter is a simple subst., (Msb,) and <span class=\"ar\">ظُعُونٌ</span> (TA) [and <span class=\"ar\">مَظْعَنٌ</span>, occurring in a verse of Zuheyr cited in art. <span class=\"ar\">بلو</span>, conj. 3], <i>He journeyed, went away, departed,</i> (S, * Msb, K, * TA,) or <i>removed;</i> (Msb;) <i>he journeyed to seek after herbage,</i> or <i>to water;</i> or <i>he removed from water to water,</i> or <i>from one country,</i> or <i>tract of land, to another.</i> (TA. [See also the part. n., <span class=\"ar\">ظَاعِنٌ</span>.]) -b2- <span class=\"ar\">ظَعَنَ بِهِ</span>: see what next follows.</p><p><b>4.</b> <b class=\"ar\">اظعنهُ</b> <i>He made him to journey, go away, depart,</i> (S, Msb, K,) or <i>remove;</i> and <span class=\"ar\"> <span class=\"ar\">ظَعَنَ</span>بِهِ</span> signifies the same [or <i>he journeyed,</i> &amp;c., <i>with him</i>]. (Msb.)</p><p><b>8.</b> <b class=\"ar\">اِظَّعَنَتْهُ</b> <i>She rode him,</i> (S, K, TA,) namely, a camel: you say, <span class=\"ar\">هٰذَا بَعِيرٌ تَظَّعِنُهُ المَرْأَةُ</span> <i>This is a camel that the woman rides</i> (S, TA) <i>in her journeying,</i> and <i>in the day of her departure.</i> (TA.)</p><p><b class=\"ar\">ظَعَنٌ</b> : see 1: -A2- and see also <span class=\"ar\">ظَاعِنٌ</span>.</p><p><b class=\"ar\">ظُعْنَةٌ</b> <i>A short journey.</i> (TA.)</p><p><b class=\"ar\">ظِعْنَةٌ</b> <i>A state</i> or <i>condition,</i> or <i>a mode</i> or <i>manner, of journeying</i> or <i>departing.</i> (TA.)</p><p><b class=\"ar\">ظِعَانٌ</b> <i>A rope with which a</i> <span class=\"ar\">هَوْدَج</span> [or <i>woman's camel-vehicle</i>] <i>is bound;</i> (S, K;) or <i>with which a load is bound,</i> accord. to the T: and <span class=\"ar\"> <span class=\"ar\">ظَعُونٌ</span></span> signifies the same. (TA.)</p><p><b class=\"ar\">ظَعُونٌ</b> A camel <i>used for work and for bearing burdens:</i> (S, K, TA:) or, as some say, peculiarly, [like <span class=\"ar\">ظَعِينَةٌ</span>,] a camel <i>that is ridden by a woman.</i> (TA.) -A2- See also <span class=\"ar\">ظِعَانٌ</span>.</p><p><b class=\"ar\">ظَعِينَةٌ</b> <i>A</i> <span class=\"ar\">هَوْدَج</span> [or <i>woman's camel-vehicle</i>] (S, Mgh, Msb, K, TA) <i>in which is a woman,</i> (TA,) or <i>whether there be in it a woman or not:</i> (S, Msb, K, TA:) this is [said to be] the primary signification: (Mgh:) pl. <span class=\"ar\">ظَعَائِنُ</span> and <span class=\"ar\">ظُعُنٌ</span> (S, Mgh, Msb, K) and <span class=\"ar\">ظُعْنٌ</span> (S, K) and [pl. of pauc.] <span class=\"ar\">أَظْعَانٌ</span> (S, Mgh, K) and pl. pl. <span class=\"ar\">ظُعُنَاتٌ</span>. (TA. [But see, in what follows, an assertion of AZ respecting the pl. <span class=\"ar\">ظُعُنٌ</span>.]) -b2- And <i>A woman,</i> (ISk, Mgh, Msb, TA;) <i>whether in a</i> <span class=\"ar\">هَوْدَج</span> <i>or elsewhere;</i> (ISk, TA;) the word being used in the sense of <span class=\"ar\">مَظْعُونَةٌ</span> [for <span class=\"ar\">مَظْعُونٌ بِهَا</span>]; because her husband journeys (<span class=\"ar\">يَظْعَنُ</span>) with her: (Msb:) or a man's <i>wife;</i> because she journeys with her husband: (TA:) or a <i>woman as long as she is in the</i> <span class=\"ar\">هودج</span>; (S, Msb, K;) when not in it she is not thus called: (S:) or this is the primary meaning: then it was applied to her though in her tent, because she might become <span class=\"ar\">مَظْعُونَة</span> [i. e. <span class=\"ar\">مَظْعُون بِهَا</span>]: (Msb:) it is mostly applied to <i>a woman riding</i> [<i>in a</i> <span class=\"ar\">هودج</span>]: then, to <i>a</i> <span class=\"ar\">هودج</span> <i>without a woman:</i> and to <i>a woman without a</i> <span class=\"ar\">هودج</span>. (TA.) 'Amr Ibn-Kulthoom says, <span class=\"ar\">قِفِى قَبْلَ التَّفَرُّقِ يَا ظَعِينَا</span> <span class=\"ar\">نُخَبِّرْكِ اليَقِينَ وَتُخْبِرِينَا</span> [<i>Pause thou before separation, O woman in the</i> <i>camel-vehicle: we will inform thee of the real truth</i> respecting our case, <i>and thou shalt inform us</i> respecting thy case]: (S:) <span class=\"ar\">يَا ظَعِينَا</span> is for <span class=\"ar\">يَا</span> <span class=\"ar\">ظَعِينَةُ</span>. (EM p. 185.) -b3- And, accord. to Lth, <i>A camel that is ridden by women:</i> [like <span class=\"ar\">ظَعُونٌ</span>:] and applied to signify <i>a woman</i> because she rides it: or, accord. to IAmb, <i>a camel upon which one journeys:</i> and hence the trad., <span class=\"ar\">لَيْسَ</span> <span class=\"ar\">فِى جَمَلٍ ظَعِينَةٍ صَدَقَةٌ</span> i. e. [<i>There is no poor-rate in the case of</i>] <i>the camel upon which one journeys;</i> if the phrase be thus: but if it be <span class=\"ar\">فِى جَمَلِ ظَعِينَةٍ</span>, by the last word is meant a woman: (TA:) AZ says, one should not say <span class=\"ar\">حُمُولٌ</span> nor <span class=\"ar\">ظُعُنٌ</span> except as meaning the <i>camels upon which are</i> <span class=\"ar\">هَوَادِج</span>, <i>whether there be in them women</i> or <i>not.</i> (S.)</p><p><b class=\"ar\">ظَاعِنٌ</b> <i>Journeying, going away, departing,</i> or <i>removing:</i> (Msb:) [<i>a traveller:</i>] any one <i>going forth on a journey, on pilgrimage,</i> or <i>on a warring and plundering expedition,</i> or <i>journeying from one city</i> [or <i>town</i> &amp;c.] <i>to another: contr. of</i> <span class=\"ar\">خَافِضٌ</span> [and <i>of</i> <span class=\"ar\">مُقِيمٌ</span>]: one says, <span class=\"ar\">أَظَاعِنٌ أَنْتَ</span> <span class=\"ar\">أَمْ مُقِيمٌ</span> [<i>Art thou journeying</i> or <i>abiding?</i>]: the pl. is <span class=\"ar\">ظَاعِنُونَ</span> and <span class=\"ar\">ظُعُنٌ</span>, and <span class=\"ar\"> <span class=\"ar\">ظَعَنٌ</span></span> is a quasipl. n. syn. with <span class=\"ar\">ظَاعِنُونَ</span>. (TA.)</p><p><b class=\"ar\">مِظْعَانٌ</b> , applied to a horse or mare, and to a she-camel, <i>Easy in pace.</i> (TA.)</p><p><b class=\"ar\">مَظْعُونٌ</b> <i>Made to journey, go away, depart,</i> or <i>remove;</i> originally <span class=\"ar\">مَظْعُونٌ بِهِ</span>; the complement being suppressed because of frequency of usage. (Msb.)</p>"}});
